ar.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to a child (e.g. the inner OrigamToolbar)."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.app_bar.exposed.css", "descriptionFallback": "Reactive CSS string from useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.app_bar.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.app_bar.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.app_bar.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.app_bar.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "flat", "labelKey": "components.app_bar.playground.flat", "defaultValue": false, "labelFallback": "Flat (no shadow)"}, {"kind": "switch", "prop": "collapse", "labelKey": "components.app_bar.playground.collapse", "defaultValue": false, "labelFallback": "Collapsed"}, {"kind": "select", "prop": "scrollBehavior", "options": [{"label": "(none)", "value": ""}, {"label": "hide", "value": "hide"}, {"label": "elevate", "value": "elevate"}, {"label": "collapse", "value": "collapse"}, {"label": "active", "value": "active"}], "labelKey": "components.app_bar.playground.scroll_behavior", "defaultValue": "", "labelFallback": "Scroll behaviour"}], "defaultSlotContent": "My Application"}, "previewVariants": [{"label": "default", "props": {"color": "primary"}, "slotContent": "My Application"}, {"label": "flat", "props": {"flat": true}, "slotContent": "Flat AppBar"}, {"label": "collapse", "props": {"collapse": true}, "slotContent": "Collapsed"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
