ss_vars.day_cell_height", "descriptionFallback": "Month-view day cell height."}, {"name": "--origam-calendar__day-cell---bg-color-today", "defaultValue": "{color.action.primary.bgSubtle}", "descriptionKey": "components.calendar.css_vars.today_bg", "descriptionFallback": "Background of today''s cell."}, {"name": "--origam-calendar__day-cell---bg-color-weekend", "defaultValue": "{color.surface.sunken}", "descriptionKey": "components.calendar.css_vars.weekend_bg", "descriptionFallback": "Background of weekend cells when weekendHighlight=true."}, {"name": "--origam-calendar__event---bg-color-default", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.calendar.css_vars.event_bg", "descriptionFallback": "Default event chip background."}, {"name": "--origam-calendar__toolbar---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.calendar.css_vars.toolbar_bg", "descriptionFallback": "Toolbar background."}, {"name": "--origam-calendar__timeline---slot-height", "defaultValue": "32px", "descriptionKey": "components.calendar.css_vars.slot_height", "descriptionFallback": "Height per timeline slot row (proportional to slotDuration)."}], "exposed": [{"name": "visibleDateRange", "type": "ComputedRef<{ start: Date; end: Date }>", "descriptionKey": "components.calendar.exposed.visible_date_range", "descriptionFallback": "Start and end Date of the currently rendered period (useful for fetching remote events)."}, {"name": "expandedEvents", "type": "ComputedRef<IEvent[]>", "descriptionKey": "components.calendar.exposed.expanded_events", "descriptionFallback": "Events after recurring expansion within the visible date range."}, {"name": "navigate", "type": "(direction: TCalendarNavigate) => void", "descriptionKey": "components.calendar.exposed.navigate", "descriptionFallback": "Programmatically navigate: \"prev\", \"next\" or \"today\"."}, {"name": "setView", "type": "(view: TCalendarView) => void", "descriptionKey": "components.calendar.exposed.set_view", "descriptionFallback": "Programmatically switch the view mode."}], "playground": {"controls": [{"kind": "select", "prop": "view", "options": [{"label": "month", "value": "month"}, {"label": "week", "value": "week"}, {"label": "day", "value": "day"}, {"label": "agenda", "value": "agenda"}], "labelKey": "components.calendar.playground.view", "defaultValue": "month", "labelFallback": "View"}, {"kind": "select", "prop": "firstDayOfWeek", "options": [{"label": "Monday (1)", "value": 1}, {"label": "Sunday (0)", "value": 0}], "labelKey": "components.calendar.playground.first_day_of_week", "defaultValue": 1, "labelFallback": "First day of week"}, {"kind": "switch", "prop": "weekendHighlight", "labelKey": "components.calendar.playground.weekend_highlight", "defaultValue": true, "labelFallback": "Weekend highlight"}, {"kind": "switch", "prop": "showWeekNumbers", "labelKey": "components.calendar.playground.show_week_numbers", "defaultValue": false, "labelFallback": "Week numbers"}, {"kind": "switch", "prop": "selectable", "labelKey": "components.calendar.playground.selectable", "defaultValue": true, "labelFallback": "Drag-select"}, {"kind": "select", "prop": "timeFormat", "options": [{"label": "24h", "value": "24h"}, {"label": "12h", "value": "12h"}], "labelKey": "components.calendar.playground.time_format", "defaultValue": "24h", "labelFallback": "Time format"}]}, "previewVariants": [{"label": "month view", "props": {"view": "month"}}, {"label": "week view", "props": {"view": "week"}}, {"label": "agenda view", "props": {"view": "agenda"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a23bbb6c-7a4c-434b-9461-a0d61a7c844e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'card', 'Card', 'Surface', NULL, 'mdi-card-outline', 'components.catalog.card.description', 'Versatile surface container with title, subtitle, image asset, text body, footer slots, link support, loading states and ripple interaction.', NULL, NULL, 'origam-card', NULL, 'packages/ds/src/components/Card/OrigamCard.vue', 'origam', NULL, NULL, '/stories/?story=components-card--design', '/docs/components/Card/OrigamCard.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.card.a11y.disabled_tabindex", "noteFallback": "When disabled=true, tabindex=\"-1\" is set to remove the card from the tab order."}, {"noteKey": "components.card.a11y.link_semantics", "noteFallback": "When href or to is set, the card root renders as <a> with proper link semantics. The ripple v-ripple directive triggers on the native click event."}, {"noteKey": "components.card.a11y.focus_visible", "noteFallback": "Focus-visible outline is applied via :focus-visible in the component SCSS — visible for keyboard navigation, not mouse clicks."}, {"noteKey": "components.card.a11y.overlay_hidden", "noteFallback": "The __overlay and __underlay spans are aria-hidden (inert layers)."}, {"noteKey": "components.card.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to ensure accessible foreground/background contrast when color is set."}, {"noteKey": "components.card.a11y.loader", "noteFallback": "The OrigamProgress inside the loader slot has role=\"progressbar\". OrigamSkeleton is aria-hidden (decorative)."}], "roles": ["article", "link", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.card.a11y.key_tab", "actionFallback": "Moves focus to the card when it is interactive (link=true or href/to is set)."}, {"key": "Enter / Space", "actionKey": "components.card.a11y.key_activate", "actionFallback": "Activates the card link or click handler when focused."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-card---background", "descriptionKey": "components.card.tokens.background", "descriptionFallback": "Card background."}, {"type": "shadow", "value": "var(--origam-shadow---sm)", "tokenPath": "--origam-card---box-shadow", "descriptionKey": "components.card.tokens.box_shadow", "descriptionFallback": "Default elevation shadow."}, {"type": "shadow", "value": "var(--origam-shadow---lg)", "tokenPath": "--origam-card---box-shadow-hover", "descriptionKey": "components.card.tokens.box_shadow_hover", "descriptionFallback": "Hover elevation shadow for interactive cards."}, {"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-card---transition-duration", "descriptionKey": "components.card.tokens.transition_duration", "descriptionFallback": "Transition duration for shadow and opacity."}, {"type": "number", "value": "var(--origam-opacity---0)", "tokenPath": "--origam-card__overlay---opacity", "descriptionKey": "components.card.tokens.overlay_opacity", "descriptionFallback": "Resting overlay opacity (0 = invisible)."}, {"type": "number", "value": "var(--origam-opacity---12)", "tokenPath": "--origam-card---overlay-opacity-hover", "descriptionKey": "components.card.tokens.overlay_opacity_hover", "descriptionFallback": "Overlay opacity on hover (12%)."}, {"type": "number", "value": "var(--origam-opacity---60)", "tokenPath": "--origam-card---opacity-disabled", "descriptionKey": "components.card.tokens.opacity_disabled", "descriptionFallback": "Card