"600\" height=\"25\" rx=\"0\" fill=\"var(--origam-color__surface---sunken, rgba(124,58,237,0.03))\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.15))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"293\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__footer (#footer slot)</text>\n  <rect x=\"50\" y=\"20\" width=\"600\" height=\"280\" rx=\"8\" fill=\"var(--origam-color__overlay---scrim, rgba(0,0,0,0.04))\" stroke=\"none\" opacity=\"0\" class=\"origam-card__overlay\"/>\n  <circle cx=\"52\" cy=\"22\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"52\" y=\"26\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"64\" cy=\"22\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"64\" y=\"26\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"52\" cy=\"107\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"52\" y=\"111\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"52\" cy=\"192\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"52\" y=\"196\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"52\" cy=\"277\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"52\" y=\"281\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "legend": [{"cls": ".origam-card", "num": 1, "descriptionKey": "components.card.anatomy.root", "descriptionFallback": "Root element. Defaults to <div>; becomes <a> when href/to is set. Carries color, shadow, rounded and density classes."}, {"cls": ".origam-card__overlay", "num": 2, "descriptionKey": "components.card.anatomy.overlay", "descriptionFallback": "Absolute scrim. opacity: 0 → overlay-opacity-hover on hover when the card is clickable. Driven by --origam-card__overlay---opacity."}, {"cls": ".origam-card__header", "num": 3, "descriptionKey": "components.card.anatomy.header", "descriptionFallback": "OrigamCardHeader. Rendered only when title, subtitle or prepend/append slots are populated."}, {"cls": ".origam-card__asset", "num": 4, "descriptionKey": "components.card.anatomy.asset", "descriptionFallback": "Image container rendered when the image prop or #asset slot is present. Contains <origam-img cover> by default."}, {"cls": ".origam-card__content", "num": 5, "descriptionKey": "components.card.anatomy.content", "descriptionFallback": "Main content wrapper. Contains OrigamCardText (if text prop is set) and the #default slot."}, {"cls": ".origam-card__text", "num": 6, "descriptionKey": "components.card.anatomy.text", "descriptionFallback": "OrigamCardText — density-aware padding wrapper around the text prop value."}, {"cls": ".origam-card__footer", "num": 7, "descriptionKey": "components.card.anatomy.footer", "descriptionFallback": "<div> rendered only when the #footer slot is populated. Typically contains action buttons."}, {"cls": ".origam-card__loader", "num": 8, "descriptionKey": "components.card.anatomy.loader", "descriptionFallback": "Loading overlay rendered when loading prop is set. Contains skeleton, progress-linear or progress-circular."}], "svgDesc": "Schematic of the Card component with 8 numbered internal parts.", "svgTitle": "Anatomy of OrigamCard", "rootClass": "origam-card", "figcaption": "Anatomy of <code>&lt;origam-card&gt;</code> — 5 visible parts: root ①, header ②, asset ③, content ④, footer ⑤. Two absolute layers (overlay for hover scrim and underlay) sit above the root.", "svgViewBox": "0 0 700 320"}, "cssVars": [{"name": "--origam-card---background", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.card.css_vars.background", "descriptionFallback": "Card