dary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Jan</text>\n  <text x=\"370\" y=\"196\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Feb</text>\n  <text x=\"540\" y=\"196\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Mar</text>\n  <circle cx=\"68\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"68\" cy=\"180\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"68\" y=\"184\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"370\" cy=\"100\" r=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"370\" y=\"104\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"200\" cy=\"196\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"200\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<!-- OrigamChartAxis renders inside the parent chart SVG -->\n<g class=\"origam-chart-axis\">\n  <!-- horizontal grid lines (one per Y tick) -->\n  <line class=\"origam-chart-axis__grid\" />\n  <!-- Y axis vertical line -->\n  <line class=\"origam-chart-axis__y-axis\" />\n  <!-- X axis horizontal line -->\n  <line class=\"origam-chart-axis__x-axis\" />\n  <!-- tick labels for X and Y -->\n  <text class=\"origam-chart-axis__tick-label\" />\n</g>", "legend": [{"cls": ".origam-chart-axis__y-axis", "num": 1, "descriptionKey": "components.chart_axis.anatomy.y_axis", "descriptionFallback": "Left vertical axis line. Hidden when showAxis=false."}, {"cls": ".origam-chart-axis__x-axis", "num": 2, "descriptionKey": "components.chart_axis.anatomy.x_axis", "descriptionFallback": "Bottom horizontal axis line. Hidden when showAxis=false."}, {"cls": ".origam-chart-axis__grid", "num": 3, "descriptionKey": "components.chart_axis.anatomy.grid", "descriptionFallback": "Horizontal grid lines aligned with Y-axis ticks. Hidden when showGrid=false."}, {"cls": ".origam-chart-axis__tick-label", "num": 4, "descriptionKey": "components.chart_axis.anatomy.tick_label", "descriptionFallback": "X and Y axis tick labels formatted by xAxisFormat / yAxisFormat."}], "classes": [{"cls": "origam-chart-axis", "descriptionKey": "components.chart_axis.anatomy.root", "descriptionFallback": "Root SVG group element wrapping all axis chrome."}, {"cls": "origam-chart-axis__y-axis", "descriptionKey": "components.chart_axis.anatomy.y_axis", "descriptionFallback": "Left Y-axis line."}, {"cls": "origam-chart-axis__x-axis", "descriptionKey": "components.chart_axis.anatomy.x_axis", "descriptionFallback": "Bottom X-axis line."}, {"cls": "origam-chart-axis__grid", "descriptionKey": "components.chart_axis.anatomy.grid", "descriptionFallback": "Horizontal grid lines."}, {"cls": "origam-chart-axis__tick-label", "descriptionKey": "components.chart_axis.anatomy.tick_label", "descriptionFallback": "Axis tick label text elements."}], "svgDesc": "Schematic showing X axis, Y axis, grid lines and tick labels.", "svgTitle": "Anatomy of OrigamChartAxis", "rootClass": "origam-chart-axis", "figcaption": "Anatomy of <code>&lt;origam-chart-axis&gt;</code> — 4 visible regions: Y axis line ①, X axis line ②, horizontal grid lines ③, and tick labels ④.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-chart__axis---color", "defaultValue": "{color.border.default}", "descriptionKey": "components.chart_axis.css_vars.axis_color", "descriptionFallback": "Axis line colour."}, {"name": "--origam-chart__axis__label---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.chart_axis.css_vars.label_color", "descriptionFallback": "Tick label text colour."}, {"name": "--origam-chart__axis__label---font-size", "defaultValue": "{font.size.xs}", "descriptionKey": "components.chart_axis.css_vars.label_font_size", "descriptionFallback": "Tick label font size."}, {"name": "--origam-chart__grid---color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.chart_axis.css_vars.grid_color", "descriptionFallback": "Grid line colour."}, {"name": "--origam-chart__grid---stroke-width", "defaultValue": "1px", "descriptionKey": "components.chart_axis.css_vars.grid_stroke_width", "descriptionFallback": "Grid line stroke width."}], "playground": {"controls": [{"kind": "switch", "prop": "showAxis", "labelKey": "components.chart_axis.playground.show_axis", "defaultValue": true, "labelFallback": "Show Axis"}, {"kind": "switch", "prop": "showGrid", "labelKey": "components.chart_axis.playground.show_grid", "defaultValue": true, "labelFallback": "Show Grid"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
