xt x=\"240\" y=\"175\" font-size=\"18\" fill=\"var(--origam-color__text---primary,#1e1b4b)\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"sans-serif\">72%</text>\n  <circle cx=\"200\" cy=\"165\" r=\"8\" fill=\"var(--origam-color__action--primary---bg,#7c3aed)\"/>\n  <text x=\"200\" y=\"169\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"108\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---secondary,#6b7280)\" text-anchor=\"middle\" font-family=\"sans-serif\">0</text>\n  <text x=\"372\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---secondary,#6b7280)\" text-anchor=\"middle\" font-family=\"sans-serif\">100</text>\n  <circle cx=\"108\" cy=\"188\" r=\"7\" fill=\"var(--origam-color__action--primary---bg,#a855f7)\"/>\n  <text x=\"108\" y=\"192\" font-size=\"7\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "legend": [{"cls": ".origam-chart-gauge__header", "num": 1, "descriptionKey": "components.chart_gauge.anatomy.header", "descriptionFallback": "Header block. Contains title and subtitle divs."}, {"cls": ".origam-chart-gauge__body", "num": 2, "descriptionKey": "components.chart_gauge.anatomy.body", "descriptionFallback": "Body container. Wraps the SVG and empty-state overlay."}, {"cls": ".origam-chart__gauge-track", "num": 3, "descriptionKey": "components.chart_gauge.anatomy.track", "descriptionFallback": "Background arc path — always full 270 degrees."}, {"cls": ".origam-chart__gauge-fill", "num": 4, "descriptionKey": "components.chart_gauge.anatomy.fill", "descriptionFallback": "Foreground arc path — length proportional to value ratio."}, {"cls": ".origam-chart__gauge-value", "num": 5, "descriptionKey": "components.chart_gauge.anatomy.value", "descriptionFallback": "Centre value label. Hidden when gaugeShowValue=false."}, {"cls": ".origam-chart__gauge-endpoint (min/max)", "num": 6, "descriptionKey": "components.chart_gauge.anatomy.endpoints", "descriptionFallback": "Min and max labels at arc endpoints. Hidden when gaugeShowEndpoints=false."}], "svgDesc": "Schematic of the gauge chart component with numbered internal parts.", "svgTitle": "Anatomy of OrigamChartGauge", "rootClass": "origam-chart-gauge", "figcaption": "Anatomy of <code>&lt;origam-chart-gauge&gt;</code> — 6 internal parts.", "svgViewBox": "0 0 480 260"}, "cssVars": [{"name": "--origam-chart---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.chart_gauge.css_vars.background_color", "descriptionFallback": "Chart root background colour."}, {"name": "--origam-chart---padding", "defaultValue": "{space.3}", "descriptionKey": "components.chart_gauge.css_vars.padding", "descriptionFallback": "Inner padding of the chart root."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_gauge.css_vars.animation_duration", "descriptionFallback": "Duration of the fill arc animation."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.chart_gauge.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_gauge.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "gaugeShowEndpoints", "labelKey": "components.chart_gauge.playground.gauge_show_endpoints", "defaultValue": true, "labelFallback": "Gauge Show Endpoints"}, {"kind": "switch", "prop": "gaugeShowValue", "labelKey": "components.chart_gauge.playground.gauge_show_value", "defaultValue": true, "labelFallback": "Gauge Show Value"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart_gauge.playground.animated", "defaultValue": true, "labelFallback": "Animated"}, {"kind": "select", "prop": "colorScheme", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "