INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5eff6741-883a-43af-b3e9-ece15758d2d5', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'chart-polar-bar', 'ChartPolarBar', 'Data Display', NULL, 'mdi-chart-donut-variant', 'components.catalog.chart_polar_bar.description', 'Nightingale-rose (polar bar) chart. N data points are rendered as radial wedges each occupying an equal angular slice; outer radius is proportional to value. Ideal for cyclical data such as hours per day or monthly activity.', NULL, NULL, 'origam-chart-polar-bar', NULL, 'packages/ds/src/components/Chart/OrigamChartPolarBar.vue', 'origam', NULL, NULL, '/stories/?story=components-chart-polar-bar--design', '/docs/components/Chart/OrigamChartPolarBar.html', 'chart-polar', '{"a11y": {"notes": [{"noteKey": "components.chart_polar_bar.a11y.root_figure", "noteFallback": "Root div carries role=\"figure\" and aria-label from the title prop (or \"Polar bar chart\")."}, {"noteKey": "components.chart_polar_bar.a11y.svg_img", "noteFallback": "Inner SVG has role=\"img\" with <title> and <desc> elements summarising the data."}, {"noteKey": "components.chart_polar_bar.a11y.wedge_label", "noteFallback": "Each wedge <path> has aria-label with category, value, percentage and series name."}, {"noteKey": "components.chart_polar_bar.a11y.reduced_motion", "noteFallback": "All CSS animations are disabled under prefers-reduced-motion: reduce."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_polar_bar.a11y.key_tab", "actionFallback": "Moves focus between focusable wedges (tabindex=\"0\" on each <path>)