=\"64\" width=\"660\" height=\"168\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, #e5e7eb)\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"40\" y=\"78\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" font-family=\"''JetBrains Mono'',monospace\">__body ③</text>\n  <g transform=\"translate(350,148)\">\n    <path d=\"M0,-60 A60,60 0 0,1 58,-17 L29,-8 A30,30 0 0,0 0,-30 Z\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.9\"/>\n    <path d=\"M58,-17 A60,60 0 0,1 36,50 L18,25 A30,30 0 0,0 29,-8 Z\" fill=\"var(--origam-color__action--info---bg, #0ea5e9)\" opacity=\"0.9\"/>\n    <path d=\"M36,50 A60,60 0 0,1 -36,50 L-18,25 A30,30 0 0,0 18,25 Z\" fill=\"var(--origam-color__action--success---bg, #22c55e)\" opacity=\"0.9\"/>\n    <path d=\"M-36,50 A60,60 0 0,1 -58,-17 L-29,-8 A30,30 0 0,0 -18,25 Z\" fill=\"var(--origam-color__action--warning---bg, #f59e0b)\" opacity=\"0.9\"/>\n    <path d=\"M-58,-17 A60,60 0 0,1 0,-60 L0,-30 A30,30 0 0,0 -29,-8 Z\" fill=\"var(--origam-color__action--danger---bg, #ef4444)\" opacity=\"0.9\"/>\n    <circle cx=\"0\" cy=\"0\" r=\"5\" fill=\"var(--origam-color__surface---raised, #fff)\"/>\n  </g>\n  <text x=\"465\" y=\"100\" font-size=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">origam-chart__polar-bar-wedge ④</text>\n  <text x=\"465\" y=\"114\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" font-family=\"''JetBrains Mono'',monospace\">--active modifier on hover</text>\n  <text x=\"465\" y=\"132\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" font-family=\"''JetBrains Mono'',monospace\">__polar-bar-category-label ⑤</text>\n  <text x=\"465\" y=\"146\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" font-family=\"''JetBrains Mono'',monospace\">__polar-bar-value-label ⑥</text>\n  <rect x=\"200\" y=\"248\" width=\"300\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__surface---sunken, #f3f4f6)\" stroke=\"var(--origam-color__border---default, #e5e7eb)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"259\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #6b7280)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-chart-legend</text>\n", "code": "<div class=\"origam-chart-polar-bar\">\n  <div class=\"origam-chart-polar-bar__header\">\n    <slot name=\"title\" />\n  </div>\n  <div class=\"origam-chart-polar-bar__body\">\n    <svg class=\"origam-chart-polar-bar__svg origam-chart__svg\" role=\"img\">\n      <title /><desc />\n      <g class=\"origam-chart__series\" :transform=\"translateCenter\">\n        <path class=\"origam-chart__polar-bar-wedge\" role=\"button\" tabindex=\"0\" />\n        <text class=\"origam-chart__polar-bar-category-label\" />\n        <text class=\"origam-chart__polar-bar-value-label\" />\n      </g>\n    </svg>\n    <origam-chart-tooltip />\n    <div class=\"origam-chart-polar-bar__empty origam-chart__empty\">\n      <slot name=\"empty\" />\n    </div>\n  </div>\n  <origam-chart-legend />\n</div>", "legend": [{"cls": ".origam-chart-polar-bar", "num": 1, "descriptionKey": "components.chart_polar_bar.anatomy.root", "descriptionFallback": "Root wrapper. CSS grid: header / body / legend rows."}, {"cls": ".origam-chart-polar-bar__header", "num": 2, "descriptionKey": "components.chart_polar_bar.anatomy.header", "descriptionFallback": "Optional title + subtitle block."}, {"cls": ".origam-chart-polar-bar__body", "num": 3, "descriptionKey": "components.chart_polar_bar.anatomy.body", "descriptionFallback": "Plot area containing the SVG and empty-state slot."}, {"cls": ".origam-chart__polar-bar-wedge", "num": 4, "descriptionKey": "components.chart_polar_bar.anatomy.wedge", "descriptionFallback": "SVG <path> arc for one data point. Keyboard-focusable (role=\"button\", tabindex=\"0\"). Gets --active modifier on hover."}, {"cls": ".origam-chart__polar-bar-category-label", "num": 5, "descriptionKey": "components.chart_polar_bar.anatomy.category_label", "descriptionFallback": "Category text anchored outside the outer radius. text-anchor driven by wedge midpoint quadrant."}, {"cls": ".origam-chart__polar-bar-value-label", "num": 6, "descriptionKey": "components.chart_polar_bar.anatomy.value_label", "descriptionFallback": "Optional numeric value label inside the wedge. Hidden when angular space is insufficient (showValueLabel flag)."}], "classes": [{"cls": "origam-chart-polar-bar", "descriptionKey": "components.chart_polar_bar.anatomy.root", "descriptionFallback": "Root grid wrapper."}, {"cls": "origam-chart-polar-bar__header", "descriptionKey": "components.chart_polar_bar.anatomy.header", "descriptionFallback": "Title/subtitle block."}, {"cls": "origam-chart-polar-bar__body", "descriptionKey": "components.chart_polar_bar.anatomy.body", "descriptionFallback": "Plot area."}, {"cls": "origam-chart-polar-bar__svg", "descriptionKey": "components.chart_polar_bar.anatomy.svg", "descriptionFallback": "Square SVG (viewBox NxN)."}, {"cls": "origam-chart__polar-bar-wedge", "descriptionKey": "components.chart_polar_bar.anatomy.wedge", "descriptionFallback": "Arc wedge <path>."}, {"cls": "origam-chart__polar-bar-wedge--active", "descriptionKey": "components.chart_polar_bar.anatomy.wedge_active", "descriptionFallback": "Added on hover / keyboard focus."}, {"cls": "origam-chart__polar-bar-category-label", "descriptionKey": "components.chart_polar_bar.anatomy.category_label", "descriptionFallback": "Outer category text."}, {"cls": "origam-chart__polar-bar-value-label", "descriptionKey": "components.chart_polar_bar.anatomy.value_label", "descriptionFallback": "Inner value text."}, {"cls": "origam-chart-polar-bar__empty", "descriptionKey": "components.chart_polar_bar.anatomy.empty", "descriptionFallback": "Empty-state overlay."}], "svgDesc": "Schematic of the ChartPolarBar component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamChartPolarBar", "rootClass": "origam-chart-polar-bar", "figcaption": "Anatomy of <code>&lt;origam-chart-polar-bar&gt;</code> — 6 internal parts. Wedges ④ are SVG <code>&lt;path&gt;</code> elements inside a centred <code>&lt;g&gt;</code>. Category labels ⑤ and optional value labels ⑥ float outside / inside the outer radius.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-chart---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.chart_polar_bar.css_vars.background_color", "descriptionFallback": "Background colour of the chart wrapper."}, {"name": "--origam-chart---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.chart_polar_bar.css_vars.color", "descriptionFallback": "Default text colour (inherited by category labels)."}, {"name": "--origam-chart---padding", "defaultValue": "{space.3}", "descriptionKey": "components.chart_polar_bar.css_vars.padding", "descriptionFallback": "Inner padding of the root wrapper."}, {"name": "--origam-chart---gap", "defaultValue": "{space.3}", "descriptionKey": "components.chart_polar_bar.css_vars.gap", "descriptionFallback": "Grid gap between header / body / legend rows."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_polar_bar.css_vars.animation_duration", "descriptionFallback": "Wedge animation duration. Set via animationDuration prop."}, {"name": "--origam-chart__tooltip---background-color", "defaultValue": "{color.surface.inverse}", "descriptionKey": "components.chart_polar_bar.css_vars.tooltip_bg", "descriptionFallback": "Tooltip background colour."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_polar_bar.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_polar_bar.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_polar_bar.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "showLabel", "labelKey": "components.chart_polar_bar.playground.show_label", "defaultValue": true, "labelFallback": "Show Label"}, {"kind": "switch", "prop": "showValue", "labelKey": "components.chart_polar_bar.playground.show_value", "defaultValue": false, "labelFallback": "Show Value"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_polar_bar.playground.show_legend", "defaultValue": true, "labelFallback": "Show Legend"}, {"kind": "switch", "prop": "showTooltip", "labelKey": "components.chart_polar_bar.playground.show_tooltip", "defaultValue": true, "labelFallback": "Show Tooltip"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart_polar_bar.playground.animated", "defaultValue": true, "labelFallback": "Animated"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
