INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e0bb2667-0591-4d57-958f-d6c4ec63c433', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'list-item', 'ListItem', 'Data Display', NULL, 'mdi-format-list-bulleted', 'components.catalog.list_item.description', 'Single row inside a List. Supports prepend/append icons or avatars, title, subtitle, active state, and polymorphic link rendering.', NULL, NULL, 'origam-list-item', NULL, 'packages/ds/src/components/List/OrigamListItem.vue', 'origam', NULL, NULL, '/stories/?story=components-list-item--design', '/docs/components/List/OrigamListItem.html', 'list', '{"a11y": {"notes": [{"noteKey": "components.list_item.a11y.disabled_note", "noteFallback": "When disabled=true and rendered as an anchor, aria-disabled=\"true\" is set instead of the disabled attribute. Pointer events are removed via CSS."}, {"noteKey": "components.list_item.a11y.link_note", "noteFallback": "When href or to is set, the item renders as a native <a> element — full keyboard navigation and focus management are inherited from the browser."}, {"noteKey": "components.list_item.a11y.selection_note", "noteFallback": "When inside a selectable list (value prop set), selection state is driven by useNestedItem. The active CSS class provides a visual selected indicator."}], "roles": [], "keyboard": [{"key": "Enter / Space", "actionKey": "components.list_item.a11y.key_activate", "actionFallback": "Activates a clickable item (fires click event, navigates, or toggles selection)."}, {"key": "Tab", "actionKey": "components.list_item.a11y.key_tab", "actionFallback": "Moves focus. tabindex=0 for standalone clickable items; tabindex=-2 inside a list group."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "56px", "tokenPath": "--origam-list__item---min-height", "descriptionKey": "components.list_item.tokens.min_height", "descriptionFallback": "Default minimum row height."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-list-item---padding-inline-start", "descriptionKey": "components.list_item.tokens.padding_inline_start", "descriptionFallback": "Default inline-start padding (16px). Added to list indent-padding and density."}, {"type": "color", "value": "currentColor", "tokenPath": "--origam-list__item---overlay-background-color", "descriptionKey": "components.list_item.tokens.overlay_background_color", "descriptionFallback": "Overlay tint color for hover/active states."}, {"type": "dimension", "value": "var(--origam-font__size---lg)", "tokenPath": "--origam-list__item---title-font-size", "descriptionKey": "components.list_item.tokens.title_font_size", "descriptionFallback": "Title font size (1rem)."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-list__item---subtitle-font-size", "descriptionKey": "components.list_item.tokens.subtitle_font_size", "descriptionFallback": "Subtitle font size (0.875rem)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.6\"/>\n  <rect x=\"32\" y=\"42\" width=\"56\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"60\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prepend</text>\n  <rect x=\"100\" y=\"42\" width=\"416\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"108\" y=\"50\" width=\"248\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\"/>\n  <text x=\"232\" y=\"62\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">title</text>\n  <rect x=\"108\" y=\"74\" width=\"180\" height=\"12\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"198\" y=\"84\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">subtitle</text>\n  <rect x=\"528\" y=\"42\" width=\"140\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"598\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append</text>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"none\"/>\n  <rect x=\"20\" y=\"110\" width=\"660\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.12))\"/>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"60\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"60\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"308\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"308\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"232\" cy=\"46\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"232\" y=\"50\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"198\" cy=\"70\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"198\" y=\"74\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"598\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"598\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"28\" cy=\"108\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"28\" y=\"112\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <line x1=\"38\" y1=\"36\" x2=\"90\" y2=\"18\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"20\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-list-item</text>\n  <text x=\"350\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">⑦ = overlay — absolute, opacity: 0 at rest, visible on hover/active</text>\n", "legend": [{"cls": ".origam-list-item", "num": 1, "descriptionKey": "components.list_item.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;div&gt;</code> by default, <code>&lt;a&gt;</code> when href/to is set. Grid container: 3 columns (prepend / content / append)."}, {"cls": ".origam-list-item__prepend", "num": 2, "descriptionKey": "components.list_item.anatomy.prepend", "descriptionFallback": "Leading icon/avatar zone. <code>grid-area: prepend</code>. Renders <code>prependIcon</code>, <code>prependAvatar</code>, or the <code>#prepend</code> slot. <code>v-if=\"hasPrepend\"</code>."}, {"cls": ".origam-list-item__content", "num": 3, "descriptionKey": "components.list_item.anatomy.content", "descriptionFallback": "<code>grid-area: content</code>. Contains title, subtitle and the <code>#default</code> slot."}, {"cls": ".origam-list-item__title", "num": 4, "descriptionKey": "components.list_item.anatomy.title", "descriptionFallback": "Primary text. Truncates with ellipsis (white-space: nowrap). <code>v-if=\"hasTitle\"</code>."}, {"cls": ".origam-list-item__subtitle", "num": 5, "descriptionKey": "components.list_item.anatomy.subtitle", "descriptionFallback": "Secondary text. Uses <code>-webkit-box</code> clamp via the <code>lines</code> prop. <code>v-if=\"hasSubtitle\"</code>."}, {"cls": ".origam-list-item__append", "num": 6, "descriptionKey": "components.list_item.anatomy.append", "descriptionFallback": "Trailing icon/avatar zone. <code>grid-area: append</code>. Renders <code>appendIcon</code>, <code>appendAvatar</code>, or the <code>#append</code> slot. <code>v-if=\"hasAppend\"</code>."}, {"cls": ".origam-list-item__overlay", "num": 7, "descriptionKey": "components.list_item.anatomy.overlay", "descriptionFallback": "Absolute interaction scrim. <code>opacity: 0</code> at rest → 0.08 on hover/focus → 0.12 when active. Only rendered when the item is clickable or active."}], "svgDesc": "Schematic of the ListItem component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamListItem", "rootClass": "origam-list-item", "figcaption": "Anatomy of <code>&lt;origam-list-item&gt;</code> — 7 internal parts. The grid layout places prepend ② / content ③ / append ⑥ in a 3-column grid. Title ④ and subtitle ⑤ live inside content. The overlay ⑦ is an absolute layer that paints hover/active tints.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-list-item---min-height", "defaultValue": "40px", "descriptionKey": "components.list_item.css_vars.min_height", "descriptionFallback": "Minimum row height. Adjusted by the density modifier."}, {"name": "--origam-list-item---padding-block-start", "defaultValue": "8px", "descriptionKey": "components.list_item.css_vars.padding_block_start", "descriptionFallback": "Block-start padding. Added to the density offset."}, {"name": "--origam-list-item---padding-inline-start", "defaultValue": "16px", "descriptionKey": "components.list_item.css_vars.padding_inline_start", "descriptionFallback": "Inline-start padding. Added to the indent-padding and density offsets."}, {"name": "--origam-list-item---border-radius", "defaultValue": "0px", "descriptionKey": "components.list_item.css_vars.border_radius", "descriptionFallback": "Item border radius. Overridden by the rounded prop."}, {"name": "--origam-list-item---cursor", "defaultValue": "pointer", "descriptionKey": "components.list_item.css_vars.cursor", "descriptionFallback": "Cursor style when the item is in link/clickable mode."}, {"name": "--origam-list-item---opacity", "defaultValue": "0.6", "descriptionKey": "components.list_item.css_vars.opacity", "descriptionFallback": "Opacity applied when the item is disabled."}, {"name": "--origam-list-item__overlay---opacity", "defaultValue": "0", "descriptionKey": "components.list_item.css_vars.overlay_opacity", "descriptionFallback": "Overlay opacity. Animates to 0.08 on hover/focus and 0.12 when active."}, {"name": "--origam-list-item__title---font-size", "defaultValue": "1rem", "descriptionKey": "components.list_item.css_vars.title_font_size", "descriptionFallback": "Title font size. Overridden to 0.8125rem in nav mode."}, {"name": "--origam-list-item__subtitle---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.list_item.css_vars.subtitle_font_size", "descriptionFallback": "Subtitle font size."}], "exposed": [{"name": "isGroupActivator", "type": "boolean", "descriptionKey": "components.list_item.exposed.is_group_activator", "descriptionFallback": "True when this item acts as the activator of a ListGroup. Prevents selection toggling on click."}, {"name": "isSelected", "type": "Ref<boolean>", "descriptionKey": "components.list_item.exposed.is_selected", "descriptionFallback": "Reactive selection state from useNestedItem. True when the item value is selected in the parent list."}, {"name": "list", "type": "ListProvide | null", "descriptionKey": "components.list_item.exposed.list", "descriptionFallback": "Parent list context injected by OrigamList. Null when the item is used standalone."}, {"name": "select", "type": "(value: boolean, event?: Event) => void", "descriptionKey": "components.list_item.exposed.select", "descriptionFallback": "Programmatically select or deselect this item within the parent list."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed listItemStyles."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_item.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.list_item.playground.title", "defaultValue": "List item", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.list_item.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-inbox", "value": "mdi-inbox"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-home", "value": "mdi-home"}], "labelKey": "components.list_item.playground.prepend_icon", "defaultValue": "mdi-inbox", "labelFallback": "Prepend icon"}, {"kind": "select", "prop": "lines", "options": [{"label": "(default)", "value": ""}, {"label": "one-line", "value": "one-line"}, {"label": "two-line", "value": "two-line"}, {"label": "three-line", "value": "three-line"}], "labelKey": "components.list_item.playground.lines", "defaultValue": "", "labelFallback": "Lines"}, {"kind": "switch", "prop": "active", "labelKey": "components.list_item.playground.active", "defaultValue": false, "labelFallback": "Active"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.list_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "simple", "props": {"title": "Inbox", "prependIcon": "mdi-inbox"}}, {"label": "subtitle", "props": {"title": "John Doe", "subtitle": "john.doe@example.com", "prependIcon": "mdi-account"}}, {"label": "active", "props": {"title": "Active", "active": true, "prependIcon": "mdi-star"}}, {"label": "disabled", "props": {"title": "Disabled", "disabled": true, "prependIcon": "mdi-lock"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
