", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chip.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "select", "prop": "size", "options": [{"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.chip.playground.size", "defaultValue": "default", "labelFallback": "Size"}, {"kind": "switch", "prop": "closable", "labelKey": "components.chip.playground.closable", "defaultValue": false, "labelFallback": "Closable"}, {"kind": "switch", "prop": "label", "labelKey": "components.chip.playground.label", "defaultValue": false, "labelFallback": "Label shape"}, {"kind": "switch", "prop": "border", "labelKey": "components.chip.playground.border", "defaultValue": false, "labelFallback": "Border"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-tag", "value": "mdi-tag"}], "labelKey": "components.chip.playground.prepend_icon", "defaultValue": "", "labelFallback": "Prepend icon"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.chip.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": "Design"}, "previewVariants": [{"label": "default", "props": {}, "slotContent": "Design"}, {"label": "primary", "props": {"color": "primary"}, "slotContent": "Frontend"}, {"label": "success", "props": {"color": "success", "prependIcon": "mdi-check"}, "slotContent": "Done"}, {"label": "closable", "props": {"color": "danger", "closable": true}, "slotContent": "Remove"}, {"label": "outlined", "props": {"border": true}, "slotContent": "Outlined"}, {"label": "label", "props": {"color": "warning", "label": true}, "slotContent": "Label"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0fdf812a-f1c8-437b-8250-3f20f38c3279', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'chip-group', 'ChipGroup', 'Data Display', NULL, 'mdi-label-multiple-outline', 'components.catalog.chip_group.description', 'Scrollable group of Chip elements with single or multi-select, filter support, and column layout option. Propagates color/bgColor tokens to descendant chips via OrigamDefaultsProvider.', NULL, NULL, 'origam-chip-group', NULL, 'packages/ds/src/components/Chip/OrigamChipGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-chipgroup--design', '/docs/components/Chip/OrigamChipGroup.html', 'chip', '{"a11y": {"notes": [{"noteKey": "components.chip_group.a11y.group_role", "noteFallback": "The slide group container exposes a logical grouping of selectable chip controls. Each chip carries its own role and aria-selected."}, {"noteKey": "components.chip_group.a11y.defaults_propagation", "noteFallback": "Color tokens are propagated via OrigamDefaultsProvider — children that set their own color still take precedence over the group defaults."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.chip_group.a11y.key_tab", "actionFallback": "Moves focus between chips inside the group."}, {"key": "Enter / Space", "actionKey": "components.chip_group.a11y.key_activate", "actionFallback": "Selects or deselects the focused chip."}, {"key": "Arrow Left / Right", "actionKey": "components.chip_group.a11y.key_arrows", "actionFallback": "Scrolls the slide group when overflow is present (handled by OrigamSlideGroup)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-chip---background-color", "descriptionKey": "components.chip_group.tokens.chip_bg", "descriptionFallback": "Default chip background (propagated to children)."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-chip--selected---background-color", "descriptionKey": "components.chip_group.tokens.chip_selected_bg", "descriptionFallback": "Background of the selected chip state."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-chip---border-radius", "descriptionKey": "components.chip_group.tokens.chip_radius", "descriptionFallback": "Chip border radius."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-chip---transition-duration", "descriptionKey": "components.chip_group.tokens.transition_duration", "descriptionFallback": "Chip transition duration (hover, selection)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"24\" width=\"668\" height=\"100\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"16\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-chip-group ①</text>\n  <rect x=\"32\" y=\"36\" width=\"636\" height=\"76\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"100\" y=\"56\" font-size=\"8.5\" fill=\"var(--origam-color__text---secondary, #6b7280)\" font-family=\"''JetBrains Mono'',monospace\">origam-slide-group ②</text>\n  <rect x=\"48\" y=\"64\" width=\"80\" height=\"32\" rx=\"16\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"88\" y=\"83\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"sans-serif\">Vue ✓</text>\n  <rect x=\"140\" y=\"64\" width=\"100\" height=\"32\" rx=\"16\" fill=\"var(--origam-color__surface---overlay, #f3f4f6)\" stroke=\"var(--origam-color__border---default, #e5e7eb)\" stroke-width=\"1\"/>\n  <text x=\"190\" y=\"83\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #111827)\" text-anchor=\"middle\" font-family=\"sans-serif\">TypeScript</text>\n  <rect x=\"252\" y=\"64\" width=\"72\" height=\"32\" rx=\"16\" fill=\"var(--origam-color__surface---overlay, #f3f4f6)\" stroke=\"var(--origam-color__border---default, #e5e7eb)\" stroke-width=\"1\"/>\n  <text x=\"288\" y=\"83\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #111827)\" text-anchor=\"middle\" font-family=\"sans-serif\">CSS</text>\n  <text x=\"48\" y=\"110\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" font-family=\"''JetBrains Mono'',monospace\">origam-chip ③ (slot default)</text>\n  <text x=\"350\" y=\"148\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"sans-serif\">OrigamDefaultsProvider propagates color/bgColor to chip children ④</text>\n", "code": "<origam-slide-group class=\"origam-chip-group origam-chip-group--column?\">\n  <origam-defaults-provider :defaults=\"slotDefaults\">\n    <slot :is-selected=\"isSelected\" :select=\"select\" :next=\"next\" :prev=\"prev\" :selected=\"selected\" />\n  </origam-defaults-provider>\n</origam-slide-group>", "legend": [{"cls": ".origam-chip-group", "num": 1, "descriptionKey": "components.chip_group.anatomy.root", "descriptionFallback": "Root element. BEM modifier --column switches to a wrapping grid layout."}, {"cls": "origam-slide-group", "num": 2, "descriptionKey": "components.chip_group.anatomy.slide_group", "descriptionFallback": "Horizontal scrollable container with prev/next navigation buttons. Receives filtered SlideGroup props."}, {"cls": "origam-chip (slot children)", "num": 3, "descriptionKey": "components.chip_group.anatomy.chip", "descriptionFallback": "Child chip elements provided via the default slot. Receive selection state from the group context (ORIGAM_CHIP_GROUP_KEY)."}, {"cls": "origam-defaults-provider", "num": 4, "descriptionKey": "components.chip_group.anatomy.defaults_provider", "descriptionFallback": "Injects default color, bgColor and other visual props into all descendant origam-chip elements."}], "classes": [{"cls": "origam-chip-group", "descriptionKey": "components.chip_group.anatomy.root", "descriptionFallback": "Root BEM class."}, {"cls": "origam-chip-group--column", "descriptionKey": "components.chip_group.anatomy.column_modifier", "descriptionFallback": "Added when column=true. Switches layout to a wrapping column grid."}], "svgDesc": "Schematic of the ChipGroup component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamChipGroup", "rootClass": "origam-chip-group", "figcaption": "Anatomy of <code>&lt;origam-chip-group&gt;</code> — 4 internal parts. The root ① wraps a <code>origam-slide-group</code> ② which contains chip children ③. An <code>origam-defaults-provider</code> ④ propagates visual token props to all descendant chips.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-chip---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.chip_group.css_vars.chip_bg", "descriptionFallback": "Default chip background propagated to all chips in the group."}, {"name": "--origam-chip---border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.chip_group.css_vars.chip_radius", "descriptionFallback": "Chip border radius (pill by default)."}, {"name": "--origam-chip--selected---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.chip_group.css_vars.chip_selected_bg", "descriptionFallback": "Selected chip background colour."}, {"name": "--origam-chip--selected---color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.chip_group.css_vars.chip_selected_color", "descriptionFallback": "Selected chip foreground colour."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.chip_group.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.chip_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.chip_group.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.chip_group.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.chip_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.chip_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.chip_group.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.chip_group.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "filter", "labelKey": "components.chip_group.playground.filter", "defaultValue": false, "labelFallback": "Filter mode"}, {"kind": "switch", "prop": "column", "labelKey": "components.chip_group.playground.column", "defaultValue": false, "labelFallback": "Column layout"}]}, "previewVariants": [{"label": "default", "props": {}, "slotContent": "Group"}, {"label": "with color", "props": {"color": "primary"}, "slotContent": "Colored"}, {"label": "filter", "props": {"filter": true}, "slotContent": "Filter"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('973c0c4b-9afb-40bf-9c75-8e42850995a2', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'class-icon', 'ClassIcon', 'Media', NULL, 'mdi-format-color-fill', 'components.catalog.class_icon.description', 'Renders a CSS class-based icon (e.g. MDI font) by applying the icon string as a class on the root element.', NULL, NULL, 'origam-class-icon', NULL, 'packages/ds/src/components/Icon/OrigamClassIcon.vue', 'origam', NULL, NULL, '/stories/?story=components-icon--design', '/docs/components/Icon/OrigamIcon.html', 'icon', '{"a11y": {"notes": [{"noteKey": "components.class_icon.a11y.decorative", "noteFallback": "Decorative icons should have aria-hidden=\"true\" on the parent OrigamIcon. When meaningful, pass aria-label on the wrapping interactive element."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"400\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"30\" width=\"80\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"80\" y=\"67\" font-size=\"22\" text-anchor=\"middle\" font-family=\"''Material Design Icons''\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\">★</text>\n  <circle cx=\"48\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"57\" y1=\"38\" x2=\"160\" y2=\"30\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"164\" y=\"33\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-icon</text>\n  <text x=\"164\" y=\"47\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">icon class applied as className</text>\n", "code": "<i class=\"origam-icon mdi mdi-star\" />", "legend": [{"cls": ".origam-icon", "num": 1, "descriptionKey": "components.class_icon.anatomy.root", "descriptionFallback": "Root element (defaults to <code>&lt;i&gt;</code>). The <code>icon</code> prop value is injected as a CSS class, e.g. <code>mdi-star</code>."}], "classes": [{"cls": "origam-icon", "descriptionKey": "components.class_icon.anatomy.root", "descriptionFallback": "Base class applied to the root element. Always present."}, {"cls": "origam-icon--size-{size}", "descriptionKey": "components.class_icon.anatomy.size", "descriptionFallback": "Size modifier when a named TSize token is passed, e.g. origam-icon--size-large."}], "svgDesc": "Schematic of ClassIcon with 1 internal part.", "svgTitle": "Anatomy of OrigamClassIcon", "rootClass": "origam-icon", "figcaption": "Anatomy of <code>&lt;origam-class-icon&gt;</code> — 1 part. The icon string is applied directly as a CSS class on the root <code>&lt;i&gt;</code> element.", "svgViewBox": "0 0 400 120"}, "cssVars": [{"name": "--origam-icon---font-size", "defaultValue": "24px", "descriptionKey": "components.class_icon.css_vars.font_size", "descriptionFallback": "Icon font-size. Overridden per size variant class."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.class_icon.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.class_icon.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.class_icon.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.class_icon.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.class_icon.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.class_icon.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.class_icon.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "size", "options": [{"label": "(default)", "value": ""}, {"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.class_icon.playground.size", "defaultValue": "", "labelFallback": "Size"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.class_icon.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "default", "props": {"icon": "mdi-star"}}, {"label": "large", "props": {"icon": "mdi-heart", "size": "large"}}, {"label": "colored", "props": {"icon": "mdi-check-circle", "size": "large", "color": "success"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('71712245-b808-4005-9daf-254da4a458a9', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'client-only', 'ClientOnly', 'Utilities & Providers', NULL, 'mdi-monitor', 'components.catalog.client_only.description', 'Wrapper that renders its default slot ONLY after hydration on the client. On the server a configurable placeholder element (or the #fallback slot) is rendered instead, preventing hydration mismatches for client-only content.', NULL, NULL, 'origam-client-only', NULL, 'packages/ds/src/components/ClientOnly/OrigamClientOnly.vue', 'origam', NULL, NULL, '/stories/?story=components-clientonly--design', '/docs/components/ClientOnly/OrigamClientOnly.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.client_only.a11y.placeholder_aria", "noteFallback": "The auto-generated placeholder element carries aria-hidden=\"true\" so it is invisible to assistive technologies. Only provide a placeholder that is purely decorative (skeleton, shimmer)."}, {"noteKey": "components.client_only.a11y.fallback_slot", "noteFallback": "If the #fallback slot contains meaningful content (e.g. \"Loading chart…\"), ensure it is visible to screen readers (do not add aria-hidden)."}, {"noteKey": "components.client_only.a11y.ssr_note", "noteFallback": "OrigamClientOnly prevents hydration mismatches for content that relies on browser APIs (window, document, canvas, WebGL). Use it for charts, maps, canvas-based components and anything that reads window dimensions on mount."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"300\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-dasharray=\"6 3\" stroke-width=\"1.5\"/>\n  <text x=\"170\" y=\"44\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\" font-weight=\"600\">SSR (isMounted = false)</text>\n  <rect x=\"40\" y=\"54\" width=\"260\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__feedback--warning---bgSubtle, rgba(180,130,0,0.08))\" stroke=\"var(--origam-color__feedback--warning---border, rgba(180,130,0,0.35))\" stroke-width=\"1\"/>\n  <text x=\"170\" y=\"88\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">#fallback slot (or placeholder tag)</text>\n  <rect x=\"380\" y=\"20\" width=\"300\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"530\" y=\"44\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"sans-serif\" font-weight=\"600\">Client (isMounted = true)</text>\n  <rect x=\"400\" y=\"54\" width=\"260\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__action--primary---bg, rgba(124,58,237,0.35))\" stroke-width=\"1\"/>\n  <text x=\"530\" y=\"88\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a0f3c)\" text-anchor=\"middle\" font-family=\"sans-serif\">#default slot (your content)</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__feedback--warning---fgSubtle, #b45309)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"388\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"388\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<template>\n  <!-- isMounted=false (SSR) → renders fallback/placeholder -->\n  <template v-if=\"isMounted\">\n    <slot />\n  </template>\n  <template v-else>\n    <slot name=\"fallback\">\n      <!-- auto-generated placeholder (aria-hidden) -->\n      <component\n        :is=\"placeholderTag\"\n        v-if=\"placeholderTag\"\n        :class=\"placeholderClass\"\n        aria-hidden=\"true\"\n      />\n    </slot>\n  </template>\n</template>", "legend": [{"cls": "#fallback / placeholderTag", "num": 1, "descriptionKey": "components.client_only.anatomy.fallback", "descriptionFallback": "Rendered on the server and during first client paint. Either the #fallback slot content or a generated <placeholderTag> element (aria-hidden=\"true\")."}, {"cls": "#default", "num": 2, "descriptionKey": "components.client_only.anatomy.default", "descriptionFallback": "Rendered only after onMounted fires on the client (isMounted ref flips to true). Completely absent from SSR output."}], "classes": [], "svgDesc": "Schematic showing the SSR vs client render paths of OrigamClientOnly.", "svgTitle": "Anatomy of OrigamClientOnly", "rootClass": "origam-client-only", "figcaption": "Anatomy of <code>&lt;origam-client-only&gt;</code> — two render paths: server (fallback/placeholder) and client (default slot after <code>onMounted</code>).", "svgViewBox": "0 0 700 160"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('efbd9a6d-1b3d-4918-8ad5-e31ef7ffa11a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'clipboard', 'Clipboard', 'Utilities & Providers', NULL, 'mdi-content-copy', 'components.catalog.clipboard.description', 'Chrome-less copy-to-clipboard wrapper. Owns the navigator.clipboard.writeText pipeline and an auto-resetting "copied" flag. The default trigger is a single icon button; replace it entirely via the default scoped slot.', NULL, NULL, 'origam-clipboard', NULL, 'packages/ds/src/components/Clipboard/OrigamClipboard.vue', 'origam', NULL, NULL, '/stories/?story=components-clipboard--design', '/docs/components/Clipboard/OrigamClipboard.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.clipboard.a11y.aria_label", "noteFallback": "The default trigger carries a dynamic aria-label that changes from \"Copy to clipboard\" to \"Value copied to clipboard\" once copied. Sourced from useLocale for full i18n."}, {"noteKey": "components.clipboard.a11y.aria_live", "noteFallback": "The feedback label has aria-live=\"polite\" so screen readers announce the success state without interrupting the current reading."}, {"noteKey": "components.clipboard.a11y.disabled_note", "noteFallback": "When disabled=true the default trigger has the disabled HTML attribute; the copy() exposed method short-circuits immediately."}, {"noteKey": "components.clipboard.a11y.custom_slot", "noteFallback": "When using a custom #default slot, ensure your trigger element has an appropriate aria-label and keyboard handler (or use origam-btn which handles both)."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.clipboard.a11y.key_tab", "actionFallback": "Moves focus to the default trigger button."}, {"key": "Enter / Space", "actionKey": "components.clipboard.a11y.key_activate", "actionFallback": "Triggers the copy action from the focused default trigger button."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__feedback--success---fgSubtle)", "tokenPath": "--origam-clipboard__feedback---color", "descriptionKey": "components.clipboard.tokens.color", "descriptionFallback": "Text color when copied."}, {"type": "color", "value": "var(--origam-color__feedback--success---bgSubtle)", "tokenPath": "--origam-clipboard__feedback---bg-color", "descriptionKey": "components.clipboard.tokens.bg_color", "descriptionFallback": "Background when copied."}, {"type": "dimension", "value": "var(--origam-font__size---xs)", "tokenPath": "--origam-clipboard__feedback---font-size", "descriptionKey": "components.clipboard.tokens.font_size", "descriptionFallback": "Trigger font size."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-clipboard__feedback---transition-duration", "descriptionKey": "components.clipboard.tokens.transition_duration", "descriptionFallback": "Color/background transition duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"40\" width=\"660\" height=\"100\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"40\" y=\"60\" width=\"100\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__action--primary---bg, rgba(124,58,237,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"90\" y=\"95\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">default-trigger</text>\n  <rect x=\"160\" y=\"60\" width=\"180\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__feedback--success---bgSubtle, rgba(22,163,74,0.06))\" stroke=\"var(--origam-color__feedback--success---border, rgba(22,163,74,0.35))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"250\" y=\"89\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">default-label</text>\n  <text x=\"250\" y=\"104\" font-size=\"9\" fill=\"var(--origam-color__feedback--success---fgSubtle, #16a34a)\" text-anchor=\"middle\" font-family=\"sans-serif\">(visible when copied = true)</text>\n  <circle cx=\"28\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"90\" cy=\"54\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"90\" y=\"58\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"250\" cy=\"54\" r=\"10\" fill=\"var(--origam-color__feedback--success---fgSubtle, #16a34a)\"/>\n  <text x=\"250\" y=\"58\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"165\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② and ③ are the built-in trigger — replaced when #default slot is provided</text>\n", "code": "<!-- root tag is configurable via ''tag'' prop (default: span) -->\n<span class=\"origam-clipboard origam-clipboard--copied\">\n\n  <!-- #default scoped slot (your custom trigger) -->\n  <slot :copy=\"handleCopy\" :copied=\"copied\" :error=\"error\">\n\n    <!-- built-in trigger: rendered only when no slot is provided -->\n    <button\n      type=\"button\"\n      class=\"origam-clipboard__default-trigger\"\n      :disabled=\"disabled\"\n      :aria-label=\"defaultAriaLabel\"\n      @click=\"handleCopy\"\n    >\n      <origam-icon\n        class=\"origam-clipboard__default-icon\"\n        aria-hidden=\"true\"\n      />\n      <!-- feedback label (aria-live=\"polite\") -->\n      <span v-if=\"copied\" class=\"origam-clipboard__default-label\">\n        {{ resolvedFeedbackText }}\n      </span>\n    </button>\n\n  </slot>\n</span>", "legend": [{"cls": ".origam-clipboard", "num": 1, "descriptionKey": "components.clipboard.anatomy.root", "descriptionFallback": "Root element (default tag: span). Carries BEM modifiers --copied and --disabled."}, {"cls": ".origam-clipboard__default-trigger", "num": 2, "descriptionKey": "components.clipboard.anatomy.trigger", "descriptionFallback": "Built-in trigger button (all: unset). Rendered only when no #default slot is provided."}, {"cls": ".origam-clipboard__default-label", "num": 3, "descriptionKey": "components.clipboard.anatomy.label", "descriptionFallback": "Feedback text label (aria-live=\"polite\"). Visible only when copied=true."}, {"cls": ".origam-clipboard__default-icon", "num": 4, "descriptionKey": "components.clipboard.anatomy.icon", "descriptionFallback": "OrigamIcon inside the default trigger. Switches between mdi-content-copy and mdi-check on copy."}], "classes": [{"cls": "origam-clipboard", "descriptionKey": "components.clipboard.anatomy.root", "descriptionFallback": "Root wrapper element."}, {"cls": "origam-clipboard--copied", "descriptionKey": "components.clipboard.anatomy.mod_copied", "descriptionFallback": "BEM modifier present while copied=true."}, {"cls": "origam-clipboard--disabled", "descriptionKey": "components.clipboard.anatomy.mod_disabled", "descriptionFallback": "BEM modifier present while disabled=true. Adds cursor: not-allowed."}, {"cls": "origam-clipboard__default-trigger", "descriptionKey": "components.clipboard.anatomy.trigger", "descriptionFallback": "Built-in copy button (all: unset)."}, {"cls": "origam-clipboard__default-icon", "descriptionKey": "components.clipboard.anatomy.icon", "descriptionFallback": "Icon inside the default trigger."}, {"cls": "origam-clipboard__default-label", "descriptionKey": "components.clipboard.anatomy.label", "descriptionFallback": "Feedback text label (aria-live)."}], "svgDesc": "Schematic of the Clipboard component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamClipboard", "rootClass": "origam-clipboard", "figcaption": "Anatomy of <code>&lt;origam-clipboard&gt;</code> — root wrapper + optional default trigger (button + feedback label).", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-clipboard__feedback---color", "defaultValue": "{color.feedback.success.fgSubtle}", "descriptionKey": "components.clipboard.css_vars.feedback_color", "descriptionFallback": "Text color of the default trigger while copied=true."}, {"name": "--origam-clipboard__feedback---bg-color", "defaultValue": "{color.feedback.success.bgSubtle}", "descriptionKey": "components.clipboard.css_vars.feedback_bg", "descriptionFallback": "Background color of the default trigger while copied=true."}, {"name": "--origam-clipboard__feedback---font-size", "defaultValue": "{font.size.xs}", "descriptionKey": "components.clipboard.css_vars.feedback_font_size", "descriptionFallback": "Font size of the default trigger."}, {"name": "--origam-clipboard__feedback---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.clipboard.css_vars.feedback_border_radius", "descriptionFallback": "Border radius of the default trigger button."}, {"name": "--origam-clipboard__feedback---gap", "defaultValue": "{space.1}", "descriptionKey": "components.clipboard.css_vars.feedback_gap", "descriptionFallback": "Gap between the icon and the feedback label inside the default trigger."}, {"name": "--origam-clipboard__feedback---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.clipboard.css_vars.transition_duration", "descriptionFallback": "Duration of color and background-color transitions."}], "exposed": [{"name": "copy", "type": "() => Promise<boolean>", "descriptionKey": "components.clipboard.exposed.copy", "descriptionFallback": "Triggers the copy pipeline programmatically. Returns true on success."}, {"name": "copied", "type": "Ref<boolean>", "descriptionKey": "components.clipboard.exposed.copied", "descriptionFallback": "Reactive boolean — true for feedbackDuration ms after a successful copy."}, {"name": "error", "type": "Ref<Error | null>", "descriptionKey": "components.clipboard.exposed.error", "descriptionFallback": "Set when the last copy attempt threw an error. Null otherwise."}], "playground": {"controls": [{"kind": "text", "prop": "value", "labelKey": "components.clipboard.playground.value", "defaultValue": "npm install origam", "labelFallback": "Value to copy"}, {"kind": "number", "prop": "feedbackDuration", "labelKey": "components.clipboard.playground.feedback_duration", "defaultValue": 2000, "labelFallback": "Feedback duration (ms)"}, {"kind": "text", "prop": "feedbackText", "labelKey": "components.clipboard.playground.feedback_text", "defaultValue": "Copied!", "labelFallback": "Feedback text"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.clipboard.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d3177154-41d8-4f70-9b4e-e4e1d0047a73', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'code', 'Code', 'Data Display', NULL, 'mdi-code-braces', 'components.catalog.code.description', 'Shiki-powered syntax-highlighted code block with optional line numbers, line highlighting, copy button, filename header, compact pill mode and theme awareness. Supports 14 languages and honours the active Origam theme.', NULL, NULL, 'origam-code', NULL, 'packages/ds/src/components/Code/OrigamCode.vue', 'origam', NULL, NULL, '/stories/?story=components-code--design', '/docs/components/Code/OrigamCode.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.code.a11y.semantic", "noteFallback": "Root element defaults to <figure> for W3C correctness. The code block is rendered inside <pre><code data-lang=\"...\"> which gives screen readers proper semantic context."}, {"noteKey": "components.code.a11y.copy_aria", "noteFallback": "The copy button aria-label and aria-live=\"polite\" are set so screen readers announce \"Copied\" after a successful write without interrupting the current reading."}, {"noteKey": "components.code.a11y.prompt_hidden", "noteFallback": "The prompt prefix (<span aria-hidden=\"true\">) is decorative — it is never read aloud and is never included in the clipboard payload."}, {"noteKey": "components.code.a11y.scrollable", "noteFallback": "The scrollable code area is focusable via keyboard when content overflows, allowing keyboard users to scroll horizontally."}], "roles": ["figure"], "keyboard": [{"key": "Tab", "actionKey": "components.code.a11y.key_tab", "actionFallback": "Moves focus to the copy button when copyable=true."}, {"key": "Enter / Space", "actionKey": "components.code.a11y.key_activate", "actionFallback": "Triggers the copy action on the focused copy button."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-code---background-color", "descriptionKey": "components.code.tokens.bg", "descriptionFallback": "Block background."}, {"type": "dimension", "value": "var(--origam-radius---md)", "tokenPath": "--origam-code---border-radius", "descriptionKey": "components.code.tokens.border_radius", "descriptionFallback": "Corner radius."}, {"type": "fontFamily", "value": "var(--origam-font__family---mono)", "tokenPath": "--origam-code---font-family", "descriptionKey": "components.code.tokens.font_family", "descriptionFallback": "Monospace font stack."}, {"type": "dimension", "value": "var(--origam-font__size---sm)", "tokenPath": "--origam-code---font-size", "descriptionKey": "components.code.tokens.font_size", "descriptionFallback": "Font size."}, {"type": "color", "value": "var(--origam-color__feedback--warning---bgSubtle)", "tokenPath": "--origam-code__line-highlight---background-color", "descriptionKey": "components.code.tokens.line_highlight_bg", "descriptionFallback": "Highlighted line background."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"190\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"36\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.06))\"/>\n  <text x=\"48\" y=\"43\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">App.vue</text>\n  <text x=\"620\" y=\"43\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Copy</text>\n  <rect x=\"20\" y=\"56\" width=\"660\" height=\"120\" rx=\"0\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\"/>\n  <rect x=\"20\" y=\"80\" width=\"660\" height=\"20\" rx=\"0\" fill=\"var(--origam-color__feedback--warning---bgSubtle, rgba(180,130,0,0.12))\"/>\n  <text x=\"60\" y=\"93\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a0f3c)\" font-family=\"''JetBrains Mono'',monospace\">const <tspan fill=\"var(--origam-color__feedback--info---fgSubtle, #0369a1)\">x</tspan> = <tspan fill=\"var(--origam-color__feedback--warning---fgSubtle, #b45309)\">42</tspan></text>\n  <rect x=\"20\" y=\"176\" width=\"660\" height=\"34\" rx=\"0\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.04))\"/>\n  <text x=\"350\" y=\"197\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">#footer slot</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"48\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"620\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"620\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"28\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"350\" cy=\"116\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"120\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"28\" cy=\"176\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"28\" y=\"180\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<figure class=\"origam-code\">\n  <!-- header bar: filename or lang badge + copy button -->\n  <component :is=\"headerTag\" class=\"origam-code__header\">\n    <span class=\"origam-code__filename\">App.vue</span>\n    <origam-btn class=\"origam-code__copy origam-code__copy--header\" />\n  </component>\n\n  <!-- floating copy button (no header) -->\n  <origam-btn class=\"origam-code__copy origam-code__copy--floating\" />\n\n  <!-- shell prompt prefix (compact only) -->\n  <span class=\"origam-code__prompt\" aria-hidden=\"true\">$</span>\n\n  <!-- scrollable code area -->\n  <div class=\"origam-code__scroller\">\n    <pre class=\"origam-code__pre\">\n      <code ref=\"codeRef\" class=\"origam-code__code\" data-lang=\"ts\" />\n    </pre>\n  </div>\n\n  <!-- compact inline copy button -->\n  <origam-btn class=\"origam-code__copy origam-code__copy--compact\" />\n\n  <!-- footer slot -->\n  <footer class=\"origam-code__footer\">\n    <slot name=\"footer\" />\n  </footer>\n</figure>", "legend": [{"cls": ".origam-code", "num": 1, "descriptionKey": "components.code.anatomy.root", "descriptionFallback": "Root element (default tag: <figure>). Carries display, background, border, font-family and overflow tokens."}, {"cls": ".origam-code__header", "num": 2, "descriptionKey": "components.code.anatomy.header", "descriptionFallback": "Header bar rendered when filename is set. Contains the filename badge or lang badge and the copy button."}, {"cls": ".origam-code__copy", "num": 3, "descriptionKey": "components.code.anatomy.copy", "descriptionFallback": "OrigamBtn copy button. Positioned in the header (--header), floating top-right (--floating) or inline in compact mode (--compact)."}, {"cls": ".origam-code__scroller", "num": 4, "descriptionKey": "components.code.anatomy.scroller", "descriptionFallback": "Scrollable area wrapping the <pre><code> pair. flex: 1 1 auto in non-compact mode so it fills a constrained height."}, {"cls": ".origam-code__pre / .origam-code__code", "num": 5, "descriptionKey": "components.code.anatomy.pre", "descriptionFallback": "<pre><code> semantic pair. The <code> element carries data-lang and receives the shiki-highlighted innerHTML."}, {"cls": ".origam-code__footer", "num": 6, "descriptionKey": "components.code.anatomy.footer", "descriptionFallback": "<footer> wrapper for the #footer slot. Only rendered when the footer slot is provided."}], "classes": [{"cls": "origam-code", "descriptionKey": "components.code.anatomy.root", "descriptionFallback": "Root figure element."}, {"cls": "origam-code--compact", "descriptionKey": "components.code.anatomy.mod_compact", "descriptionFallback": "BEM modifier for compact pill mode. Switches display to inline-flex."}, {"cls": "origam-code__header", "descriptionKey": "components.code.anatomy.header", "descriptionFallback": "Header bar with filename/lang and copy button."}, {"cls": "origam-code__filename", "descriptionKey": "components.code.anatomy.filename", "descriptionFallback": "Filename badge in the header."}, {"cls": "origam-code__lang-badge", "descriptionKey": "components.code.anatomy.lang_badge", "descriptionFallback": "Language badge in the header when no filename is set."}, {"cls": "origam-code__copy", "descriptionKey": "components.code.anatomy.copy", "descriptionFallback": "Copy button (variants: --header, --floating, --compact)."}, {"cls": "origam-code__scroller", "descriptionKey": "components.code.anatomy.scroller", "descriptionFallback": "Overflow-x: auto scroll container."}, {"cls": "origam-code__pre", "descriptionKey": "components.code.anatomy.pre", "descriptionFallback": "<pre> element. Margin 0, white-space: pre."}, {"cls": "origam-code__code", "descriptionKey": "components.code.anatomy.code", "descriptionFallback": "<code> element receiving shiki innerHTML."}, {"cls": "origam-code__row", "descriptionKey": "components.code.anatomy.row", "descriptionFallback": "One line row. Used for line numbers (CSS counter) and line highlighting."}, {"cls": "origam-code__prompt", "descriptionKey": "components.code.anatomy.prompt", "descriptionFallback": "Decorative shell prompt prefix (aria-hidden)."}, {"cls": "origam-code__footer", "descriptionKey": "components.code.anatomy.footer", "descriptionFallback": "<footer> element for the #footer slot."}], "svgDesc": "Schematic of the Code component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamCode", "rootClass": "origam-code", "figcaption": "Anatomy of <code>&lt;origam-code&gt;</code> — 6 internal parts. Root is <code>&lt;figure&gt;</code> for W3C correctness.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-code---background-color", "defaultValue": "{color.surface.sunken}", "descriptionKey": "components.code.css_vars.bg", "descriptionFallback": "Code block background colour."}, {"name": "--origam-code---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.code.css_vars.color", "descriptionFallback": "Default foreground colour for non-highlighted tokens."}, {"name": "--origam-code---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.code.css_vars.border_radius", "descriptionFallback": "Border radius."}, {"name": "--origam-code---font-family", "defaultValue": "{font.family.mono}", "descriptionKey": "components.code.css_vars.font_family", "descriptionFallback": "Monospace font stack."}, {"name": "--origam-code---font-size", "defaultValue": "{font.size.sm}", "descriptionKey": "components.code.css_vars.font_size", "descriptionFallback": "Font size."}, {"name": "--origam-code---line-height", "defaultValue": "1.6", "descriptionKey": "components.code.css_vars.line_height", "descriptionFallback": "Line height of code rows."}, {"name": "--origam-code---padding-block", "defaultValue": "{space.4}", "descriptionKey": "components.code.css_vars.padding_block", "descriptionFallback": "Vertical padding inside the code surface."}, {"name": "--origam-code---padding-inline", "defaultValue": "{space.4}", "descriptionKey": "components.code.css_vars.padding_inline", "descriptionFallback": "Horizontal padding inside the code surface."}, {"name": "--origam-code__header---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.code.css_vars.header_bg", "descriptionFallback": "Header bar background."}, {"name": "--origam-code__line-highlight---background-color", "defaultValue": "{color.feedback.warning.bgSubtle}", "descriptionKey": "components.code.css_vars.line_highlight_bg", "descriptionFallback": "Background of highlighted lines."}], "exposed": [{"name": "rebuild", "type": "() => void", "descriptionKey": "components.code.exposed.rebuild", "descriptionFallback": "Force re-highlights the code. Useful when the theme changes or the code prop is mutated without Vue reactivity."}, {"name": "copied", "type": "Ref<boolean>", "descriptionKey": "components.code.exposed.copied", "descriptionFallback": "True for feedbackDuration ms after a successful copy."}, {"name": "codeRef", "type": "Ref<HTMLElement | undefined>", "descriptionKey": "components.code.exposed.code_ref", "descriptionFallback": "Template ref pointing to the inner <code> element. Useful for external syntax processing or DOM inspection."}], "composable": {"name": "useCode", "signature": "interface IUseCodeReturn {\n  highlight(code: string, lang: TCodeLang): Promise<string>\n  prime(): Promise<void>\n  isReady(): boolean\n  resetCacheForTesting(): void\n}\n\nfunction useCode(): IUseCodeReturn", "usageCode": "<script setup lang=\"ts\">\nimport { useCode } from ''origam''\n\nconst { highlight, prime, isReady } = useCode()\n\n// Warm the cache before component mount\nawait prime()\n\nconst html = await highlight(''const x = 42'', ''ts'')\n</script>", "importPath": "import { useCode } from ''origam''", "descriptionKey": "components.code.composable.description", "descriptionFallback": "Lazily instantiates a shiki highlighter singleton on first call and reuses it across every OrigamCode instance. Exposes highlight(), prime(), isReady() and resetCacheForTesting()."}, "playground": {"controls": [{"kind": "select", "prop": "lang", "options": [{"label": "plaintext", "value": "plaintext"}, {"label": "vue", "value": "vue"}, {"label": "ts", "value": "ts"}, {"label": "js", "value": "js"}, {"label": "scss", "value": "scss"}, {"label": "css", "value": "css"}, {"label": "json", "value": "json"}, {"label": "bash", "value": "bash"}, {"label": "html", "value": "html"}], "labelKey": "components.code.playground.lang", "defaultValue": "ts", "labelFallback": "Language"}, {"kind": "switch", "prop": "lineNumbers", "labelKey": "components.code.playground.line_numbers", "defaultValue": false, "labelFallback": "Line numbers"}, {"kind": "switch", "prop": "copyable", "labelKey": "components.code.playground.copyable", "defaultValue": true, "labelFallback": "Copyable"}, {"kind": "switch", "prop": "compact", "labelKey": "components.code.playground.compact", "defaultValue": false, "labelFallback": "Compact"}, {"kind": "switch", "prop": "wrap", "labelKey": "components.code.playground.wrap", "defaultValue": false, "labelFallback": "Wrap lines"}]}, "previewVariants": [{"label": "default", "props": {"code": "const x: number = 42", "lang": "ts", "copyable": true}, "slotContent": ""}, {"label": "compact", "props": {"code": "npm install origam", "lang": "bash", "prompt": "$", "compact": true}, "slotContent": ""}, {"label": "with filename", "props": {"code": "<origam-btn />", "lang": "vue", "filename": "App.vue"}, "slotContent": ""}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('57c7ab8e-0d94-478d-aad9-5446636f3ad5', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'col', 'Col', 'Layout & Structure', NULL, 'mdi-view-column-outline', 'components.catalog.col.description', 'Responsive flex column that spans 1–12 grid tracks. Supports per-breakpoint span, offset, order and alignment overrides via props.', NULL, NULL, 'origam-col', NULL, 'packages/ds/src/components/Grids/OrigamCol.vue', 'origam', NULL, NULL, '/stories/?story=components-grids--design', '/docs/components/Grids/OrigamGrids.html', 'grids', '{"a11y": {"notes": [{"noteKey": "components.col.a11y.semantic", "noteFallback": "Col renders as <div> by default. Use the tag prop to render a semantic element (e.g. <article>, <section>) when appropriate for the content."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"500\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"460\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"30\" width=\"440\" height=\"60\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"250\" y=\"64\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"37\" y1=\"28\" x2=\"70\" y2=\"12\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"74\" y=\"14\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-col</text>\n", "code": "<div class=\"origam-col origam-col--6 origam-col--md-4\">\n  <slot name=\"default\" />\n</div>", "legend": [{"cls": ".origam-col", "num": 1, "descriptionKey": "components.col.anatomy.root", "descriptionFallback": "Root element (defaults to <code>&lt;div&gt;</code>). Responsive modifiers such as <code>origam-col--6</code>, <code>origam-col--md-4</code> and <code>origam-col--offset-2</code> are generated from props."}], "classes": [{"cls": "origam-col", "descriptionKey": "components.col.anatomy.root", "descriptionFallback": "Base flex column class."}, {"cls": "origam-col--{n}", "descriptionKey": "components.col.anatomy.size", "descriptionFallback": "Column span modifier (1–12 or auto)."}, {"cls": "origam-col--{bp}-{n}", "descriptionKey": "components.col.anatomy.breakpoint_size", "descriptionFallback": "Breakpoint-specific span modifier, e.g. origam-col--md-6."}, {"cls": "origam-col--offset-{n}", "descriptionKey": "components.col.anatomy.offset", "descriptionFallback": "Left-margin offset in columns."}, {"cls": "origam-col--align-{value}", "descriptionKey": "components.col.anatomy.align", "descriptionFallback": "align-self override (start, end, center, baseline, stretch)."}, {"cls": "origam-col--order-{value}", "descriptionKey": "components.col.anatomy.order", "descriptionFallback": "CSS order override (0–12, first, last)."}], "svgDesc": "Schematic of Col with root and content slot.", "svgTitle": "Anatomy of OrigamCol", "rootClass": "origam-col", "figcaption": "Anatomy of <code>&lt;origam-col&gt;</code> — 1 root element with a default slot. BEM size/offset/order modifiers are generated dynamically from props.", "svgViewBox": "0 0 500 120"}, "cssVars": [{"name": "--origam-col---width", "defaultValue": "100%", "descriptionKey": "components.col.css_vars.width", "descriptionFallback": "Default column width before breakpoint modifiers are applied."}, {"name": "--origam-col---flex-basis", "defaultValue": "0", "descriptionKey": "components.col.css_vars.flex_basis", "descriptionFallback": "Flex basis. Overridden per span modifier to calc(100% / (12 / n))."}, {"name": "--origam-col---flex-grow", "defaultValue": "1", "descriptionKey": "components.col.css_vars.flex_grow", "descriptionFallback": "flex-grow value. Set to 0 for auto columns."}, {"name": "--origam-col---padding-inline-start", "defaultValue": "12px", "descriptionKey": "components.col.css_vars.padding_inline_start", "descriptionFallback": "Horizontal gutter — start side. Matches the Row gutter half-width."}, {"name": "--origam-col---padding-inline-end", "defaultValue": "12px", "descriptionKey": "components.col.css_vars.padding_inline_end", "descriptionFallback": "Horizontal gutter — end side."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.col.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.col.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.col.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.col.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.col.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.col.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.col.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.col.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
