INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('25f6bcd5-d0ad-42ac-ba2e-d6bdbc67c165', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'data-table-row', 'DataTableRow', 'Data Display', NULL, 'mdi-table-row', 'components.catalog.data_table_row.description', 'Single data row (<tr>) in a DataTable. Renders each column cell, handles row selection, expand toggle, and switches to mobile stacked layout below the breakpoint.', NULL, NULL, 'origam-data-table-row', NULL, 'packages/ds/src/components/DataTable/OrigamDataTableRow.vue', 'origam', NULL, NULL, '/stories/?story=components-datatable--design', '/docs/components/DataTable/OrigamDataTable.html', 'data-table', '{"a11y": {"notes": [{"noteKey": "components.data_table_row.a11y.aria_selected", "noteFallback": "<code>aria-selected</code> is set on the <code>&lt;tr&gt;</code> when the selection column is present. It is omitted (undefined) for non-selectable rows."}, {"noteKey": "components.data_table_row.a11y.aria_rowindex", "noteFallback": "<code>aria-rowindex</code> is set by the parent DataTableRows component on each row (startIndex + index + 2, 1-based, accounting for the header row)."}, {"noteKey": "components.data_table_row.a11y.expand_button", "noteFallback": "The expand button exposes <code>aria-expanded</code> (true/false) and a localised <code>aria-label</code> via the DS i18n provider (keys: origam.dataTableRow.collapseRow / expandRow)."}], "roles": ["row"], "keyboard": [{"key": "Space", "actionKey": "components.data_table_row.a11y.key_select", "actionFallback": "Toggles row selection via the CheckboxBtn (when the selection column is present)."}, {"key": "Enter", "actionKey": "components.data_table_row.a11y.key_expand", "actionFallback": "Toggles row expansion via the expand Btn (when the expand column is present)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-data-table-row---background-color", "descriptionKey": "components.data_table_row.tokens.background_color", "descriptionFallback": "Default row background."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-data-table__row---hover-background-color", "descriptionKey": "components.data_table_row.tokens.hover_background_color", "descriptionFallback": "Row background on hover."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-data-table-row---transition-duration", "descriptionKey": "components.data_table_row.tokens.transition_duration", "descriptionFallback": "Row background transition duration."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-data-table-row__column-title---font-weight", "descriptionKey": "components.data_table_row.tokens.column_title_font_weight", "descriptionFallback": "Column label weight in mobile stacked layout."}, {"type": "dimension", "value": "52px", "tokenPath": "--origam-data-table__row---mobile-column-min-height", "descriptionKey": "components.data_table_row.tokens.mobile_column_min_height", "descriptionFallback": "Minimum cell height in mobile stacked layout."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"24\" width=\"528\" height=\"48\" rx=\"0\" fill=\"var(--origam-color__surface---default, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"16\" y=\"72\" width=\"528\" height=\"1\" fill=\"var(--origam-color__border---subtle, rgba(168,85,247,0.2))\"/>\n  <rect x=\"28\" y=\"32\" width=\"32\" height=\"32\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"44\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">☑</text>\n  <rect x=\"70\" y=\"32\" width=\"160\" height=\"32\" rx=\"2\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"150\" y=\"52\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">column value</text>\n  <rect x=\"238\" y=\"32\" width=\"160\" height=\"32\" rx=\"2\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"318\" y=\"52\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">column value</text>\n  <rect x=\"406\" y=\"32\" width=\"32\" height=\"32\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"422\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">⌄</text>\n  <circle cx=\"24\" cy=\"32\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"24\" y=\"36\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"30\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"30\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"76\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"76\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"412\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"412\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"33\" y1=\"32\" x2=\"300\" y2=\"10\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"304\" y=\"13\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-data-table-row</text>\n", "code": "<tr class=\"origam-data-table-row\" :aria-selected=\"isSelected([item]) || undefined\">\n  <!-- select column -->\n  <origam-data-table-column-cell class=\"origam-data-table-row__column origam-data-table-row__column--select-row\">\n    <origam-checkbox-btn :model-value=\"isSelected([item])\" @click=\"toggleSelect(item)\" />\n  </origam-data-table-column-cell>\n  <!-- data columns -->\n  <origam-data-table-column-cell v-for=\"column in columns\" class=\"origam-data-table-row__column\">\n    <!-- mobile: show column title + value -->\n    <div class=\"origam-data-table-row__column-title\">{{ column.title }}</div>\n    <div class=\"origam-data-table-row__column-value\">\n      <slot :name=\"`item.${column.key}`\">{{ displayValue }}</slot>\n    </div>\n  </origam-data-table-column-cell>\n  <!-- expand column -->\n  <origam-data-table-column-cell class=\"origam-data-table-row__column origam-data-table-row__column--expanded-row\">\n    <origam-btn :icon=\"isExpanded(item) ? MDI_ICONS.CHEVRON_UP : MDI_ICONS.CHEVRON_DOWN\" @click=\"toggleExpand(item)\" />\n  </origam-data-table-column-cell>\n</tr>", "legend": [{"cls": ".origam-data-table-row", "num": 1,