INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('de087bf8-8cca-428b-a465-110626309f49', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'date-picker', 'DatePicker', 'Form & Input', NULL, 'mdi-calendar', 'components.catalog.date_picker.description', 'Calendar popup to select a single date, multiple dates or a range. Supports month and year navigation with animated view transitions.', NULL, NULL, 'origam-date-picker', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePicker.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/DatePicker/OrigamDatePicker.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.date_picker.a11y.grid_note", "noteFallback": "The day grid uses role=\"grid\" with role=\"gridcell\" for each day. Disabled days have aria-disabled=\"true\" and are skipped in keyboard navigation."}, {"noteKey": "components.date_picker.a11y.label_note", "noteFallback": "Each day button has an aria-label with the full date string (e.g. \"15 juin 2026\") for screen reader users."}, {"noteKey": "components.date_picker.a11y.reduced_motion_note", "noteFallback": "View-change transitions (OrigamFade) are disabled under prefers-reduced-motion: reduce."}], "roles": ["dialog", "grid", "gridcell", "button"], "keyboard": [{"key": "← / → / ↑ / ↓", "actionKey": "components.date_picker.a11y.key_navigate_days", "actionFallback": "Navigate between day cells within the grid."}, {"key": "Enter / Space", "actionKey": "components.date_picker.a11y.key_select", "actionFallback": "Select the focused day, month or year."}, {"key": "PageUp / PageDown", "actionKey": "components.date_picker.a11y.key_month_nav", "actionFallback": "Move to the previous / next month without leaving the day grid."}, {"key": "Home / End", "actionKey": "components.date_picker.a11y.key_week_edges", "actionFallback": "Jump to the first / last day of the current week row."}, {"key": "Escape", "actionKey": "components.date_picker.a11y.key_close", "actionFallback": "Close the picker (when used inside DatePickerField)."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "40px", "tokenPath": "--origam-date-picker__day---size", "descriptionKey": "components.date_picker.tokens.day_size", "descriptionFallback": "Day button size (width and height)."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker.tokens.day_background_color_selected", "descriptionFallback": "Selected day button background."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-date-picker__day---background-color-in-range", "descriptionKey": "components.date_picker.tokens.day_background_color_in_range", "descriptionFallback": "Days in range background (range mode)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"360\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"200\" y=\"20\" width=\"300\" height=\"320\" rx=\"10\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1.5\"/>\n  <circle cx=\"216\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"216\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"200\" y=\"20\" width=\"300\" height=\"64\" rx=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <rect x=\"200\" y=\"64\" width=\"300\" height=\"16\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"216\" cy=\"52\" r=\"10\" fill=\"rgba(0,0,0,0.2)\"/>\n  <text x=\"216\" y=\"56.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"54\" font-size=\"14\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"600\" font-family=\"system-ui\">15 juin 2026</text>\n  <rect x=\"200\" y=\"80\" width=\"300\" height=\"40\" rx=\"0\" fill=\"none\"/>\n  <circle cx=\"216\" cy=\"100\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"216\" y=\"104.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"244\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #555)\" font-family=\"system-ui\">&lt;</text>\n  <text x=\"350\" y=\"104\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\" font-weight=\"600\">Juin 2026</text>\n  <text x=\"454\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #555)\" font-family=\"system-ui\">&gt;</text>\n  <rect x=\"206\" y=\"124\" width=\"288\" height=\"168\" rx=\"4\" fill=\"none\" stroke=\"none\"/>\n  <circle cx=\"216\" cy=\"132\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"216\" y=\"136.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"219\" y=\"148\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #888)\" font-family=\"system-ui\">Lu  Ma  Me  Je  Ve  Sa  Di</text>\n  <text x=\"219\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\"> 1   2   3   4   5   6   7</text>\n  <text x=\"219\" y=\"192\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\"> 8   9  10  11  12  13  14</text>\n  <circle cx=\"282\" cy=\"212\" r=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"283\" y=\"216\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\">15</text>\n  <text x=\"222\" y=\"215\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">16  17  18  19  20  21</text>\n  <text x=\"219\" y=\"236\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">22  23  24  25  26  27  28</text>\n  <text x=\"219\" y=\"258\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" font-family=\"system-ui\">29  30</text>\n  <rect x=\"200\" y=\"300\" width=\"300\" height=\"40\" rx=\"0\" fill=\"var(--origam-color__surface---sunken, #f9f9f9)\" stroke=\"none\"/>\n  <line x1=\"200\" y1=\"300\" x2=\"500\" y2=\"300\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1\"/>\n  <circle cx=\"216\" cy=\"320\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"216\" y=\"324.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"420\" y=\"324\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">Cancel</text>\n  <text x=\"468\" y=\"324\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"system-ui\" font-weight=\"700\">OK</text>\n", "code": "<origam-picker class=\"origam-date-picker origam-date-picker--month\">\n  <!-- slot: #title -->\n\n  <!-- slot: #header → OrigamDatePickerHeader -->\n  <template #header>\n    <origam-date-picker-header :header=\"selectedDateLabel\" />\n  </template>\n\n  <!-- default slot: controls + animated grid -->\n  <origam-date-picker-controls @click:prev=\"prev\" @click:next=\"next\" @click:month=\"viewMonths\" />\n\n  <origam-fade>\n    <!-- view: month grid -->\n    <origam-date-picker-month v-model:date=\"model\" v-model:month=\"month\" v-model:year=\"year\" />\n\n    <!-- OR view: months -->\n    <origam-date-picker-months v-model:month=\"month\" :year=\"year\" />\n\n    <!-- OR view: years -->\n    <origam-date-picker-years v-model:year=\"year\" />\n  </origam-fade>\n\n  <!-- slot: #actions -->\n  <template #actions>\n    <origam-btn text=\"Cancel\" variant=\"text\" />\n    <origam-btn text=\"OK\" color=\"primary\" />\n  </template>\n</origam-picker>", "legend": [{"cls": ".origam-date-picker", "num": 1, "descriptionKey": "components.date_picker.anatomy.root", "descriptionFallback": "Root element. Fixed width 328px (368px with showWeek). Built on OrigamPicker with overflow:hidden. Modifier --year / --months applied while switching view."}, {"cls": "OrigamDatePickerHeader", "num": 2, "descriptionKey": "components.date_picker.anatomy.header", "descriptionFallback": "Coloured header strip (background from header.background-color token = color.action.primary.bg). Shows the selected date. Hidden via hideHeader prop. Replaced by the #header slot."}, {"cls": "OrigamDatePickerControls", "num": 3, "descriptionKey": "components.date_picker.anatomy.controls", "descriptionFallback": "Navigation bar with prev/next arrow buttons and a text button that toggles between month, months and year views."}, {"cls": "OrigamDatePickerMonth", "num": 4, "descriptionKey": "components.date_picker.anatomy.month", "descriptionFallback": "Day-grid view. Weekday labels row + 6 rows of day buttons. Day cells use day.size (40px) and day.border-radius (full). Animated via OrigamFade when switching views."}, {"cls": "#actions slot", "num": 5, "descriptionKey": "components.date_picker.anatomy.actions", "descriptionFallback": "Optional action buttons row. Use for Cancel / OK confirmation pattern. Only rendered when the #actions slot is provided."}], "classes": [{"cls": "origam-date-picker", "descriptionKey": "components.date_picker.anatomy.root", "descriptionFallback": "Root picker element."}, {"cls": "origam-date-picker--month", "descriptionKey": "components.date_picker.anatomy.month_modifier", "descriptionFallback": "Applied when viewMode=\"month\". Modifier drives CSS transitions on sub-components."}, {"cls": "origam-date-picker--show-week", "descriptionKey": "components.date_picker.anatomy.show_week_modifier", "descriptionFallback": "Applied when showWeek=true. Widens the picker to 368px."}], "svgDesc": "Schematic of the DatePicker component with numbered internal regions.", "svgTitle": "Anatomy of OrigamDatePicker", "rootClass": "origam-date-picker", "figcaption": "Anatomy of <code>&lt;origam-date-picker&gt;</code> — 5 regions: root ①, header strip ②, navigation controls ③, day grid ④, and optional actions ⑤.", "svgViewBox": "0 0 700 360"}, "cssVars": [{"name": "--origam-date-picker---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.date_picker.css_vars.background_color", "descriptionFallback": "Picker surface background colour."}, {"name": "--origam-date-picker---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.date_picker.css_vars.color", "descriptionFallback": "Picker surface foreground colour."}, {"name": "--origam-date-picker---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.date_picker.css_vars.border_radius", "descriptionFallback": "Picker surface border-radius."}, {"name": "--origam-date-picker__header---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.date_picker.css_vars.header_background_color", "descriptionFallback": "Header strip background (selected-date display area)."}, {"name": "--origam-date-picker__header---color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.date_picker.css_vars.header_color", "descriptionFallback": "Header strip text colour."}, {"name": "--origam-date-picker__day---size", "defaultValue": "40px", "descriptionKey": "components.date_picker.css_vars.day_size", "descriptionFallback": "Size (width and height) of day buttons in the day grid."}, {"name": "--origam-date-picker__day---border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.date_picker.css_vars.day_border_radius", "descriptionFallback": "Border-radius of day buttons (full circle by default)."}, {"name": "--origam-date-picker__day---background-color-selected", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.date_picker.css_vars.day_background_color_selected", "descriptionFallback": "Background of the selected day button."}, {"name": "--origam-date-picker__day---background-color-in-range", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.date_picker.css_vars.day_background_color_in_range", "descriptionFallback": "Background of days within a selected date range."}, {"name": "--origam-date-picker__day---color-out-of-month", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.date_picker.css_vars.day_color_out_of_month", "descriptionFallback": "Text colour of days outside the current month."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker.exposed.css", "descriptionFallback": "Reactive CSS string for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker.exposed.load", "descriptionFallback": "Injects the style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker.exposed.unload", "descriptionFallback": "Removes the style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.date_picker.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.date_picker.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "range", "labelKey": "components.date_picker.playground.range", "defaultValue": false, "labelFallback": "Range"}, {"kind": "switch", "prop": "hideHeader", "labelKey": "components.date_picker.playground.hide_header", "defaultValue": false, "labelFallback": "Hide header"}, {"kind": "switch", "prop": "showWeek", "labelKey": "components.date_picker.playground.show_week", "defaultValue": false, "labelFallback": "Show week numbers"}, {"kind": "switch", "prop": "landscape", "labelKey": "components.date_picker.playground.landscape", "defaultValue": false, "labelFallback": "Landscape"}]}, "previewVariants": [{"label": "default", "props": {"color": "primary"}}, {"label": "range", "props": {"color": "primary", "range": true}}, {"label": "no header", "props": {"color": "primary", "hideHeader": true}}, {"label": "landscape", "props": {"color": "primary", "landscape": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
