'JetBrains Mono'',monospace\">23</text>\n  <text x=\"66\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">24</text>\n  <text x=\"66\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">25</text>\n  <text x=\"66\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">26</text>\n  <!-- days grid -->\n  <rect x=\"96\" y=\"20\" width=\"564\" height=\"240\" rx=\"0\" fill=\"none\"/>\n  <!-- weekday header row -->\n  <rect x=\"96\" y=\"20\" width=\"564\" height=\"36\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\"/>\n  <text x=\"378\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Lu  Ma  Me  Je  Ve  Sa  Di</text>\n  <!-- day cells sample -->\n  <text x=\"378\" y=\"76\"  font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\"> 1   2   3   4   5   6   7</text>\n  <text x=\"378\" y=\"106\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\"> 8   9  10  11  12  13  14</text>\n  <!-- selected day -->\n  <circle cx=\"312\" cy=\"135\" r=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"312\" y=\"139\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\">15</text>\n  <text x=\"386\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">16  17  18  19  20  21</text>\n  <text x=\"378\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">22  23  24  25  26  27  28</text>\n  <text x=\"346\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">29  30</text>\n  <!-- adjacent days faded -->\n  <text x=\"430\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #aaa)\" text-anchor=\"middle\" font-family=\"system-ui\" opacity=\"0.5\"> 1   2   3   4</text>\n  <!-- markers -->\n  <circle cx=\"48\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"104\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"104\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"104\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"104\" y=\"60.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"312\" cy=\"118\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"312\" y=\"122.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div class=\"origam-date-picker-month\">\n  <!-- optional week numbers column (showWeek=true) -->\n  <div class=\"origam-date-picker-month__weeks\">\n    <div class=\"origam-date-picker-month__day\">&nbsp;</div>\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__day--adjacent\">\n      <span>22</span>\n    </div>\n    <!-- … -->\n  </div>\n\n  <!-- animated day grid (OrigamTransition wraps the inner div) -->\n  <div class=\"origam-date-picker-month__days\">\n    <!-- weekday headers (hidden when hideWeekdays=true) -->\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__weekday\">\n      <span>Lu</span>\n    </div>\n    <!-- … -->\n\n    <!-- day cell -->\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__day--selected\">\n      <origam-btn\n        class=\"origam-date-picker-month__day-btn\"\n        :active=\"item.isSelected\"\n        :border=\"item.isToday\"\n        icon\n        :text=\"item.localized\"\n      />\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-month", "num": 1, "descriptionKey": "components.date_picker_month.anatomy.root", "descriptionFallback": "Root flex container. Display: flex, padding: 0 12px 8px. Hosts the weeks column and the days grid side by side."}, {"cls": ".origam-date-picker-month__weeks", "num": 2, "descriptionKey": "components.date_picker_month.anatomy.weeks", "descriptionFallback": "Optional week-numbers column. Visible when showWeek=true. Uses grid-template-rows: repeat(7, 1fr)."}, {"cls": ".origam-date-picker-month__weekday", "num": 3, "descriptionKey": "components.date_picker_month.anatomy.weekday", "descriptionFallback": "Weekday label cell (Mon, Tue…). Font-size 0.85rem. Hidden when hideWeekdays=true."}, {"cls": ".origam-date-picker-month__day", "num": 4, "descriptionKey": "components.date_picker_month.anatomy.day", "descriptionFallback": "Day cell. 40×40px. Contains the day button. Modifiers: --selected, --today, --adjacent, --hide-adjacent, --week-start, --week-end."}], "classes": [{"cls": "origam-date-picker-month", "descriptionKey": "components.date_picker_month.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-date-picker-month__weeks", "descriptionKey": "components.date_picker_month.anatomy.weeks", "descriptionFallback": "Week-numbers column (showWeek=true)."}, {"cls": "origam-date-picker-month__days", "descriptionKey": "components.date_picker_month.anatomy.days", "descriptionFallback": "Day grid — 7-column CSS grid."}, {"cls": "origam-date-picker-month__weekday", "descriptionKey": "components.date_picker_month.anatomy.weekday", "descriptionFallback": "Weekday label header cell."}, {"cls": "origam-date-picker-month__day", "descriptionKey": "components.date_picker_month.anatomy.day", "descriptionFallback": "Day wrapper cell. 40×40px."}, {"cls": "origam-date-picker-month__day--selected", "descriptionKey": "components.date_picker_month.anatomy.day_selected", "descriptionFallback": "Applied when the day is part of the current selection."}, {"cls": "origam-date-picker-month__day--today", "descriptionKey": "components.date_picker_month.anatomy.day_today", "descriptionFallback": "Applied when the day is today. The inner button receives border=true."}, {"cls": "origam-date-picker-month__day--adjacent", "descriptionKey": "components.date_picker_month.anatomy.day_adjacent", "descriptionFallback": "Days from the previous or next month. Opacity 0.5."}, {"cls": "origam-date-picker-month__day--hide-adjacent", "descriptionKey": "components.date_picker_month.anatomy.day_hide_adjacent", "descriptionFallback": "Adjacent days rendered invisible (opacity 0) when showAdjacentMonths=false."}, {"cls": "origam-date-picker-month__day-btn", "descriptionKey": "components.date_picker_month.anatomy.day_btn", "descriptionFallback": "Inner OrigamBtn inside each day cell. Height 24px, font-size 0.85rem."}], "svgDesc": "Schematic of the DatePickerMonth component showing weekday labels, day cells and week numbers column.", "svgTitle": "Anatomy of OrigamDatePickerMonth", "rootClass": "origam-date-picker-month", "figcaption": "Anatomy of <code>&lt;origam-date-picker-month&gt;</code> — 4 parts: ① root wrapper, ② week-numbers column (showWeek), ③ weekday header row, ④ day button cells.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-date-picker-month-day-diff", "defaultValue": "4px", "descriptionKey": "components.date_picker_month.css_vars.day_diff", "descriptionFallback": "Gap used to offset the range-selection pseudo-element (::before/::after) on selected day cells."}, {"name": "--origam-btn---height", "defaultValue": "24px", "descriptionKey": "components.date_picker_month.css_vars.btn_height", "descriptionFallback": "Height of the inner day button (overridden from the default btn height via :deep selector)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_month.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_month.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_month.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_month.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_month.exposed.unload", "descriptionFallback": "Removes the injected style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_month.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.date_picker_month.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "switch", "prop": "hideWeekdays", "labelKey": "components.date_picker_month.playground.hide_weekdays", "defaultValue": false, "labelFallback": "Hide Weekdays"}, {"kind": "switch", "prop": "range", "labelKey": "components.date_picker_month.playground.range", "defaultValue": false, "labelFallback": "Range"}, {"kind": "switch", "prop": "showWeek", "labelKey": "components.date_picker_month.playground.show_week", "defaultValue": false, "labelFallback": "Show Week"}, {"kind": "switch", "prop": "showAdjacentMonths", "labelKey": "components.date_picker_month.playground.show_adjacent_months", "defaultValue": false, "labelFallback": "Show Adjacent Months"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('795e0f94-1c7d-41af-853a-6ae6808552cd', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'date-picker-months', 'DatePickerMonths', 'Form & Input', NULL, 'mdi-calendar-month-outline', 'components.catalog.date_picker_months.description', 'Month-grid view for picking a month within a given year. Renders 12 month buttons in a 2-column grid with min/max constraint support.', NULL, NULL, 'origam-date-picker-months', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePickerMonths.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/DatePicker/OrigamDatePickerMonths.html', 'date-picker', '{"a11y": {"notes": [{"noteKey": "components.date_picker_months.a11y.disabled_note", "noteFallback": "Months outside the min/max range receive disabled=true on the inner OrigamBtn and are skipped in keyboard navigation."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.date_picker_months.a11y.key_select", "actionFallback": "Selects the focused month."}, {"key": "Tab", "actionKey": "components.date_picker_months.a11y.key_tab", "actionFallback": "Moves focus between month tiles."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker_months.tokens.selected_bg", "descriptionFallback": "Active month button background (driven by the color prop)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x