family=\"system-ui\" font-weight=\"600\">May</text>\n  <rect x=\"362\" y=\"112\" width=\"174\" height=\"28\" rx=\"14\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"449\" y=\"130\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"system-ui\">Jun</text>\n  <text x=\"350\" y=\"168\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">… (Jul – Dec)</text>\n  <!-- markers -->\n  <circle cx=\"148\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"168\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"168\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"168\" cy=\"120\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"168\" y=\"124.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-date-picker-months\">\n  <div class=\"origam-date-picker-months__content\">\n    <!-- slot: #month — repeated for each of the 12 months -->\n    <origam-btn\n      v-for=\"(month, i) in months\"\n      :key=\"i\"\n      :active=\"model === i\"\n      :color=\"model === i ? color : undefined\"\n      :disabled=\"month.isDisabled\"\n      :rounded=\"true\"\n      :text=\"month.text\"\n      @click=\"handleClick(i)\"\n    />\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-months", "num": 1, "descriptionKey": "components.date_picker_months.anatomy.root", "descriptionFallback": "Root container. Fixed height (288px by default). Overflow hidden."}, {"cls": ".origam-date-picker-months__content", "num": 2, "descriptionKey": "components.date_picker_months.anatomy.content", "descriptionFallback": "2-column CSS grid with justify-content: space-around. padding-inline: 36px. grid-gap: 0 24px. Inner OrigamBtn elements have text-transform: none."}, {"cls": "OrigamBtn (active)", "num": 3, "descriptionKey": "components.date_picker_months.anatomy.active_btn", "descriptionFallback": "The currently selected month button. Receives active=true and color=props.color. All buttons have rounded=true."}], "classes": [{"cls": "origam-date-picker-months", "descriptionKey": "components.date_picker_months.anatomy.root", "descriptionFallback": "Root container. Default height 288px."}, {"cls": "origam-date-picker-months__content", "descriptionKey": "components.date_picker_months.anatomy.content", "descriptionFallback": "2-column grid of month buttons."}], "svgDesc": "Schematic of the DatePickerMonths component showing a 2-column grid of 12 month buttons.", "svgTitle": "Anatomy of OrigamDatePickerMonths", "rootClass": "origam-date-picker-months", "figcaption": "Anatomy of <code>&lt;origam-date-picker-months&gt;</code> — 3 parts: ① root container (288px default height), ② the 2-column grid content wrapper, ③ the active month button highlighted with the <code>color</code> prop.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-date-picker-months---height", "defaultValue": "288px", "descriptionKey": "components.date_picker_months.css_vars.height", "descriptionFallback": "Container height. Overridden via the height prop (IDimensionProps)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_months.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_months.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey":