INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5e4f3477-2aff-4f8c-ae1c-ffd4573afe24', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'date-picker-years', 'DatePickerYears', 'Form & Input', NULL, 'mdi-calendar-range', 'components.catalog.date_picker_years.description', 'Scrollable year list for picking a year. Renders years in a 3-column grid from min to max (defaulting to ±100 years from today). Auto-scrolls to the selected year on mount.', NULL, NULL, 'origam-date-picker-years', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePickerYears.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/DatePicker/OrigamDatePickerYears.html', 'date-picker', '{"a11y": {"notes": [{"noteKey": "components.date_picker_years.a11y.scroll_note", "noteFallback": "On mount, the selected year is automatically scrolled into the centre of the visible area via scrollIntoView({block: \"center\"}), so users do not need to scroll manually to find the current year."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.date_picker_years.a11y.key_select", "actionFallback": "Selects the focused year."}, {"key": "Tab", "actionKey": "components.date_picker_years.a11y.key_tab", "actionFallback": "Moves focus between year tiles."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker_years.tokens.selected_bg", "descriptionFallback": "Active year button background (driven by the color prop)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <!-- root with scroll indicator -->\n  <rect x=\"100\" y=\"20\" width=\"500\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- scroll indicator bar on right -->\n  <rect x=\"590\" y=\"20\" width=\"6\" height=\"180\" rx=\"3\" fill=\"var(--origam-color__border---subtle, rgba(0,0,0,0.06))\"/>\n  <rect x=\"590\" y=\"68\" width=\"6\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <!-- 3-col grid -->\n  <text x=\"162\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2020</text>\n  <text x=\"310\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2021</text>\n  <text x=\"458\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2022</text>\n  <text x=\"162\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2023</text>\n  <text x=\"310\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2024</text>\n  <text x=\"458\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2025</text>\n  <!-- selected year -->\n  <rect x=\"218\" y=\"92\" width=\"184\" height=\"28\" rx=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"310\" y=\"110\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"system-ui\" font-weight=\"700\">2026</text>\n  <text x=\"162\" y=\"110\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2026</text>\n  <text x=\"458\" y=\"110\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2027</text>\n  <text x=\"162\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2028</text>\n  <text x=\"310\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2029</text>\n  <text x=\"458\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2030</text>\n  <text x=\"350\" y=\"178\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">… scrollable</text>\n  <!-- markers -->\n  <circle cx=\"108\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"120\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"120\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"220\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"220\" y=\"104.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-date-picker-years\">\n  <div class=\"origam-date-picker-years__content\">\n    <!-- slot: #year — repeated for each year in the [min..max] range -->\n    <origam-btn\n      v-for=\"year in years\"\n      :ref=\"model === year.value ? yearRef : undefined\"\n      :active=\"model === year.value\"\n      :color=\"model === year.value ? color : undefined\"\n      :rounded=\"true\"\n      :text=\"year.text\"\n      @click=\"handleClick(year.value)\"\n    />\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-years", "num": 1, "descriptionKey": "components.date_picker_years.anatomy.root", "descriptionFallback": "Root container. Height 288px (default), overflow-y: scroll. Enables native browser scrolling to the selected year."}, {"cls": ".origam-date-picker-years__content", "num": 2, "descriptionKey": "components.date_picker_years.anatomy.content", "descriptionFallback": "3-column CSS grid with justify-content: space-around. gap: 8px 24px. padding-inline: 32px. Inner OrigamBtn have padding-inline: 8px."}, {"cls": "OrigamBtn (active)", "num": 3, "descriptionKey": "components.date_picker_years.anatomy.active_btn", "descriptionFallback": "The selected year button. Receives active=true and color=props.color. All buttons have rounded=true. The active button is also assigned a template ref so scrollIntoView can target it on mount."}], "classes": [{"cls": "origam-date-picker-years", "descriptionKey": "components.date_picker_years.anatomy.root", "descriptionFallback": "Root scroll container. Default height 288px."}, {"cls": "origam-date-picker-years__content", "descriptionKey": "components.date_picker_years.anatomy.content", "descriptionFallback": "3-column grid of year buttons."}], "svgDesc": "Schematic of the DatePickerYears component showing a scrollable 3-column grid of year buttons.", "svgTitle": "Anatomy of OrigamDatePickerYears", "rootClass": "origam-date-picker-years", "figcaption": "Anatomy of <code>&lt;origam-date-picker-years&gt;</code> — 3 parts: ① root scroll container (288px height, overflow-y: scroll), ② 3-column grid content wrapper, ③ the active year button. On mount, the selected year scrolls into view via <code>scrollIntoView({block: ''center''})</code>.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-date-picker-years---height", "defaultValue": "288px", "descriptionKey": "components.date_picker_years.css_vars.height", "descriptionFallback": "Container height. Overflow-y: scroll. Overridden via the height prop (IDimensionProps)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_years.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_years.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_years.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_years.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_years.exposed.unload", "descriptionFallback": "Removes the injected style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_years.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.date_picker_years.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7f2305f1-1c7a-4ada-ba37-fc546627547f', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'defaults-provider', 'DefaultsProvider', 'Utilities & Providers', NULL, 'mdi-tune-variant', 'components.catalog.defaults_provider.description', 'Structurally transparent context provider that injects a prop-defaults map into all descendant Origam components via useDefaults().', NULL, NULL, 'origam-defaults-provider', NULL, 'packages/ds/src/components/DefaultsProvider/OrigamDefaultsProvider.vue', 'origam', NULL, NULL, '/stories/?story=components-defaults-provider--design', '/docs/components/DefaultsProvider/OrigamDefaultsProvider.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.defaults_provider.a11y.transparent_note", "noteFallback": "OrigamDefaultsProvider has no visual rendering, no focusable element and no ARIA attributes. All a11y considerations belong to the descendant components it wraps."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"120\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"8 4\"/>\n  <text x=\"350\" y=\"30\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-defaults-provider (no DOM output)</text>\n  <rect x=\"80\" y=\"70\" width=\"180\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"170\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">child component</text>\n  <rect x=\"300\" y=\"70\" width=\"180\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"390\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">child component</text>\n  <rect x=\"520\" y=\"70\" width=\"120\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"580\" y=\"104\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">…more</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"170\" cy=\"78\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"170\" y=\"82.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"185\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① Provider (transparent) injects defaults via provide() — no DOM node rendered</text>\n", "code": "<!-- OrigamDefaultsProvider renders ONLY its default slot — no DOM wrapper -->\n<template>\n  <slot name=\"default\" />\n</template>\n\n<script setup>\n// Injects the defaults map into all useDefaults() consumers in the subtree\nprovideDefaults(computed(() => props.defaults ?? {}), {\n  scoped: props.scoped,\n  reset: props.reset,\n  root: props.root,\n  disabled: props.disabled\n})\n</script>", "legend": [{"cls": ".origam-defaults-provider (no DOM)", "num": 1, "descriptionKey": "components.defaults_provider.anatomy.provider", "descriptionFallback": "The provider itself. Calls <code>provideDefaults()</code> once on setup, then renders only <code>&lt;slot name=\"default\"/&gt;</code>. No wrapper element is injected into the DOM."}, {"cls": "#default slot — descendant components", "num": 2, "descriptionKey": "components.defaults_provider.anatomy.slot", "descriptionFallback": "Any Origam component in the subtree that calls <code>useDefaults()</code> automatically picks up the injected map. Child components are NOT aware of being wrapped."}], "classes": [{"cls": "origam-defaults-provider", "descriptionKey": "components.defaults_provider.anatomy.root", "descriptionFallback": "No CSS class is emitted on any DOM element. The component is purely logical."}], "svgDesc": "Schematic showing the provider renders only its default slot with no visual chrome.", "svgTitle": "Anatomy of OrigamDefaultsProvider", "rootClass": "origam-defaults-provider", "figcaption": "Anatomy of <code>&lt;origam-defaults-provider&gt;</code> — structurally transparent. The component renders only the <code>#default</code> slot; it injects defaults via Vue''s <code>provide()</code> / <code>inject()</code> without any DOM output of its own.", "svgViewBox": "0 0 700 200"}, "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.defaults_provider.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component. Used by Origam''s auto-forwarding pattern."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.defaults_provider.playground.disabled", "defaultValue": false, "labelFallback": "Disabled (pass through parent defaults)"}, {"kind": "switch", "prop": "scoped", "labelKey": "components.defaults_provider.playground.scoped", "defaultValue": false, "labelFallback": "Scoped (no parent inheritance)"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8a090473-ce5e-454e-8d4b-f3c7511fc32e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'dialog', 'Dialog', 'Overlay & Surface', NULL, 'mdi-card-outline', 'components.catalog.dialog.description', 'Modal overlay dialog built on OrigamOverlay and OrigamCard. Supports activator slot, focus trap, scrollable mode, fullscreen, size variants, and status icons.', NULL, NULL, 'origam-dialog', NULL, 'packages/ds/src/components/Dialog/OrigamDialog.vue', 'origam', NULL, NULL, '/stories/?story=components-dialog--design', '/docs/components/Dialog/OrigamDialog.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.dialog.a11y.role_note", "noteFallback": "The inner OrigamCard renders role=\"dialog\" and aria-modal=\"true\". The title element is linked via aria-labelledby using the auto-generated dialogTitleId."}, {"noteKey": "components.dialog.a11y.focus_note", "noteFallback": "On open, focus moves to the overlay content element. On close, focus returns to the activator element."}, {"noteKey": "components.dialog.a11y.activator_note", "noteFallback": "The activator element automatically receives aria-haspopup=\"dialog\" and aria-expanded bound to the open state."}, {"noteKey": "components.dialog.a11y.persistent_note", "noteFallback": "When persistent=true, Escape and click-outside do not close the dialog. Use this only for critical flows (e.g., unsaved changes warning)."}], "roles": ["dialog"], "keyboard": [{"key": "Escape", "actionKey": "components.dialog.a11y.key_escape", "actionFallback": "Closes the dialog (unless persistent=true)."}, {"key": "Tab", "actionKey": "components.dialog.a11y.key_tab", "actionFallback": "Cycles focus through focusable elements inside the dialog. When retainFocus=true, Tab wraps from last to first element."}, {"key": "Shift+Tab", "actionKey": "components.dialog.a11y.key_shift_tab", "actionFallback": "Cycles focus backwards. Wraps from first to last element when retainFocus=true."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-dialog---background", "descriptionKey": "components.dialog.tokens.background", "descriptionFallback": "Dialog surface background. Uses the raised surface semantic color."}, {"type": "dimension", "value": "var(--origam-radius---lg)", "tokenPath": "--origam-dialog---border-radius", "descriptionKey": "components.dialog.tokens.border_radius", "descriptionFallback": "Border radius applied to the dialog content wrapper. Reset to 0 in fullscreen mode."}, {"type": "shadow", "value": "var(--origam-shadow---xl)", "tokenPath": "--origam-dialog---box-shadow", "descriptionKey": "components.dialog.tokens.box_shadow", "descriptionFallback": "Elevation shadow for the dialog surface."}, {"type": "number", "value": "var(--origam-zIndex---modal)", "tokenPath": "--origam-dialog---z-index", "descriptionKey": "components.dialog.tokens.z_index", "descriptionFallback": "z-index of the dialog overlay (default: 2400)."}, {"type": "dimension", "value": "720px", "tokenPath": "--origam-dialog---width-md", "descriptionKey": "components.dialog.tokens.width_md", "descriptionFallback": "Default dialog width (size=\"default\")."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-dialog---transition-duration", "descriptionKey": "components.dialog.tokens.transition_duration", "descriptionFallback": "Enter/leave transition duration."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-dialog__header---padding", "descriptionKey": "components.dialog.tokens.header_padding", "descriptionFallback": "Padding inside the dialog header zone."}, {"type": "dimension", "value": "var(--origam-space---6)", "tokenPath": "--origam-dialog__content---padding-inline", "descriptionKey": "components.dialog.tokens.content_padding_inline", "descriptionFallback": "Horizontal padding of the dialog body content."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- overlay scrim -->\n  <rect x=\"10\" y=\"10\" width=\"680\" height=\"280\" rx=\"4\" fill=\"rgba(0,0,0,0.08)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"25\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">origam-overlay (scrim)</text>\n  <!-- card surface -->\n  <rect x=\"100\" y=\"40\" width=\"500\" height=\"220\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- header zone -->\n  <rect x=\"100\" y=\"40\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"72\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">header — prepend | title | subtitle | append (close btn)</text>\n  <!-- content zone -->\n  <rect x=\"100\" y=\"96\" width=\"500\" height=\"108\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"155\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#content slot + isRead sentinel</text>\n  <!-- footer zone -->\n  <rect x=\"100\" y=\"204\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"236\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">footer — action buttons</text>\n  <!-- numbering -->\n  <circle cx=\"18\" cy=\"18\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"18\" y=\"22.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"108\" cy=\"104\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"108.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"108\" cy=\"212\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"216.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<origam-overlay v-model=\"isActive\" class=\"origam-dialog\">\n  <!-- activator trigger element -->\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\" />\n  </template>\n\n  <template #default=\"{ isActive }\">\n    <slot name=\"default\" v-bind=\"{ isActive }\">\n      <!-- default body: OrigamCard -->\n      <origam-card\n        role=\"dialog\"\n        aria-modal=\"true\"\n        :aria-labelledby=\"dialogTitleId\"\n      >\n        <!-- header zone: prepend | title | subtitle | append(close) -->\n        <template #header-prepend><slot name=\"header-prepend\" /></template>\n        <template #header-title=\"{ titleId }\"><slot name=\"header-title\" v-bind=\"{ titleId }\" /></template>\n        <template #header-append>\n          <slot name=\"header-append\">\n            <origam-btn icon=\"mdi-close\" @click=\"handleClose\" aria-label=\"Close dialog\" />\n          </slot>\n        </template>\n\n        <!-- scrollable content body -->\n        <template #default>\n          <slot name=\"content\" />\n          <div ref=\"endText\" v-intersect=\"handleIntersect\" />\n        </template>\n\n        <!-- footer actions -->\n        <template #footer><slot name=\"footer\" /></template>\n      </origam-card>\n    </slot>\n  </template>\n</origam-overlay>", "legend": [{"cls": ".origam-overlay (scrim)", "num": 1, "descriptionKey": "components.dialog.anatomy.overlay", "descriptionFallback": "Full-viewport overlay managed by OrigamOverlay. Blocks interaction with the page and handles click-outside / Escape key."}, {"cls": ".origam-card (header)", "num": 2, "descriptionKey": "components.dialog.anatomy.header", "descriptionFallback": "Card header zone with prepend (status icon), title (aria-labelledby target), subtitle, and append (close button)."}, {"cls": ".origam-card__content", "num": 3, "descriptionKey": "components.dialog.anatomy.content", "descriptionFallback": "Scrollable content body. Contains the #content slot plus an invisible IntersectionObserver sentinel that fires isRead when scrolled into view."}, {"cls": ".origam-card__footer", "num": 4, "descriptionKey": "components.dialog.anatomy.footer", "descriptionFallback": "Footer area for action buttons. Typically Cancel and Confirm. Fixed at the bottom in scrollable mode."}], "classes": [{"cls": "origam-dialog", "descriptionKey": "components.dialog.anatomy.root", "descriptionFallback": "Root class applied to the origam-overlay element. Drives alignment (center center) and size-width vars."}, {"cls": "origam-dialog--fullscreen", "descriptionKey": "components.dialog.anatomy.fullscreen", "descriptionFallback": "Applied when fullscreen=true. Resets width, max-width, max-height and border-radius to 100vw/100vh/0."}, {"cls": "origam-dialog--scrollable", "descriptionKey": "components.dialog.anatomy.scrollable", "descriptionFallback": "Applied when scrollable=true. Enables overflow-y: auto on the card content zone."}, {"cls": "origam-dialog--size-x-small", "descriptionKey": "components.dialog.anatomy.size_xs", "descriptionFallback": "Sets --origam-dialog---width to 320px."}, {"cls": "origam-dialog--size-small", "descriptionKey": "components.dialog.anatomy.size_sm", "descriptionFallback": "Sets --origam-dialog---width to 400px."}, {"cls": "origam-dialog--size-default", "descriptionKey": "components.dialog.anatomy.size_md", "descriptionFallback": "Sets --origam-dialog---width to 720px."}, {"cls": "origam-dialog--size-large", "descriptionKey": "components.dialog.anatomy.size_lg", "descriptionFallback": "Sets --origam-dialog---width to 960px."}, {"cls": "origam-dialog--size-x-large", "descriptionKey": "components.dialog.anatomy.size_xl", "descriptionFallback": "Sets --origam-dialog---width to 1080px."}], "svgDesc": "Schematic of the Dialog component showing overlay wrapper, card body, header, content, and footer zones.", "svgTitle": "Anatomy of OrigamDialog", "rootClass": "origam-dialog", "figcaption": "Anatomy of <code>&lt;origam-dialog&gt;</code> — 4 zones: ① overlay scrim, ② card header (prepend / title / append), ③ scrollable content body, ④ footer for actions.", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-dialog---width", "defaultValue": "auto", "descriptionKey": "components.dialog.css_vars.width", "descriptionFallback": "Dialog width. Overridden per size class (xs: 320px → xl: 1080px) and set to 100vw in fullscreen mode."}, {"name": "--origam-dialog---max-height", "defaultValue": "calc(100vh - 48px)", "descriptionKey": "components.dialog.css_vars.max_height", "descriptionFallback": "Maximum dialog height. Resolves to 100vh in fullscreen mode."}, {"name": "--origam-dialog---max-width", "defaultValue": "calc(100vw - 48px)", "descriptionKey": "components.dialog.css_vars.max_width", "descriptionFallback": "Maximum dialog width."}, {"name": "--origam-dialog---border-radius", "defaultValue": "{radius.lg} (12px)", "descriptionKey": "components.dialog.css_vars.border_radius", "descriptionFallback": "Border radius applied to the overlay content wrapper. Reset to 0 in fullscreen mode."}, {"name": "--origam-dialog---box-shadow", "defaultValue": "{shadow.xl}", "descriptionKey": "components.dialog.css_vars.box_shadow", "descriptionFallback": "Box shadow applied to the dialog surface for depth."}, {"name": "--origam-dialog---width-xs", "defaultValue": "320px", "descriptionKey": "components.dialog.css_vars.width_xs", "descriptionFallback": "Width token for size=\"x-small\"."}, {"name": "--origam-dialog---width-sm", "defaultValue": "400px", "descriptionKey": "components.dialog.css_vars.width_sm", "descriptionFallback": "Width token for size=\"small\"."}, {"name": "--origam-dialog---width-md", "defaultValue": "720px", "descriptionKey": "components.dialog.css_vars.width_md", "descriptionFallback": "Width token for size=\"default\"."}, {"name": "--origam-dialog---width-lg", "defaultValue": "960px", "descriptionKey": "components.dialog.css_vars.width_lg", "descriptionFallback": "Width token for size=\"large\"."}, {"name": "--origam-dialog---width-xl", "defaultValue": "1080px", "descriptionKey": "components.dialog.css_vars.width_xl", "descriptionFallback": "Width token for size=\"x-large\"."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.dialog.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to inner OrigamOverlay or OrigamCard instances."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.dialog.exposed.css", "descriptionFallback": "Reactive CSS string generated from dialogStyles. Used by OrigamDefaultsProvider for style injection."}, {"name": "id", "type": "string", "descriptionKey": "components.dialog.exposed.id", "descriptionFallback": "Unique style-sheet ID for this dialog instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.dialog.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.dialog.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.dialog.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}, {"name": "contentEl", "type": "HTMLElement | undefined", "descriptionKey": "components.dialog.exposed.content_el", "descriptionFallback": "Reference to the overlay content element forwarded from the inner OrigamOverlay ref."}, {"name": "activatorEl", "type": "HTMLElement | undefined", "descriptionKey": "components.dialog.exposed.activator_el", "descriptionFallback": "Reference to the activator element forwarded from the inner OrigamOverlay ref."}, {"name": "globalTop", "type": "boolean", "descriptionKey": "components.dialog.exposed.global_top", "descriptionFallback": "True when this dialog is the topmost open overlay in the global stack."}], "playground": {"controls": [{"kind": "select", "prop": "size", "options": [{"label": "x-small (320px)", "value": "x-small"}, {"label": "small (400px)", "value": "small"}, {"label": "default (720px)", "value": "default"}, {"label": "large (960px)", "value": "large"}, {"label": "x-large (1080px)", "value": "x-large"}], "labelKey": "components.dialog.playground.size", "defaultValue": "default", "labelFallback": "Size"}, {"kind": "switch", "prop": "fullscreen", "labelKey": "components.dialog.playground.fullscreen", "defaultValue": false, "labelFallback": "Fullscreen"}, {"kind": "switch", "prop": "scrollable", "labelKey": "components.dialog.playground.scrollable", "defaultValue": false, "labelFallback": "Scrollable"}, {"kind": "switch", "prop": "persistent", "labelKey": "components.dialog.playground.persistent", "defaultValue": false, "labelFallback": "Persistent (no outside-click close)"}, {"kind": "select", "prop": "status", "options": [{"label": "(none)", "value": ""}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.dialog.playground.status", "defaultValue": "", "labelFallback": "Status"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('efcef056-561d-4f4f-9239-feda38712a02', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'dialog-confirmation', 'DialogConfirmation', 'Overlay & Surface', NULL, 'mdi-check-circle-outline', 'components.catalog.dialog_confirmation.description', 'Opinionated dialog with built-in Validate / Cancel footer buttons and a read-to-enable guard — the Validate button is only enabled once the user has scrolled to the bottom of the content (isRead pattern).', NULL, NULL, 'origam-dialog-confirmation', NULL, 'packages/ds/src/components/Dialog/OrigamDialogConfirmation.vue', 'origam', NULL, NULL, '/stories/?story=components-dialog--design', '/docs/components/Dialog/OrigamDialogConfirmation.html', 'dialog', '{"a11y": {"notes": [{"noteKey": "components.dialog_confirmation.a11y.validate_disabled_note", "noteFallback": "The Validate button is rendered with disabled=true and aria-disabled until the user scrolls to the bottom of the content (isRead=true). This is intentional — it enforces that users read critical content before confirming."}, {"noteKey": "components.dialog_confirmation.a11y.role_note", "noteFallback": "role=\"dialog\" and aria-modal=\"true\" are applied by the inner OrigamDialog on the card element. The title is linked via aria-labelledby."}, {"noteKey": "components.dialog_confirmation.a11y.focus_note", "noteFallback": "On open, focus moves to the overlay content. On close, focus returns to the activator element."}], "roles": ["dialog"], "keyboard": [{"key": "Escape", "actionKey": "components.dialog_confirmation.a11y.key_escape", "actionFallback": "Closes the dialog (unless persistent=true)."}, {"key": "Tab", "actionKey": "components.dialog_confirmation.a11y.key_tab", "actionFallback": "Cycles focus through Cancel, Validate and any other focusable elements inside the dialog (focus trap inherited from OrigamDialog)."}, {"key": "Shift+Tab", "actionKey": "components.dialog_confirmation.a11y.key_shift_tab", "actionFallback": "Cycles focus backwards."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- overlay scrim -->\n  <rect x=\"10\" y=\"10\" width=\"680\" height=\"280\" rx=\"4\" fill=\"rgba(0,0,0,0.08)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"24\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">OrigamDialog (inner overlay)</text>\n  <!-- card surface -->\n  <rect x=\"100\" y=\"36\" width=\"500\" height=\"228\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- header zone -->\n  <rect x=\"100\" y=\"36\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"68\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">header — prepend (status icon) | title | append (close)</text>\n  <!-- content zone -->\n  <rect x=\"100\" y=\"92\" width=\"500\" height=\"100\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.12))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"146\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#content slot + isRead IntersectionObserver sentinel</text>\n  <!-- footer zone -->\n  <rect x=\"100\" y=\"192\" width=\"500\" height=\"72\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.18))\" stroke-width=\"1\"/>\n  <!-- cancel button -->\n  <rect x=\"120\" y=\"212\" width=\"100\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\"/>\n  <text x=\"170\" y=\"232\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"system-ui\">Cancel</text>\n  <!-- validate button -->\n  <rect x=\"468\" y=\"212\" width=\"112\" height=\"32\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"524\" y=\"232\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"system-ui\" font-weight=\"600\">Validate</text>\n  <text x=\"350\" y=\"247\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">Validate enabled only when isRead = true (user scrolled to bottom)</text>\n  <!-- markers -->\n  <circle cx=\"18\" cy=\"18\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"18\" y=\"22.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"108\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"104.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"108\" cy=\"200\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"204.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<origam-dialog\n  ref=\"origamDialogRef\"\n  v-model=\"isActive\"\n  v-bind=\"dialogProps\"\n  @is-read=\"handleIsRead\"\n>\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\" />\n  </template>\n\n  <!-- all header-* slots forwarded -->\n  <template #header><slot name=\"header\" /></template>\n  <template #header-prepend><slot name=\"header-prepend\" /></template>\n  <template #header-title><slot name=\"header-title\" /></template>\n  <!-- … -->\n\n  <template #content><slot name=\"content\" /></template>\n\n  <!-- built-in footer: Cancel + Validate -->\n  <template #footer>\n    <slot name=\"footer\">\n      <origam-container fluid>\n        <origam-row justify=\"space-between\">\n          <origam-col cols=\"auto\">\n            <origam-btn v-if=\"cancellable\" text=\"Cancel\" @click=\"handleCancel\" />\n          </origam-col>\n          <origam-col cols=\"auto\">\n            <origam-btn :disabled=\"!validatable\" text=\"Validate\" @click=\"handleValidate\" />\n          </origam-col>\n        </origam-row>\n      </origam-container>\n    </slot>\n  </template>\n</origam-dialog>", "legend": [{"cls": ".origam-overlay (scrim)", "num": 1, "descriptionKey": "components.dialog_confirmation.anatomy.overlay", "descriptionFallback": "Full-viewport overlay inherited from OrigamDialog. Handles click-outside and Escape (unless persistent=true)."}, {"cls": ".origam-card (header)", "num": 2, "descriptionKey": "components.dialog_confirmation.anatomy.header", "descriptionFallback": "Card header with status icon in prepend slot, title, and close button in append slot. All header-* slots are forwarded transparently."}, {"cls": ".origam-card__content", "num": 3, "descriptionKey": "components.dialog_confirmation.anatomy.content", "descriptionFallback": "Scrollable content body. An IntersectionObserver sentinel at the bottom fires the @isRead event when it enters the viewport, enabling the Validate button."}, {"cls": ".origam-card__footer (two-button bar)", "num": 4, "descriptionKey": "components.dialog_confirmation.anatomy.footer", "descriptionFallback": "Default footer with Cancel (left) and Validate (right) in a space-between row. The Validate button is disabled until isRead=true. Override with the #footer slot."}], "classes": [{"cls": "origam-dialog", "descriptionKey": "components.dialog_confirmation.anatomy.root", "descriptionFallback": "Root class — delegated to the inner OrigamDialog. DialogConfirmation itself has no additional BEM root class."}], "svgDesc": "Schematic of the DialogConfirmation component showing its inner OrigamDialog with header, content, and a two-button footer.", "svgTitle": "Anatomy of OrigamDialogConfirmation", "rootClass": "origam-dialog", "figcaption": "Anatomy of <code>&lt;origam-dialog-confirmation&gt;</code> — wraps OrigamDialog with 4 zones: ① overlay scrim, ② header (status icon + title), ③ scrollable content + isRead sentinel, ④ two-button footer (Cancel / Validate).", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-dialog-confirmation---icon-size", "defaultValue": "28px", "descriptionKey": "components.dialog_confirmation.css_vars.icon_size", "descriptionFallback": "Size of the status icon in the header prepend slot."}, {"name": "--origam-dialog-confirmation---icon-color-default", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_default", "descriptionFallback": "Icon colour when no status is set."}, {"name": "--origam-dialog-confirmation---icon-color-success", "defaultValue": "{color.feedback.success.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_success", "descriptionFallback": "Icon colour when status=\"success\"."}, {"name": "--origam-dialog-confirmation---icon-color-warning", "defaultValue": "{color.feedback.warning.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_warning", "descriptionFallback": "Icon colour when status=\"warning\"."}, {"name": "--origam-dialog-confirmation---icon-color-danger", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_danger", "descriptionFallback": "Icon colour when status=\"danger\"."}, {"name": "--origam-dialog-confirmation---icon-color-info", "defaultValue": "{color.feedback.info.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_info", "descriptionFallback": "Icon colour when status=\"info\"."}, {"name": "--origam-dialog-confirmation---title-font-size", "defaultValue": "{font.size.lg}", "descriptionKey": "components.dialog_confirmation.css_vars.title_font_size", "descriptionFallback": "Title font size."}, {"name": "--origam-dialog-confirmation---title-font-weight", "defaultValue": "{font.weight.semibold}", "descriptionKey": "components.dialog_confirmation.css_vars.title_font_weight", "descriptionFallback": "Title font weight."}, {"name": "--origam-dialog-confirmation---actions-gap", "defaultValue": "{space.3}", "descriptionKey": "components.dialog_confirmation.css_vars.actions_gap", "descriptionFallback": "Gap between footer action buttons."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.dialog_confirmation.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the inner OrigamDialog."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.dialog_confirmation.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "size", "options": [{"label": "(default)", "value": ""}, {"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.dialog_confirmation.playground.size", "defaultValue": "", "labelFallback": "Size"}, {"kind": "select", "prop": "status", "options": [{"label": "(default)", "value": ""}, {"label": "STATUS.SUCCESS", "value": "STATUS.SUCCESS"}, {"label": "success", "value": "success"}, {"label": "info", "value": "info"}, {"label": "STATUS.INFO", "value": "STATUS.INFO"}, {"label": "STATUS.WARNING", "value": "STATUS.WARNING"}, {"label": "warning", "value": "warning"}, {"label": "error", "value": "error"}, {"label": "STATUS.ERROR", "value": "STATUS.ERROR"}], "labelKey": "components.dialog_confirmation.playground.status", "defaultValue": "", "labelFallback": "Status"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.dialog_confirmation.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "modelValue", "labelKey": "components.dialog_confirmation.playground.model_value", "defaultValue": false, "labelFallback": "Value"}, {"kind": "switch", "prop": "cancellable", "labelKey": "components.dialog_confirmation.playground.cancellable", "defaultValue": true, "labelFallback": "Cancellable"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.dialog