INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('917097f6-4508-41f1-95d7-60ae53379f24', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'divider', 'Divider', 'Layout & Structure', NULL, 'mdi-minus', 'components.catalog.divider.description', 'Horizontal or vertical separator rendered as a semantic <hr> with color, thickness and inset support.', NULL, NULL, 'origam-divider', NULL, 'packages/ds/src/components/Divider/OrigamDivider.vue', 'origam', NULL, NULL, '/stories/?story=components-divider--design', '/docs/components/Divider/OrigamDivider.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.divider.a11y.role_note", "noteFallback": "Renders as a native <hr> element which has an implicit role=\"separator\". The aria-orientation attribute matches the direction prop (horizontal or vertical)."}, {"noteKey": "components.divider.a11y.decorative_note", "noteFallback": "When used purely for visual decoration, pass role=\"presentation\" via attrs to remove the element from the accessibility tree."}], "roles": ["separator"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-divider---color", "descriptionKey": "components.divider.tokens.color", "descriptionFallback": "Default divider color. References the subtle border semantic token."}, {"type": "dimension", "value": "var(--origam-border__width---thin)", "tokenPath": "--origam-divider---thickness", "descriptionKey": "components.divider.tokens.thickness", "descriptionFallback": "Default stroke thickness. Overridden by the thickness prop."}, {"type": "number", "value": "var(--origam-opacity---100)", "tokenPath": "--origam-divider---opacity", "descriptionKey": "components.divider.tokens.opacity", "descriptionFallback": "Token default opacity (1). SCSS overrides to 0.12 for a subtle separator effect."}, {"type": "dimension", "value": "var(--origam-space---0)", "tokenPath": "--origam-divider---margin-block", "descriptionKey": "components.divider.tokens.margin_block", "descriptionFallback": "Default block margin (0). Use the margin prop for spacing."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"350\" y=\"40\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">HORIZONTAL</text>\n  <rect x=\"40\" y=\"55\" width=\"620\" height=\"2\" rx=\"1\" fill=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <circle cx=\"48\" cy=\"56\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"60.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <text x=\"350\" y=\"110\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">VERTICAL</text>\n  <rect x=\"348\" y=\"120\" width=\"4\" height=\"60\" rx=\"1\" fill=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <circle cx=\"350\" cy=\"125\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"129.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"195\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Rendered as &lt;hr&gt; — native HTML separator with role=\"separator\"</text>\n", "code": "<hr\n  role=\"separator\"\n  aria-orientation=\"horizontal\"\n  class=\"origam-divider origam-divider--horizontal\"\n/>", "legend": [{"cls": ".origam-divider", "num": 1, "descriptionKey": "components.divider.anatomy.root_horizontal", "descriptionFallback": "Root <code>&lt;hr&gt;</code> element. In horizontal mode: <code>display: block; flex: 1 1 100%</code>. <code>aria-orientation=\"horizontal\"</code>."}, {"cls": ".origam-divider--vertical", "num": 2, "descriptionKey": "components.divider.anatomy.vertical", "descriptionFallback": "Vertical variant modifier. Switches to <code>display: inline-flex</code>, <code>height: auto</code>, <code>align-self: stretch</code>. <code>aria-orientation=\"vertical\"</code>."}, {"cls": ".origam-divider--inset", "num": 3, "descriptionKey": "components.divider.anatomy.inset", "descriptionFallback": "Inset modifier. Adds <code>margin-inline-start</code> so the line aligns with list item content."}], "classes": [{"cls": "origam-divider", "descriptionKey": "components.divider.anatomy.root_horizontal", "descriptionFallback": "Root element. Renders as a semantic <hr> with role=\"separator\"."}, {"cls": "origam-divider--horizontal", "descriptionKey": "components.divider.anatomy.horizontal", "descriptionFallback": "Applied when direction=\"horizontal\" (the default). Full-width block line."}, {"cls": "origam-divider--vertical", "descriptionKey": "components.divider.anatomy.vertical", "descriptionFallback": "Applied when direction=\"vertical\". Inline-flex stretch line."}, {"cls": "origam-divider--inset", "descriptionKey": "components.divider.anatomy.inset", "descriptionFallback": "Applied when inset=true. Adds a leading margin offset."}], "svgDesc": "Schematic of the Divider component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamDivider", "rootClass": "origam-divider", "figcaption": "Anatomy of <code>&lt;origam-divider&gt;</code>. Horizontal ① is full-width; vertical ② is inline-flex with height: auto. Both render as a native <code>&lt;hr&gt;</code>.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-divider---opacity", "defaultValue": "0.12", "descriptionKey": "components.divider.css_vars.opacity", "descriptionFallback": "Global opacity of the divider line. Token: {opacity.100} resolves to 1; the component overrides to 0.12 by default in SCSS."}, {"name": "--origam-divider---border-top-width", "defaultValue": "thin", "descriptionKey": "components.divider.css_vars.border_top_width", "descriptionFallback": "Stroke thickness for the horizontal divider. Overridden by the thickness prop."}, {"name": "--origam-divider---border-right-width", "defaultValue": "thin", "descriptionKey": "components.divider.css_vars.border_right_width", "descriptionFallback": "Stroke thickness for the vertical divider. Overridden by the thickness prop."}, {"name": "--origam-divider---max-width", "defaultValue": "100%", "descriptionKey": "components.divider.css_vars.max_width", "descriptionFallback": "Maximum width for horizontal dividers. Set by the length prop."}, {"name": "--origam-divider---max-height", "defaultValue": "100%", "descriptionKey": "components.divider.css_vars.max_height", "descriptionFallback": "Maximum height for vertical dividers. Set by the length prop."}, {"name": "--origam-divider--inset---margin-inline-start", "defaultValue": "16px", "descriptionKey": "components.divider.css_vars.inset_margin", "descriptionFallback": "Leading indent applied when inset=true."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.divider.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.divider.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed dividerStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.divider.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.divider.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.divider.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.divider.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.divider.playground.direction", "defaultValue": "horizontal", "labelFallback": "Direction"}, {"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.divider.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "switch", "prop": "inset", "labelKey": "components.divider.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "number", "prop": "thickness", "labelKey": "components.divider.playground.thickness", "defaultValue": 1, "labelFallback": "Thickness (px)"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6a5088da-e64a-4e0c-b797-1784f38dcaab', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'drawer', 'Drawer', 'Layout & Structure', NULL, 'mdi-page-layout-sidebar-left', 'components.catalog.drawer.description', 'Side-panel navigation drawer that integrates with the Origam layout grid. Supports rail/mini mode, expand-on-hover, temporary/persistent variants, touch drag, and four docking edges (left, right, top, bottom).', NULL, NULL, 'origam-drawer', NULL, 'packages/ds/src/components/Drawer/OrigamDrawer.vue', 'origam', NULL, NULL, '/stories/?story=components-drawer--design', '/docs/components/Drawer/OrigamDrawer.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.drawer.a11y.nav_note", "noteFallback": "The root element renders as <nav> by default (configurable via the tag prop). This gives it an implicit navigation landmark role, discoverable by screen reader landmark navigation."}, {"noteKey": "components.drawer.a11y.label_note", "noteFallback": "The root element carries aria-label set to the name prop (or \"Navigation\" as fallback). Provide a meaningful name prop when multiple navigation landmarks exist on the page."}, {"noteKey": "components.drawer.a11y.scrim_note", "noteFallback": "The scrim overlay in temporary mode is purely decorative and hidden from assistive technologies. It only handles click events to close the drawer."}], "roles": ["navigation"], "keyboard": [{"key": "Tab / Shift+Tab", "actionKey": "components.drawer.a11y.key_tab", "actionFallback": "Moves focus between interactive elements inside the drawer."}, {"key": "Escape", "actionKey": "components.drawer.a11y.key_escape", "actionFallback": "Closes the drawer when in temporary mode (if the overlay scrim is active)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-drawer---background", "descriptionKey": "components.drawer.tokens.background", "descriptionFallback": "Drawer surface background color."}, {"type": "shadow", "value": "var(--origam-shadow---none)", "tokenPath": "--origam-drawer---box-shadow", "descriptionKey": "components.drawer.tokens.box_shadow", "descriptionFallback": "Default shadow (none for permanent). Overridden to shadow.lg in temporary mode."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-drawer---transition-duration", "descriptionKey": "components.drawer.tokens.transition_duration", "descriptionFallback": "Open/close animation duration."}, {"type": "shadow", "value": "var(--origam-shadow---lg)", "tokenPath": "--origam-drawer__temporary---box-shadow", "descriptionKey": "components.drawer.tokens.temporary_box_shadow", "descriptionFallback": "Shadow applied when the drawer is in temporary mode to elevate it above the scrim."}, {"type": "color", "value": "var(--origam-color__overlay---scrim)", "tokenPath": "--origam-drawer__scrim---background", "descriptionKey": "components.drawer.tokens.scrim_background", "descriptionFallback": "Background of the scrim shown behind the temporary drawer."}, {"type": "number", "value": "0.2", "tokenPath": "--origam-drawer__scrim---opacity", "descriptionKey": "components.drawer.tokens.scrim_opacity", "descriptionFallback": "Scrim opacity in temporary mode. Tracks drag progress during touch open/close."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- drawer panel -->\n  <rect x=\"30\" y=\"20\" width=\"200\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- prepend zone -->\n  <rect x=\"30\" y=\"20\" width=\"200\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.07))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"130\" y=\"54\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#prepend</text>\n  <!-- content zone -->\n  <rect x=\"30\" y=\"80\" width=\"200\" height=\"140\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"130\" y=\"155\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default (scrollable)</text>\n  <!-- append zone -->\n  <rect x=\"30\" y=\"220\" width=\"200\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"130\" y=\"254\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#append</text>\n  <!-- layout reservation hint -->\n  <rect x=\"240\" y=\"20\" width=\"440\" height=\"260\" rx=\"4\" fill=\"rgba(0,0,0,0.02)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"6 4\"/>\n  <text x=\"460\" y=\"155\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">layout main content (offset by drawer width)</text>\n  <!-- numbering -->\n  <circle cx=\"38\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"88\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"92.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"38\" cy=\"228\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"38\" y=\"232.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"38\" cy=\"148\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"38\" y=\"152.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <!-- scrim overlay hint -->\n  <rect x=\"240\" y=\"20\" width=\"440\" height=\"260\" rx=\"4\" fill=\"rgba(0,0,0,0.06)\" stroke=\"rgba(0,0,0,0.1)\" stroke-width=\"1\" stroke-dasharray=\"3 3\" opacity=\"0.5\"/>\n  <text x=\"460\" y=\"40\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">scrim (temporary mode only)</text>\n", "code": "<teleport :to=\"layoutTarget\" :disabled=\"isLayoutOrphan\">\n  <origam-transition :transition=\"transition\">\n    <!-- root: nav by default -->\n    <nav v-if=\"isActive\" class=\"origam-drawer origam-drawer--left\">\n      <!-- inner wrapper: prepend | content | append -->\n      <div class=\"origam-drawer__wrapper\">\n        <!-- fixed header slot -->\n        <div class=\"origam-drawer__prepend\">\n          <slot name=\"prepend\" />\n        </div>\n\n        <!-- scrollable navigation content -->\n        <div class=\"origam-drawer__content\">\n          <slot name=\"default\" />\n        </div>\n\n        <!-- fixed footer slot -->\n        <div class=\"origam-drawer__append\">\n          <slot name=\"append\" />\n        </div>\n      </div>\n    </nav>\n  </origam-transition>\n\n  <!-- scrim: visible only in temporary mode -->\n  <origam-overlay-scrim :active=\"isTemporary && isActive\" @click=\"close\" />\n</teleport>", "legend": [{"cls": ".origam-drawer", "num": 1, "descriptionKey": "components.drawer.anatomy.root", "descriptionFallback": "Root nav element. Teleported into <code>#layout-id .origam-layout__wrapper</code> so it participates in the layout grid. Renders inline when no OrigamLayout ancestor exists."}, {"cls": ".origam-drawer__prepend", "num": 2, "descriptionKey": "components.drawer.anatomy.prepend", "descriptionFallback": "Fixed zone above the scrollable content. Rendered only when the #prepend slot is filled. <code>flex: none</code> so it does not participate in content scrolling."}, {"cls": ".origam-drawer__append", "num": 3, "descriptionKey": "components.drawer.anatomy.append", "descriptionFallback": "Fixed zone below the scrollable content. Rendered only when the #append slot is filled. <code>flex: none</code>."}, {"cls": ".origam-drawer__content", "num": 4, "descriptionKey": "components.drawer.anatomy.content", "descriptionFallback": "Scrollable content area hosting the #default slot. <code>overflow-y: auto</code>; fills remaining height between prepend and append."}], "classes": [{"cls": "origam-drawer", "descriptionKey": "components.drawer.anatomy.root", "descriptionFallback": "Root element. Controls all layout, transition, and z-index properties."}, {"cls": "origam-drawer--left", "descriptionKey": "components.drawer.anatomy.left", "descriptionFallback": "Applied when location=\"left\". Sets top: 0; left: 0 and right: auto, with border-right-width: thin."}, {"cls": "origam-drawer--right", "descriptionKey": "components.drawer.anatomy.right", "descriptionFallback": "Applied when location=\"right\". Sets top: 0; left: auto; right: 0, with border-left-width: thin."}, {"cls": "origam-drawer--temporary", "descriptionKey": "components.drawer.anatomy.temporary", "descriptionFallback": "Applied when temporary=true. Applies shadow.lg and shows the scrim."}, {"cls": "origam-drawer--rail", "descriptionKey": "components.drawer.anatomy.rail", "descriptionFallback": "Applied when rail=true. Collapses width to railWidth (default 56px)."}, {"cls": "origam-drawer--expand-on-hover", "descriptionKey": "components.drawer.anatomy.expand_on_hover", "descriptionFallback": "Applied when expandOnHover=true. Enables the hover-triggered width transition."}, {"cls": "origam-drawer--floating", "descriptionKey": "components.drawer.anatomy.floating", "descriptionFallback": "Applied when floating=true. Removes the side border."}, {"cls": "origam-drawer--sticky", "descriptionKey": "components.drawer.anatomy.sticky", "descriptionFallback": "Applied when sticky=true. Switches height to auto and uses position: sticky."}, {"cls": "origam-drawer__wrapper", "descriptionKey": "components.drawer.anatomy.wrapper", "descriptionFallback": "Inner flex container. Hosts prepend, content, and append zones in a column layout."}, {"cls": "origam-drawer__content", "descriptionKey": "components.drawer.anatomy.content", "descriptionFallback": "Scrollable main area. overflow-y: auto; flex: 0 1 auto; height: 100%."}, {"cls": "origam-drawer__prepend", "descriptionKey": "components.drawer.anatomy.prepend", "descriptionFallback": "Fixed header area. flex: none."}, {"cls": "origam-drawer__append", "descriptionKey": "components.drawer.anatomy.append", "descriptionFallback": "Fixed footer area. flex: none."}], "svgDesc": "Schematic of the Drawer component showing the three-zone layout: prepend, content, append.", "svgTitle": "Anatomy of OrigamDrawer", "rootClass": "origam-drawer", "figcaption": "Anatomy of <code>&lt;origam-drawer&gt;</code> — 4 parts: ① root drawer panel (teleported into the layout grid), ② prepend zone (fixed header), ③ append zone (fixed footer), ④ scrollable content (#default slot).", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-drawer---background", "defaultValue": "{color.surface.default}", "descriptionKey": "components.drawer.css_vars.background", "descriptionFallback": "Background color of the drawer panel."}, {"name": "--origam-drawer---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.drawer.css_vars.color", "descriptionFallback": "Foreground (text/icon) color."}, {"name": "--origam-drawer---box-shadow", "defaultValue": "{shadow.none}", "descriptionKey": "components.drawer.css_vars.box_shadow", "descriptionFallback": "Box shadow. Applied to shadow.lg automatically in temporary mode."}, {"name": "--origam-drawer---width", "defaultValue": "100%", "descriptionKey": "components.drawer.css_vars.width", "descriptionFallback": "Drawer panel width. Driven by the width prop and layout item styles (useLayoutItem)."}, {"name": "--origam-drawer---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.drawer.css_vars.transition_duration", "descriptionFallback": "Duration of the open/close slide animation."}, {"name": "--origam-drawer---transition-timing-function", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.drawer.css_vars.transition_timing_function", "descriptionFallback": "Easing function for the open/close transition."}, {"name": "--origam-drawer__scrim---background", "defaultValue": "{color.overlay.scrim}", "descriptionKey": "components.drawer.css_vars.scrim_background", "descriptionFallback": "Scrim overlay background color (temporary mode)."}, {"name": "--origam-drawer__scrim---opacity", "defaultValue": "0.2", "descriptionKey": "components.drawer.css_vars.scrim_opacity", "descriptionFallback": "Scrim opacity. Animates with drag progress during touch drag."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.drawer.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.drawer.exposed.css", "descriptionFallback": "Reactive CSS string from drawerStyles. Used by OrigamDefaultsProvider."}, {"name": "id", "type": "string", "descriptionKey": "components.drawer.exposed.id", "descriptionFallback": "Unique style-sheet ID for this drawer instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.drawer.exposed.load", "descriptionFallback": "Injects the computed style sheet on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.drawer.exposed.unload", "descriptionFallback": "Removes the injected style sheet on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.drawer.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "location", "options": [{"label": "left", "value": "left"}, {"label": "right", "value": "right"}, {"label": "top", "value": "top"}, {"label": "bottom", "value": "bottom"}], "labelKey": "components.drawer.playground.location", "defaultValue": "left", "labelFallback": "Location"}, {"kind": "switch", "prop": "temporary", "labelKey": "components.drawer.playground.temporary", "defaultValue": false, "labelFallback": "Temporary"}, {"kind": "switch", "prop": "rail", "labelKey": "components.drawer.playground.rail", "defaultValue": false, "labelFallback": "Rail mode"}, {"kind": "switch", "prop": "expandOnHover", "labelKey": "components.drawer.playground.expand_on_hover", "defaultValue": false, "labelFallback": "Expand on hover"}, {"kind": "switch", "prop": "floating", "labelKey": "components.drawer.playground.floating", "defaultValue": false, "labelFallback": "Floating (no border)"}], "defaultSlotContent": "Navigation content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b62617fe-63b5-46ef-8ebd-5c57bd1cb25c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'empty-state', 'EmptyState', 'Feedback & Status', NULL, 'mdi-inbox-outline', 'components.catalog.empty_state.description', 'Placeholder shown when a list, table or collection has nothing to display. Five visual presets (no-data, no-results, error, offline, locked) bundle icon + intent; both are overridable via props or slots.', NULL, NULL, 'origam-empty-state', NULL, 'packages/ds/src/components/EmptyState/OrigamEmptyState.vue', 'origam', NULL, NULL, '/stories/?story=components-emptystate--design', '/docs/components/EmptyState/OrigamEmptyState.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.empty_state.a11y.live_region", "noteFallback": "The root has role=\"status\" and aria-live=\"polite\". Screen readers announce the state change when the component appears or when preset changes without a page reload."}, {"noteKey": "components.empty_state.a11y.icon_hidden", "noteFallback": "The icon container carries aria-hidden=\"true\" — it is decorative. The meaningful information is in the title and description text nodes."}, {"noteKey": "components.empty_state.a11y.actions", "noteFallback": "Actions inside the #actions slot must individually carry correct roles (button, link). EmptyState does not wrap or intercept keyboard events."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---10)", "tokenPath": "--origam-empty-state---padding-block-md", "descriptionKey": "components.empty_state.tokens.padd