fault\">\n  <svg :viewBox=\"svgViewBox\">\n    <!-- background ring -->\n    <circle class=\"origam-progress__underlay\" />\n    <!-- foreground progress arc -->\n    <circle class=\"origam-progress__overlay\" :stroke-dashoffset=\"strokeDashOffset\" />\n  </svg>\n  <!-- optional center slot -->\n  <div class=\"origam-progress__content\">\n    <slot :value=\"normalizedValue\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-progress--circular", "num": 1, "descriptionKey": "components.progress_circular.anatomy.root", "descriptionFallback": "Root element. <code>display: inline-flex; position: relative</code>. Size driven by size prop via useSize → <code>origam-progress--size-{size}</code> modifier."}, {"cls": ".origam-progress__underlay", "num": 2, "descriptionKey": "components.progress_circular.anatomy.underlay", "descriptionFallback": "Background SVG circle (<code>&lt;circle&gt;</code>). Color from bgColor prop. Opacity 0.5 by default. z-index: 1."}, {"cls": ".origam-progress__overlay", "num": 3, "descriptionKey": "components.progress_circular.anatomy.overlay", "descriptionFallback": "Foreground SVG arc. stroke-dashoffset driven by normalised value. In indeterminate mode: animated via CSS keyframes. z-index: 2."}, {"cls": ".origam-progress__content", "num": 4, "descriptionKey": "components.progress_circular.anatomy.content", "descriptionFallback": "Center content area. Rendered only when the #default slot is filled. <code>display: flex; align-items: center; justify-content: center</code>."}], "classes": [{"cls": "origam-progress--circular", "descriptionKey": "components.progress_circular.anatomy.root", "descriptionFallback": "Root BEM block. Always present on the host element."}, {"cls": "origam-progress--size-{size}", "descriptionKey": "components.progress_circular.anatomy.size_modifier", "descriptionFallback": "Size modifier emitted by useSize. Sets fixed width/height (16/24/32/48/64 px)."}, {"cls": "origam-progress--indeterminate", "descriptionKey": "components.progress_circular.anatomy.indeterminate", "descriptionFallback": "Applied when indeterminate=true. Triggers the CSS spin/dash animations."}, {"cls": "origam-progress__underlay", "descriptionKey": "components.progress_circular.anatomy.underlay", "descriptionFallback": "Background ring SVG circle."}, {"cls": "origam-progress__overlay", "descriptionKey": "components.progress_circular.anatomy.overlay", "descriptionFallback": "Foreground arc SVG circle."}, {"cls": "origam-progress__content", "descriptionKey": "components.progress_circular.anatomy.content", "descriptionFallback": "Centered inner content container (shown only when default slot is used)."}], "svgDesc": "Schematic of the ProgressCircular component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamProgressCircular", "rootClass": "origam-progress--circular", "figcaption": "Anatomy of <code>&lt;origam-progress-circular&gt;</code> — 4 internal parts: root container ①, background SVG ring ②, foreground SVG arc ③, and content slot for inner label ④.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-progress-circular__underlay---color", "defaultValue": "{color.surface.disabled}", "descriptionKey": "components.progress_circular.css_vars.underlay_color", "descriptionFallback": "Color of the background ring. Resolves to neutral.200 (light) / neutral.800 (dark)."}, {"name": "--origam-progress-circular__underlay---opacity", "defaultValue": "0.5", "descriptionKey": "components.progress_circular.css_vars.underlay_opacity", "descriptionFallback": "Opacity of the background ring."}, {"name": "--origam-progress-circular__overlay---color", "defaultValue": "inherit", "descriptionKey": "components.progress_circular.css_vars.overlay_color", "descriptionFallback": "Foreground arc color. Overridden at runtime by the color prop via useTextColor."}, {"name": "--origam-progress-circular---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.progress_circular.css_vars.transition_duration", "descriptionFallback": "Duration of the stroke-dashoffset transition in determinate mode."}, {"name": "--origam-progress-circular---transition-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.progress_circular.css_vars.transition_easing", "descriptionFallback": "Easing function for the stroke transition."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.progress_circular.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.progress_circular.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.progress_circular.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.progress_circular.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.progress_circular.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.progress_circular.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "number", "prop": "modelValue", "labelKey": "components.progress_circular.playground.model_value", "defaultValue": 60, "labelFallback": "Value (0-100)"}, {"kind": "switch", "prop": "indeterminate", "labelKey": "components.progress_circular.playground.indeterminate", "defaultValue": false, "labelFallback": "Indeterminate"}, {"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "seco