extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.picker_title.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.picker_title.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed pickerTitleStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.picker_title.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.picker_title.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.picker_title.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.picker_title.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.picker_title.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.picker_title.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.picker_title.playground.title", "defaultValue": "", "labelFallback": "Title"}], "defaultSlotContent": "My title"}, "previewVariants": [{"label": "default", "props": {"title": "Select a date"}}, {"label": "primary bg", "props": {"color": "white", "title": "Pick color", "bgColor": "primary"}}, {"label": "success bg", "props": {"color": "white", "title": "Confirmed", "bgColor": "success"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('947971e9-2999-4973-822e-e3f5efaf2356', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'progress-linear', 'ProgressLinear', 'Feedback & Status', NULL, 'mdi-progress-helper', 'components.catalog.progress_linear.description', 'Horizontal progress bar with determinate, indeterminate, buffer, stream and clickable modes.', NULL, NULL, 'origam-progress-linear', NULL, 'packages/ds/src/components/Progress/OrigamProgressLinear.vue', 'origam', NULL, NULL, '/stories/?story=components-progress-linear--design', '/docs/components/Progress/OrigamProgressLinear.html', 'progress', '{"a11y": {"notes": [{"noteKey": "components.progress_linear.a11y.progressbar_note", "noteFallback": "role=\"progressbar\" is applied by the progress composable along with aria-valuenow, aria-valuemin (0) and aria-valuemax."}, {"noteKey": "components.progress_linear.a11y.label_note", "noteFallback": "Pass the label prop with a localised string to set aria-label. Defaults to \"Loading\"."}, {"noteKey": "components.progress_linear.a11y.clickable_note", "noteFallback": "When clickable=true, the bar is interactive. Ensure an aria-label describes what clicking does (e.g. \"Seek video\")."}, {"noteKey": "components.progress_linear.a11y.reduced_motion_note", "noteFallback": "Under prefers-reduced-motion: reduce, indeterminate bars are frozen at 50% width and streams stop animating."}], "roles": ["progressbar"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "100%", "tokenPath": "--origam-progress-linear---width", "descriptionKey": "components.progress_linear.tokens.width", "descriptionFallback": "Bar always fills its container width."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-progress-linear---rounded-border-radius", "descriptionKey": "components.progress_linear.tokens.rounded_border_radius", "descriptionFallback": "Border radius used when rounded=true."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-progress-linear---transition-duration", "descriptionKey": "components.progress_linear.tokens.transition_duration", "descriptionFallback": "Duration of width transitions in determinate mode."}, {"type": "duration", "value": "2200ms", "tokenPath": "--origam-progress-linear---indeterminate-duration", "descriptionKey": "components.progress_linear.tokens.indeterminate_duration", "descriptionFallback": "Duration of the indeterminate bar CSS animations."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f8f9fa)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"60\" width=\"644\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"28\" y=\"60\" width=\"280\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__surface---disabled, #e9d5ff)\" opacity=\"0.5\"/>\n  <rect x=\"28\" y=\"60\" width=\"180\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <rect x=\"308\" y=\"66\" width=\"4\" height=\"8\" rx=\"1\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" opacity=\"0.4\"/>\n  <rect x=\"316\" y=\"66\" width=\"4\" height=\"8\" rx=\"1\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" opacity=\"0.4\"/>\n  <rect x=\"324\" y=\"66\" width=\"4\" height=\"8\" rx=\"1\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" opacity=\"0.3\"/>\n  <circle cx=\"36\" cy=\"60\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"64.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"120\" cy=\"50\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"120\" y=\"54.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"280\" cy=\"50\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"280\" y=\"54.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"350\" cy=\"60\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"64.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"350\" cy=\"90\" r=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"94.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"400\" y=\"100\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">① root wrapper (div.origam-progress--linear)</text>\n  <text x=\"400\" y=\"120\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">② div.origam-progress__background (track)</text>\n  <text x=\"400\" y=\"140\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">③ div.origam-progress__loader &gt; __bar</text>\n  <text x=\"400\" y=\"160\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">④ div.origam-progress__stream (buffer dots)</text>\n  <text x=\"400\" y=\"180\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">⑤ div.origam-progress__content (slot)</text>\n", "code": "<div class=\"origam-progress--linear\">\n  <!-- stream dots (stream=true only) -->\n  <div v-if=\"stream\" class=\"origam-progress__stream\" />\n  <!-- background track -->\n  <div class=\"origam-progress__background\" />\n  <!-- animated loader (determinate or indeterminate) -->\n  <origam-transition :transition=\"transition\">\n    <div class=\"origam-progress__loader\">\n      <div class=\"origam-progress__bar\" />          <!-- determinate -->\n      <div class=\"origam-progress__bar--long\" />    <!-- indeterminate only -->\n      <div class=\"origam-progress__bar--short\" />   <!-- indeterminate only -->\n    </div>\n  </origam-transition>\n  <!-- optional slot content -->\n  <div v-if=\"hasContent\" class=\"origam-progress__content\">\n    <slot :value=\"normalizedValue\" :buffer=\"normalizedBuffer\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-progress--linear", "num": 1, "descriptionKey": "components.progress_linear.anatomy.root", "descriptionFallback": "Root element. <code>overflow: hidden; position: relative; width: 100%</code>. Height set inline from thickness prop."}, {"cls": ".origam-progress__background", "num": 2, "descriptionKey": "components.progress_linear.anatomy.background", "descriptionFallback": "Background track — absolute, full-width until buffer narrows it. Color from bgColor prop via useTextColor, opacity 0.5."}, {"cls": ".origam-progress__loader > .origam-progress__bar", "num": 3, "descriptionKey": "components.progress_linear.anatomy.loader", "descriptionFallback": "Foreground loader container + bar(s). In indeterminate mode two bars (--long and --short) animate simultaneously. Width driven by normalised value in determinate mode."}, {"cls": ".origam-progress__stream", "num": 4, "descriptionKey": "components.progress_linear.anatomy.stream", "descriptionFallback": "Animated dot-stream rendered only when stream=true. Positioned after the buffer zone. Opacity: 0.3."}, {"cls": ".origam-progress__content", "num": 5, "descriptionKey": "components.progress_linear.anatomy.content", "descriptionFallback": "Absolute overlay for the #default slot. Rendered only when hasContent is true."}], "classes": [{"cls": "origam-progress--linear", "descriptionKey": "components.progress_linear.anatomy.root", "descriptionFallback": "Root BEM block."}, {"cls": "origam-progress--indeterminate", "descriptionKey": "components.progress_linear.anatomy.indeterminate", "descriptionFallback": "Applied when indeterminate=true. Starts the CSS animations."}, {"cls": "origam-progress--reverse", "descriptionKey": "components.progress_linear.anatomy.reverse", "descriptionFallback": "Applied when isReversed is true (reverse prop XOR RTL)."}, {"cls": "origam-progress--rounded", "descriptionKey": "components.progress_linear.anatomy.rounded", "descriptionFallback": "Applied when rounded=true. Sets border-radius: 9999px on root and loader."}, {"cls": "origam-progress--absolute", "descriptionKey": "components.progress_linear.anatomy.absolute", "descriptionFallback": "Applied when absolute=true. Position: absolute; left: 0; z-index: 1."}, {"cls": "origam-progress--fixed", "descriptionKey": "components.progress_linear.anatomy.fixed", "descriptionFallback": "Applied when the component is fixed to the viewport."}, {"cls": "origam-progress__background", "descriptionKey": "components.progress_linear.anatomy.background", "descriptionFallback": "Background track element."}, {"cls": "origam-progress__loader", "descriptionKey": "components.progress_linear.anatomy.loader", "descriptionFallback": "Foreground progress container."}, {"cls": "origam-progress__bar", "descriptionKey": "components.progress_linear.anatomy.bar", "descriptionFallback": "Individual bar stripe. One in determinate mode, two in indeterminate."}, {"cls": "origam-progress__stream", "descriptionKey": "components.progress_linear.anatomy.stream", "descriptionFallback": "Buffer stream dots (stream=true)."}, {"cls": "origam-progress__content", "descriptionKey": "components.progress_linear.anatomy.content", "descriptionFallback": "Absolute centered slot container."}], "svgDesc": "Schematic of the ProgressLinear component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamProgressLinear", "rootClass": "origam-progress--linear", "figcaption": "Anatomy of <code>&lt;origam-progress-linear&gt;</code> — 5 internal parts: root ①, background track ②, foreground bar ③, stream indicator ④ (buffer mode only), and content slot ⑤.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-progress-linear__background---color", "defaultValue": "inherit", "descriptionKey": "components.progress_linear.css_vars.background_color", "descriptionFallback": "Background track color. Inherits from bgColor prop via useTextColor."}, {"name": "--origam-progress-linear__background---opacity", "defaultValue": "0.5", "descriptionKey": "components.progress_linear.css_vars.background_opacity", "descriptionFallback": "Background track opacity."}, {"name": "--origam-progress-linear__loader---color", "defaultValue": "inherit", "descriptionKey": "components.progress_linear.css_vars.loader_color", "descriptionFallback": "Foreground bar color. Inherits from color prop via useTextColor."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.progress_linear.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.progress_linear.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.progress_linear.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.progress_linear.exposed.load", "descriptionFallback": "Injects the computed style sheet."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.progress_linear.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.progress_linear.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "number", "prop": "modelValue", "labelKey": "components.progress_linear.playground.model_value", "defaultValue": 45, "labelFallback": "Value (0-100)"}, {"kind": "switch", "prop": "indeterminate", "labelKey": "components.progress_linear.playground.indeterminate", "defaultValue": false, "labelFallback": "Indeterminate"}, {"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.progress_linear.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "rounded", "labelKey": "components.progress_linear.playground.rounded", "defaultValue": false, "labelFallback": "Rounded"}, {"kind": "switch", "prop": "stream", "labelKey": "components.progress_linear.playground.stream", "defaultValue": false, "labelFallback": "Stream (buffer mode)"}]}, "previewVariants": [{"label": "determinate 40%", "props": {"color": "primary", "modelValue": 40}}, {"label": "indeterminate", "props": {"color": "primary", "indeterminate": true}}, {"label": "buffer", "props": {"color": "info", "stream": true, "modelValue": 30, "bufferValue": 60}}, {"label": "rounded", "props": {"color": "success", "rounded": true, "modelValue": 70}}, {"label": "thick", "props": {"color": "warning", "thickness": 12, "modelValue": 55}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e30b7c9b-0d54-4681-b626-fece4d967cf0', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'qr-code', 'QrCode', 'Data Display', NULL, 'mdi-qrcode', 'components.catalog.qr_code.description', 'SSR-safe SVG QR code renderer with configurable error correction level, quiet zone, module corner radius, optional title, and a centred icon/image overlay. Accepts any text or URL via the value prop.', NULL, NULL, 'origam-qr-code', NULL, 'packages/ds/src/components/QrCode/OrigamQrCode.vue', 'origam', NULL, NULL, '/stories/?story=components-qrcode--design', '/docs/components/QrCode/OrigamQrCode.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.qr_code.a11y.role_note", "noteFallback": "The root element has role=\"img\" and aria-label. When ariaLabel is not set, it falls back to \"QR code for {value}\". This ensures screen readers announce the purpose without exposing the raw URL twice."}, {"noteKey": "components.qr_code.a11y.center_note", "noteFallback": "The center overlay (icon, image, or #center slot) is marked aria-hidden=\"true\" since it is purely decorative — the aria-label on the root already conveys the full meaning."}, {"noteKey": "components.qr_code.a11y.error_level_note", "noteFallback": "When using a logo overlay, use errorCorrectionLevel=\"H\" (30% redundancy). Lower levels may make the code unscannable when modules are occluded by the overlay."}], "roles": ["img"], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"200\" y=\"20\" width=\"300\" height=\"240\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"50\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-qr-code__title</text>\n  <rect x=\"220\" y=\"58\" width=\"260\" height=\"160\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"350\" y=\"135\" font-size=\"32\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">⬛</text>\n  <text x=\"350\" y=\"160\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-qr-code__svg-host</text>\n  <circle cx=\"350\" cy=\"120\" r=\"24\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.2))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"125\" font-size=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">◆</text>\n  <text x=\"350\" y=\"235\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-qr-code__center (icon/image/#center slot)</text>\n  <circle cx=\"196\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"196\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"196\" cy=\"50\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"196\" y=\"54\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"196\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"196\" y=\"66\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"324\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"324\" y=\"104\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"196\" cy=\"232\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"196\" y=\"236\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-qr-code\" role=\"img\" :aria-label=\"resolvedAriaLabel\">\n  <!-- optional title above the matrix -->\n  <div v-if=\"title\" class=\"origam-qr-code__title\">{{ title }}</div>\n\n  <!-- SVG host + center overlay -->\n  <div class=\"origam-qr-code__svg-host\">\n    <!-- inline SVG generated by qrcode-generator -->\n    <!-- v-html: the SVG string is sanitized and contains only geometric elements -->\n\n    <!-- centred overlay (icon / image / #center slot) -->\n    <div class=\"origam-qr-code__center\" aria-hidden=\"true\">\n      <slot name=\"center\" :size=\"centerSize\">\n        <origam-avatar\n          v-if=\"image\"\n          class=\"origam-qr-code__center-avatar\"\n        />\n        <origam-icon\n          v-else-if=\"icon\"\n          class=\"origam-qr-code__center-icon\"\n          :icon=\"icon\"\n        />\n      </slot>\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-qr-code", "num": 1, "descriptionKey": "components.qr_code.anatomy.root", "descriptionFallback": "Root wrapper element. Has role=\"img\" and aria-label. Applies wrapper-level color, bgColor, rounded, border, elevation, size, padding, margin."}, {"cls": ".origam-qr-code__title", "num": 2, "descriptionKey": "components.qr_code.anatomy.title", "descriptionFallback": "Optional heading rendered above the SVG. Only present when the title prop is set."}, {"cls": ".origam-qr-code__svg-host", "num": 3, "descriptionKey": "components.qr_code.anatomy.svg_host", "descriptionFallback": "Container div that hosts the inline SVG element and the center overlay. Manages the relative positioning context."}, {"cls": "inline SVG (matrix)", "num": 4, "descriptionKey": "components.qr_code.anatomy.svg", "descriptionFallback": "The QR matrix rendered as an inline SVG by qrcode-generator. Module color and corner radius are applied here from qrCodeProps."}, {"cls": ".origam-qr-code__center", "num": 5, "descriptionKey": "components.qr_code.anatomy.center", "descriptionFallback": "Absolutely centered overlay zone. Renders the icon (origam-qr-code__center-icon), image (origam-qr-code__center-avatar), or #center slot. aria-hidden=\"true\"."}], "classes": [{"cls": "origam-qr-code", "descriptionKey": "components.qr_code.anatomy.root", "descriptionFallback": "Root wrapper with role=\"img\"."}, {"cls": "origam-qr-code__title", "descriptionKey": "components.qr_code.anatomy.title", "descriptionFallback": "Optional title heading above the matrix."}, {"cls": "origam-qr-code__svg-host", "descriptionKey": "components.qr_code.anatomy.svg_host", "descriptionFallback": "SVG + center overlay container."}, {"cls": "origam-qr-code__center", "descriptionKey": "components.qr_code.anatomy.center", "descriptionFallback": "Absolutely centered overlay for icon/image/slot. aria-hidden=\"true\"."}, {"cls": "origam-qr-code__center-icon", "descriptionKey": "components.qr_code.anatomy.center_icon", "descriptionFallback": "OrigamIcon rendered at the center when icon prop is set."}, {"cls": "origam-qr-code__center-avatar", "descriptionKey": "components.qr_code.anatomy.center_avatar", "descriptionFallback": "OrigamAvatar rendered at the center when image prop is set."}], "svgDesc": "Schematic of the QrCode component with 5 numbered parts.", "svgTitle": "Anatomy of OrigamQrCode", "rootClass": "origam-qr-code", "figcaption": "Anatomy of <code>&lt;origam-qr-code&gt;</code> — 5 parts: wrapper root, optional title, SVG host, inline SVG matrix, and the centred overlay zone (#center slot).", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-qrcode---foreground", "defaultValue": "{color.text.primary}", "descriptionKey": "components.qr_code.css_vars.foreground", "descriptionFallback": "Default module (dark square) fill color."}, {"name": "--origam-qrcode---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.qr_code.css_vars.background_color", "descriptionFallback": "Default quiet-zone and SVG background color."}, {"name": "--origam-qrcode---size-sm", "defaultValue": "120px", "descriptionKey": "components.qr_code.css_vars.size_sm", "descriptionFallback": "Wrapper width/height for size=\"small\"."}, {"name": "--origam-qrcode---size-md", "defaultValue": "240px", "descriptionKey": "components.qr_code.css_vars.size_md", "descriptionFallback": "Wrapper width/height for size=\"default\" (medium)."}, {"name": "--origam-qrcode---size-lg", "defaultValue": "480px", "descriptionKey": "components.qr_code.css_vars.size_lg", "descriptionFallback": "Wrapper width/height for size=\"large\"."}, {"name": "--origam-qrcode__module---corner-radius", "defaultValue": "0", "descriptionKey": "components.qr_code.css_vars.module_corner_radius", "descriptionFallback": "Per-module corner radius in module units. 0 = square, 0.5 = circle."}, {"name": "--origam-qrcode__logo---padding", "defaultValue": "{space.2}", "descriptionKey": "components.qr_code.css_vars.logo_padding", "descriptionFallback": "Pixel padding of the opaque backdrop drawn around the logo overlay."}], "playground": {"controls": [{"kind": "text", "prop": "value", "labelKey": "components.qr_code.playground.value", "defaultValue": "https://origam.dev", "labelFallback": "URL / text"}, {"kind": "select", "prop": "errorCorrectionLevel", "options": [{"label": "L (7%)", "value": "L"}, {"label": "M (15%)", "value": "M"}, {"label": "Q (25%)", "value": "Q"}, {"label": "H (30%)", "value": "H"}], "labelKey": "components.qr_code.playground.error_correction_level", "defaultValue": "M", "labelFallback": "Error correction"}, {"kind": "select", "prop": "size", "options": [{"label": "small (120px)", "value": "small"}, {"label": "default (240px)", "value": "default"}, {"label": "large (480px)", "value": "large"}], "labelKey": "components.qr_code.playground.size", "defaultValue": "default", "labelFallback": "Size"}, {"kind": "number", "prop": "quietZone", "labelKey": "components.qr_code.playground.quiet_zone", "defaultValue": 4, "labelFallback": "Quiet zone"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}], "labelKey": "components.qr_code.playground.rounded", "defaultValue": "", "labelFallback": "Wrapper rounded"}, {"kind": "switch", "prop": "border", "labelKey": "components.qr_code.playground.border", "defaultValue": false, "labelFallback": "Border"}]}, "previewVariants": [{"label": "default", "props": {"value": "https://origam.dev"}, "ariaLabel": "QR code for origam.dev"}, {"label": "with icon", "props": {"icon": "mdi-vuejs", "value": "https://origam.dev", "errorCorrectionLevel": "H"}, "ariaLabel": "QR code with Vue icon overlay"}, {"label": "card", "props": {"value": "https://origam.dev", "border": true, "padding": "3", "rounded": "lg", "elevation": "sm"}, "ariaLabel": "QR code as card"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0c8e7bf5-7b41-4bf2-bf6c-1ab24347c95b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'radio', 'Radio', 'Form & Input', NULL, 'mdi-radiobox-marked', 'components.catalog.radio.description', 'Single-selection radio control with label, error and focus state support. Wraps OrigamRadioBtn inside OrigamInput.', NULL, NULL, 'origam-radio', NULL, 'packages/ds/src/components/Radio/OrigamRadio.vue', 'origam', NULL, NULL, '/stories/?story=components-radio--design', '/docs/components/Radio/OrigamRadio.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.radio.a11y.disabled_note", "noteFallback": "When disabled, aria-disabled=\"true\" is set on the native input. Pointer events are suppressed via CSS."}, {"noteKey": "components.radio.a11y.label_note", "noteFallback": "The label is associated with the input via the for/id pair managed by OrigamLabel. Clicking the label activates the control."}, {"noteKey": "components.radio.a11y.group_note", "noteFallback": "RadioGroup sets aria-labelledby and aria-describedby on the group container for screen-reader announcements."}], "roles": ["radio"], "keyboard": [{"key": "Space", "actionKey": "components.radio.a11y.key_space", "actionFallback": "Selects the radio when focused."}, {"key": "Tab", "actionKey": "components.radio.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}, {"key": "Arrow keys (in group)", "actionKey": "components.radio.a11y.key_arrows", "actionFallback": "Navigates between radio options in a RadioGroup."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"480\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"440\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <circle cx=\"70\" cy=\"90\" r=\"30\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\"/>\n  <circle cx=\"70\" cy=\"90\" r=\"12\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <rect x=\"120\" y=\"78\" width=\"200\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"220\" y=\"95\" font-size=\"12\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label text</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"70\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"70\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"70\" cy=\"90\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"70\" y=\"94\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"130\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"130\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<!-- root: OrigamInput wrapper -->\n<div class=\"origam-radio origam-input\">\n  <!-- SelectionControl owns the ripple zone + native input -->\n  <origam-radio-btn class=\"origam-radio-btn\">\n    <origam-selection-control class=\"origam-selection-control\" type=\"radio\">\n      <!-- input zone with ripple -->\n      <div class=\"origam-selection-control__input\">\n        <origam-icon :icon=\"trueIcon\" />   <!-- dot when checked -->\n        <input type=\"radio\" />\n      </div>\n      <!-- label -->\n      <div class=\"origam-selection-control__label\">\n        <origam-label />\n      </div>\n    </origam-selection-control>\n  </origam-radio-btn>\n</div>", "legend": [{"cls": ".origam-radio", "num": 1, "descriptionKey": "components.radio.anatomy.root", "descriptionFallback": "Root element. Wraps OrigamInput providing messages, error and label orchestration."}, {"cls": ".origam-selection-control", "num": 2, "descriptionKey": "components.radio.anatomy.selection_control", "descriptionFallback": "Inner SelectionControl hosting the ripple zone, the native input and the label."}, {"cls": ".origam-selection-control__input", "num": 3, "descriptionKey": "components.radio.anatomy.input", "descriptionFallback": "Circular input zone with the ripple directive. Contains the native <input type=\"radio\">."}, {"cls": ".origam-radio__dot (via MDI icon)", "num": 4, "descriptionKey": "components.radio.anatomy.dot", "descriptionFallback": "Checked-state dot rendered by the trueIcon (mdi-radiobox-marked). Scales with size."}, {"cls": ".origam-selection-control__label", "num": 5, "descriptionKey": "components.radio.anatomy.label", "descriptionFallback": "Label container. Renders OrigamLabel with color and for wiring."}], "classes": [{"cls": "origam-radio", "descriptionKey": "components.radio.anatomy.root", "descriptionFallback": "Root block element wrapping OrigamInput."}, {"cls": "origam-radio-btn", "descriptionKey": "components.radio.anatomy.radio_btn", "descriptionFallback": "RadioBtn sub-component wrapping SelectionControl."}, {"cls": "origam-selection-control", "descriptionKey": "components.radio.anatomy.selection_control", "descriptionFallback": "SelectionControl providing ripple, focus and state management."}, {"cls": "origam-selection-control__input", "descriptionKey": "components.radio.anatomy.sc_input", "descriptionFallback": "Circular ripple zone containing the native radio input."}, {"cls": "origam-selection-control__label", "descriptionKey": "components.radio.anatomy.sc_label", "descriptionFallback": "Label wrapper rendered via OrigamLabel."}], "svgDesc": "Schematic of the Radio component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamRadio", "rootClass": "origam-radio", "figcaption": "Anatomy of <code>&lt;origam-radio&gt;</code> — 5 internal parts: the Input wrapper ①, the SelectionControl ②, the circular input ③, the selection dot ④, and the label ⑤.", "svgViewBox": "0 0 480 180"}, "cssVars": [{"name": "--origam-radio__input---size", "defaultValue": "20px", "descriptionKey": "components.radio.css_vars.input_size", "descriptionFallback": "Diameter of the circular radio input visual."}, {"name": "--origam-radio__input---border-color", "defaultValue": "{color.border.default}", "descriptionKey": "components.radio.css_vars.input_border_color", "descriptionFallback": "Border color of the unchecked radio."}, {"name": "--origam-radio__input---border-color-checked", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.radio.css_vars.input_border_color_checked", "descriptionFallback": "Border color when the radio is checked."}, {"name": "--origam-radio__input---border-color-disabled", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.radio.css_vars.input_border_color_disabled", "descriptionFallback": "Border color when the radio is disabled."}, {"name": "--origam-radio__dot---size", "defaultValue": "10px", "descriptionKey": "components.radio.css_vars.dot_size", "descriptionFallback": "Diameter of the inner dot rendered when checked."}, {"name": "--origam-radio__dot---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.radio.css_vars.dot_background_color", "descriptionFallback": "Background color of the inner dot."}, {"name": "--origam-selection-control--density", "defaultValue": "0px", "descriptionKey": "components.radio.css_vars.density", "descriptionFallback": "Density modifier offset: compact → -8px, comfortable → +8px."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.radio.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.radio.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed radioStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.radio.exposed.id", "descriptionFallback": "Computed input id (prop or auto-generated)."}, {"name": "load", "type": "() => void", "descriptionKey": "components.radio.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.radio.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.radio.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}, {"name": "styleId", "type": "string", "descriptionKey": "components.radio.exposed.style_id", "descriptionFallback": "Unique style-sheet ID for this instance."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.radio.playground.color", "defaultValue": "primary", "labelFallback": "Color / Intent"}, {"kind": "text", "prop": "label", "labelKey": "components.radio.playground.label", "defaultValue": "Radio option", "labelFallback": "Label"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.radio.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.radio.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.radio.playground.readonly", "defaultValue": false, "labelFallback": "Readonly"}], "defaultSlotContent": ""}, "previewVariants": [{"label": "default", "props": {"color": "primary"}, "slotContent": "Default"}, {"label": "checked", "props": {"color": "primary", "value": "a", "modelValue": "a"}, "slotContent": "Checked"}, {"label": "success", "props": {"color": "success", "value": "b", "modelValue": "b"}, "slotContent": "Success"}, {"label": "danger", "props": {"color": "danger"}, "slotContent": "Error"}, {"label": "disabled", "props": {"disabled": true}, "ariaLabel": "Disabled radio", "slotContent": "Disabled"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('03006f57-36a2-4442-b9d8-3a63b92779ad', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'radio-btn', 'RadioBtn', 'Form & Input', NULL, 'mdi-radiobox-marked', 'components.catalog.radio_btn.description', 'Individual radio button control wrapping OrigamSelectionControl with type="radio" and animated dot icon.', NULL, NULL, 'origam-radio-btn', NULL, 'packages/ds/src/components/Radio/OrigamRadioBtn.vue', 'origam', NULL, NULL, '/stories/?story=components-radio-btn--design', '/docs/components/Radio/OrigamRadioBtn.html', 'radio', '{"a11y": {"notes": [{"noteKey": "components.radio_btn.a11y.native_input_note", "noteFallback": "The underlying <input type=\"radio\"> provides native radio behaviour: keyboard navigation, grouping via name, and correct role=\"radio\" without any ARIA additions."}, {"noteKey": "components.radio_btn.a11y.label_note", "noteFallback": "The label is associated with the input via <label> — clicking the label text activates the radio."}, {"noteKey": "components.radio_btn.a11y.disabled_note", "noteFallback": "When disabled=true, the native disabled attribute is set on the input. No aria-disabled is needed."}, {"noteKey": "components.radio_btn.a11y.error_note", "noteFallback": "Error state applies visual styling only. Connect an aria-describedby to an error message element for full accessibility."}], "roles": ["radio"], "keyboard": [{"key": "Space", "actionKey": "components.radio_btn.a11y.key_space", "actionFallback": "Selects the radio button when focused."}, {"key": "Tab", "actionKey": "components.radio_btn.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}, {"key": "Arrow Up / Arrow Down", "actionKey": "components.radio_btn.a11y.key_arrows", "actionFallback": "Navigates between radios in a group (native browser behaviour on <input type=\"radio\">)."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #f8f9fa)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"30\" width=\"400\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"76\" cy=\"90\" r=\"20\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\"/>\n  <circle cx=\"76\" cy=\"90\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <rect x=\"112\" y=\"80\" width=\"200\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"212\" y=\"94\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label / #default slot</text>\n  <circle cx=\"36\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"42.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"60\" cy=\"68\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"60\" y=\"72.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"76\" cy=\"68\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"76\" y=\"72.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"212\" cy=\"68\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"212\" y=\"72.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"46\" y1=\"38\" x2=\"80\" y2=\"22\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"21\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-radio-btn → origam-selection-control</text>\n", "code": "<!-- RadioBtn delegates to SelectionControl with type=\"radio\" -->\n<origam-selection-control\n  class=\"origam-radio-btn\"\n  v-model=\"model\"\n  type=\"radio\"\n  :true-icon=\"trueIcon\"\n  :false-icon=\"falseIcon\"\n  v-bind=\"controlProps\"\n  @click:label=\"handleClickLabel\"\n>\n  <template #default><slot name=\"default\" /></template>\n  <template #input=\"{ props, icon, model }\">\n    <slot name=\"input\" v-bind=\"{ props, icon, model }\" />\n  </template>\n  <template #label><slot name=\"label\" /></template>\n</origam-selection-control>", "legend": [{"cls": ".origam-radio-btn", "num": 1, "descriptionKey": "components.radio_btn.anatomy.root", "descriptionFallback": "Root class applied to the OrigamSelectionControl wrapper. Delegates all rendering to the selection-control via filterProps."}, {"cls": ".origam-selection-control__input (ring)", "num": 2, "descriptionKey": "components.radio_btn.anatomy.ring", "descriptionFallback": "Circular ring. Border-color transitions from border.default → action.primary.bg when checked. 20 × 20 px, border-radius: full."}, {"cls": ".origam-selection-control__input (dot)", "num": 3, "descriptionKey": "components.radio_btn.anatomy.dot", "descriptionFallback": "Inner dot (10 × 10 px). Animates from scale(0) → scale(1) on check. Background-color: action.primary.bg."}, {"cls": ".origam-selection-control__label", "num": 4, "descriptionKey": "components.radio_btn.anatomy.label", "descriptionFallback": "Label text area. Color: text.primary. Renders the label prop or #default slot."}], "classes": [{"cls": "origam-radio-btn", "descriptionKey": "components.radio_btn.anatomy.root", "descriptionFallback": "Root class applied on top of OrigamSelectionControl."}], "svgDesc": "Schematic of the RadioBtn component delegating to OrigamSelectionControl.", "svgTitle": "Anatomy of OrigamRadioBtn", "rootClass": "origam-radio-btn", "figcaption": "Anatomy of <code>&lt;origam-radio-btn&gt;</code> — 4 internal parts: the selection-control root ①, the radio ring ②, the selection dot ③, and the label area ④.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-radio---input-size", "defaultValue": "20px", "descriptionKey": "components.radio_btn.css_vars.input_size", "descriptionFallback": "Width and height of the radio ring."}, {"name": "--origam-radio---input-border-color", "defaultValue": "{color.border.default}", "descriptionKey": "components.radio_btn.css_vars.input_border_color", "descriptionFallback": "Ring border color in unchecked state."}, {"name": "--origam-radio---input-border-color-checked", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.radio_btn.css_vars.input_border_color_checked", "descriptionFallback": "Ring border color when checked."}, {"name": "--origam-radio---input-border-color-disabled", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.radio_btn.css_vars.input_border_color_disabled", "descriptionFallback": "Ring border color when disabled."}, {"name": "--origam-radio---input-border-color-error", "defaultValue": "{color.feedback.danger.bg}", "descriptionKey": "components.radio_btn.css_vars.input_border_color_error", "descriptionFallback": "Ring border color in error state."}, {"name": "--origam-radio---dot-size", "defaultValue": "10px", "descriptionKey": "components.radio_btn.css_vars.dot_size", "descriptionFallback": "Diameter of the inner selection dot."}, {"name": "--origam-radio---dot-background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.radio_btn.css_vars.dot_background_color", "descriptionFallback": "Background color of the inner dot when selected."}, {"name": "--origam-radio---label-font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.radio_btn.css_vars.label_font_size", "descriptionFallback": "Font size of the label text."}, {"name": "--origam-radio---opacity-disabled", "defaultValue": "{opacity.32}", "descriptionKey": "components.radio_btn.css_vars.opacity_disabled", "descriptionFallback": "Overall opacity of the control when disabled."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.radio_btn.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to SelectionControl."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.radio_btn.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.radio_btn.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.radio_btn.exposed.load", "descriptionFallback": "Injects the computed style sheet."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.radio_btn.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.radio_btn.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.radio_btn.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}, {"label": "compact", "value": "compact"}], "labelKey": "components.radio_btn.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.radio_btn.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "error", "labelKey": "components.radio_btn.playground.error", "defaultValue": false, "labelFallback": "Error"}, {"kind": "switch", "prop": "inline", "labelKey": "components.radio_btn.playground.inline", "defaultValue": false, "labelFallback": "Inline"}], "defaultSlotContent": "Option label"}, "previewVariants": [{"label": "unchecked", "props": {"falseIcon": "mdi-radiobox-blank"}, "ariaLabel": "Unchecked radio"}, {"label": "checked", "props": {"color": "primary", "trueIcon": "mdi-radiobox-marked"}, "ariaLabel": "Checked radio"}, {"label": "disabled", "props": {"disabled": true}, "ariaLabel": "Disabled radio"}, {"label": "error", "props": {"error": true}, "ariaLabel": "Error radio"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a2c4a0b0-05c9-4662-b7ee-7752aeb5f031', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'radio-group', 'RadioGroup', 'Form & Input', NULL, 'mdi-radiobox-marked', 'components.catalog.radio_group.description', 'Groups multiple Radio inputs under a single v-model with optional label, validation messages and SelectionControlGroup layout.', NULL, NULL, 'origam-radio-group', NULL, 'packages/ds/src/components/Radio/OrigamRadioGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-radio--design', '/docs/components/Radio/OrigamRadioGroup.html', 'radio', '{"a11y": {"notes": [{"noteKey": "components.radio_group.a11y.role_note", "noteFallback": "The SelectionControlGroup is rendered with role=\"group\". When a label is present, aria-labelledby is set to the label id so screen readers announce the group name."}, {"noteKey": "components.radio_group.a11y.describedby_note", "noteFallback": "aria-describedby links the group to the messages/errors area rendered by OrigamInput below the controls."}, {"noteKey": "components.radio_group.a11y.disabled_note", "noteFallback": "The disabled prop is propagated to all Radio inputs via DefaultsProvider. Each native input receives the disabled attribute."}], "roles": ["radiogroup"], "keyboard": [{"key": "Space", "actionKey": "components.radio_group.a11y.key_space", "actionFallback": "Selects the focused Radio inside the group."}, {"key": "Tab", "actionKey": "components.radio_group.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}, {"key": "Arrow keys", "actionKey": "components.radio_group.a11y.key_arrows", "actionFallback": "Navigates between Radio options within the group."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"520\" height=\"180\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"36\" width=\"200\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"140\" y=\"50\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label (group)</text>\n  <rect x=\"40\" y=\"68\" width=\"480\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <circle cx=\"60\" cy=\"86\" r=\"12\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"2\"/>\n  <circle cx=\"60\" cy=\"86\" r=\"5\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"100\" y=\"90\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Radio item 1</text>\n  <rect x=\"40\" y=\"114\" width=\"480\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.03))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <circle cx=\"60\" cy=\"132\" r=\"12\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"2\"/>\n  <text x=\"100\" y=\"136\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Radio item 2</text>\n  <rect x=\"40\" y=\"160\" width=\"480\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.03))\"/>\n  <text x=\"280\" y=\"176\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">messages / error</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"48\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"48\" cy=\"76\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"48\" y=\"80\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"60\" cy=\"86\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.7\"/>\n  <text x=\"60\" y=\"90\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"48\" cy=\"168\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"48\" y=\"172\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<origam-input class=\"origam-radio-group\">\n  <template #default=\"{ id, messagesId, isDisabled, isReadonly }\">\n    <!-- optional group label -->\n    <origam-label :id=\"id\" :text=\"label\" :required=\"required\" />\n\n    <!-- DefaultsProvider pushes color/density/size to children -->\n    <origam-defaults-provider :defaults=\"radioDefaults\">\n      <origam-selection-control-group\n        v-model=\"model\"\n        :id=\"id\"\n        :items=\"items\"\n        :multiple=\"false\"\n        :disabled=\"isDisabled\"\n        :readonly=\"isReadonly\"\n        :aria-labelledby=\"label ? id : undefined\"\n        :aria-describedby=\"messagesId\"\n      >\n        <template #item=\"{ item }\">\n          <!-- #item slot or default OrigamRadio -->\n          <origam-radio v-model=\"model\" v-bind=\"item\" />\n        </template>\n      </origam-selection-control-group>\n    </origam-defaults-provider>\n  </template>\n</origam-input>", "legend": [{"cls": ".origam-radio-group", "num": 1, "descriptionKey": "components.radio_group.anatomy.root", "descriptionFallback": "Root element. Delegates to OrigamInput to manage label, error and messages."}, {"cls": ".origam-label (group label)", "num": 2, "descriptionKey": "components.radio_group.anatomy.label", "descriptionFallback": "Group-level label rendered via OrigamLabel with the label prop. Hidden when label is absent."}, {"cls": ".origam-selection-control-group", "num": 3, "descriptionKey": "components.radio_group.anatomy.scg", "descriptionFallback": "Inner SelectionControlGroup wrapped in DefaultsProvider that propagates color, density and size to all child Radios."}, {"cls": ".origam-radio (per item)", "num": 4, "descriptionKey": "components.radio_group.anatomy.radio_item", "descriptionFallback": "Each individual OrigamRadio rendered from the items array or the #item slot."}, {"cls": ".origam-messages", "num": 5, "descriptionKey": "components.radio_group.anatomy.messages", "descriptionFallback": "Validation messages and hints area. Rendered by OrigamInput below the controls."}], "classes": [{"cls": "origam-radio-group", "descriptionKey": "components.radio_group.anatomy.root", "descriptionFallback": "Root block element wrapping OrigamInput."}], "svgDesc": "Schematic of the RadioGroup component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamRadioGroup", "rootClass": "origam-radio-group", "figcaption": "Anatomy of <code>&lt;origam-radio-group&gt;</code> — 5 internal parts. The OrigamInput root ① wraps the group label ②, the SelectionControlGroup ③ with each Radio item ④ and the messages area ⑤.", "svgViewBox": "0 0 560 220"}, "cssVars": [{"name": "--origam-radio__input---size", "defaultValue": "20px", "descriptionKey": "components.radio_group.css_vars.input_size", "descriptionFallback": "Diameter of each circular radio input visual. Inherited from radio tokens."}, {"name": "--origam-radio__input---border-color", "defaultValue": "{color.border.default}", "descriptionKey": "components.radio_group.css_vars.input_border_color", "descriptionFallback": "Border color of unchecked radio inputs."}, {"name": "--origam-radio__dot---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.radio_group.css_vars.dot_background_color", "descriptionFallback": "Fill color of the selected dot. Overridden by the color prop."}, {"name": "--origam-selection-control-group---gap", "defaultValue": "{space.2}", "descriptionKey": "components.radio_group.css_vars.gap", "descriptionFallback": "Gap between radio items in the group."}, {"name": "--origam-selection-control--density", "defaultValue": "0px", "descriptionKey": "components.radio_group.css_vars.density", "descriptionFallback": "Density modifier: compact → -8px, comfortable → +8px."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.radio_group.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.radio_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "ComputedRef<string>", "descriptionKey": "components.radio_group.exposed.id", "descriptionFallback": "Computed group id (prop or auto-generated radio-group-{uid})."}, {"name": "load", "type": "() => void", "descriptionKey": "components.radio_group.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.radio_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.radio_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}, {"name": "styleId", "type": "string", "descriptionKey": "components.radio_group.exposed.style_id", "descriptionFallback": "Unique style-sheet ID for this instance."}], "playground": {"controls": [{"kind": "text", "prop": "label", "labelKey": "components.radio_group.playground.label", "defaultValue": "Choose an option", "labelFallback": "Label"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.radio_group.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.radio_group.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "inline", "labelKey": "components.radio_group.playground.inline", "defaultValue": false, "labelFallback": "Inline"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.radio_group.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c719ec47-0e64-4fd9-b386-767e2cdbe03a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'rating-field', 'RatingField', 'Form & Input', NULL, 'mdi-star-half-full', 'components.catalog.rating_field.description', 'Star-rating input with configurable length, half-increment support, hover preview and clearable option.', NULL, NULL, 'origam-rating-field', NULL, 'packages/ds/src/components/RatingField/OrigamRatingField.vue', 'origam', NULL, NULL, '/stories/?story=components-rating-field--design', '/docs/components/RatingField/OrigamRatingField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.rating_field.a11y.radio_note", "noteFallback": "Each star item renders a native <input type=\"radio\">. Screen readers announce position and total (e.g. \"3 of 5\")."}, {"noteKey": "components.rating_field.a11y.readonly_note", "noteFallback": "When readonly=true, pointer-events are disabled. The read-only class is applied to the root."}, {"noteKey": "components.rating_field.a11y.item_aria_label_note", "noteFallback": "itemAriaLabel provides a custom aria-label template for each star, replacing the default numeric label."}], "roles": ["radiogroup", "radio"], "keyboard": [{"key": "Tab", "actionKey": "components.rating_field.a11y.key_tab", "actionFallback": "Moves focus to the first or next star item."}, {"key": "Arrow Left / Right", "actionKey": "components.rating_field.a11y.key_arrows", "actionFallback": "Navigates between star positions."}, {"key": "Space", "actionKey": "components.rating_field.a11y.key_space", "actionFallback": "Selects the focused star value."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"520\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"40\" y=\"55\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">Rating label</text>\n  <text x=\"40\" y=\"110\" font-size=\"28\" fill=\"var(--origam-color__feedback--warning---bg, #f59e0b)\" font-family=\"''JetBrains Mono'',monospace\">★★★★☆</text>\n  <rect x=\"440\" y=\"92\" width=\"28\" height=\"28\" rx=\"14\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"454\" y=\"112\" font-size=\"14\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">×</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"56\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"80\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"80\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"180\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"180\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"454\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"454\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-rating-field\">\n  <!-- hidden empty item for keyboard baseline -->\n  <div class=\"origam-rating-field__empty\">\n    <origam-rating-field-item :value=\"0\" :show-star=\"false\" />\n  </div>\n\n  <!-- optional clear button -->\n  <origam-btn class=\"origam-rating-field__clear\" icon=\"mdi-close-circle-outline\" />\n\n  <!-- star rows -->\n  <div v-for=\"range in ranges\" class=\"origam-rating-field__wrapper\">\n    <!-- optional top label -->\n    <span>{{ itemLabels[index] }}</span>\n    <div class=\"origam-rating-field__content\">\n      <origam-rating-field-item :value=\"range - 0.5\" />  <!-- half -->\n      <origam-rating-field-item :value=\"range\" />         <!-- full -->\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-rating-field", "num": 1, "descriptionKey": "components.rating_field.anatomy.root", "descriptionFallback": "Root element. Inline-flex container. Wraps OrigamInput for label/messages."}, {"cls": ".origam-rating-field__label", "num": 2, "descriptionKey": "components.rating_field.anatomy.label", "descriptionFallback": "Label zone rendered via OrigamLabel. Visible when label prop is set."}, {"cls": ".origam-rating-field__wrapper", "num": 3, "descriptionKey": "components.rating_field.anatomy.wrapper", "descriptionFallback": "Per-star-position wrapper. Hosts optional itemLabel above/below the star."}, {"cls": ".origam-rating-field__content", "num": 4, "descriptionKey": "components.rating_field.anatomy.content", "descriptionFallback": "Inner row hosting one or two OrigamRatingFieldItem per position (two when halfIncrements=true)."}, {"cls": ".origam-rating-field__clear", "num": 5, "descriptionKey": "components.rating_field.anatomy.clear", "descriptionFallback": "Clear button (OrigamBtn icon). Visible when clearable=true and modelValue > 0."}], "classes": [{"cls": "origam-rating-field", "descriptionKey": "components.rating_field.anatomy.root", "descriptionFallback": "Root block."}, {"cls": "origam-rating-field__label", "descriptionKey": "components.rating_field.anatomy.label", "descriptionFallback": "Label wrapper."}, {"cls": "origam-rating-field__empty", "descriptionKey": "components.rating_field.anatomy.empty", "descriptionFallback": "Hidden zero-value item for keyboard."}, {"cls": "origam-rating-field__clear", "descriptionKey": "components.rating_field.anatomy.clear", "descriptionFallback": "Clear button."}, {"cls": "origam-rating-field__wrapper", "descriptionKey": "components.rating_field.anatomy.wrapper", "descriptionFallback": "Per-star-position wrapper."}, {"cls": "origam-rating-field__content", "descriptionKey": "components.rating_field.anatomy.content", "descriptionFallback": "Star item row."}, {"cls": "origam-rating-field--hover", "descriptionKey": "components.rating_field.anatomy.modifier_hover", "descriptionFallback": "Applied when hover=true."}, {"cls": "origam-rating-field--readonly", "descriptionKey": "components.rating_field.anatomy.modifier_readonly", "descriptionFallback": "Applied when readonly=true. Disables pointer-events."}], "svgDesc": "Schematic of the RatingField component with 5 numbered parts.", "svgTitle": "Anatomy of OrigamRatingField", "rootClass": "origam-rating-field", "figcaption": "Anatomy of <code>&lt;origam-rating-field&gt;</code> — 5 parts: root ①, label ②, star wrapper ③, individual star item ④, and clear button ⑤.", "svgViewBox": "0 0 560 180"}, "cssVars": [{"name": "--origam-rating-field---gap", "defaultValue": "{space.1}", "descriptionKey": "components.rating_field.css_vars.gap", "descriptionFallback": "Gap between star items."}, {"name": "--origam-rating-field---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.rating_field.css_vars.transition_duration", "descriptionFallback": "Transition duration for star fill animations."}, {"name": "--origam-rating-field__item---color", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.rating_field.css_vars.item_color", "descriptionFallback": "Color of unfilled star items."}, {"name": "--origam-rating-field__item---color-active", "defaultValue": "{color.feedback.warning.bg}", "descriptionKey": "components.rating_field.css_vars.item_color_active", "descriptionFallback": "Color of filled (selected) star items."}, {"name": "--origam-rating-field__item---font-size", "defaultValue": "{font.size.2xl}", "descriptionKey": "components.rating_field.css_vars.item_font_size", "descriptionFallback": "Icon size for each star item."}, {"name": "--origam-rating-field__item---scale-hover", "defaultValue": "1.15", "descriptionKey": "components.rating_field.css_vars.item_scale_hover", "descriptionFallback": "Transform scale applied to a star on hover."}, {"name": "--origam-rating-field---opacity-disabled", "defaultValue": "{opacity.32}", "descriptionKey": "components.rating_field.css_vars.opacity_disabled", "descriptionFallback": "Opacity of the entire field when disabled."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.rating_field.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.rating_field.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.rating_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.rating_field.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.rating_field.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.rating_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "number", "prop": "modelValue", "labelKey": "components.rating_field.playground.model_value", "defaultValue": 3, "labelFallback": "Value"}, {"kind": "number", "prop": "length", "labelKey": "components.rating_field.playground.length", "defaultValue": 5, "labelFallback": "Length (stars)"}, {"kind": "switch", "prop": "hover", "labelKey": "components.rating_field.playground.hover", "defaultValue": true, "labelFallback": "Hover preview"}, {"kind": "switch", "prop": "halfIncrements", "labelKey": "components.rating_field.playground.half_increments", "defaultValue": false, "labelFallback": "Half increments"}, {"kind": "switch", "prop": "clearable", "labelKey": "components.rating_field.playground.clearable", "defaultValue": false, "labelFallback": "Clearable"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.rating_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.rating_field.playground.readonly", "defaultValue": false, "labelFallback": "Readonly"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9c110a8a-67e2-4560-b79c-ebf21349bea2', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'rating-field-item', 'RatingFieldItem', 'Form & Input', NULL, 'mdi-star', 'components.catalog.rating_field_item.description', 'Individual star item in a RatingField. Renders an icon-only Btn in text variant that handles filled/hovered/half-increment state and a visually-hidden radio input.', NULL, NULL, 'origam-rating-field-item', NULL, 'packages/ds/src/components/RatingField/OrigamRatingFieldItem.vue', 'origam', NULL, NULL, '/stories/?story=components-rating-field--design', '/docs/components/RatingField/OrigamRatingFieldItem.html', 'rating-field', '{"a11y": {"notes": [{"noteKey": "components.rating_field_item.a11y.hidden_input_note", "noteFallback": "The hidden radio input is always present but tabindex=\"-1\". It participates in form submission and screen-reader state announcements without entering the normal keyboard focus order."}, {"noteKey": "components.rating_field_item.a11y.label_note", "noteFallback": "The accessible label (aria text) is built from the itemAriaLabel locale key via t(itemAriaLabel, value, length). It reads \"Rate N of M stars\" for screen readers."}, {"noteKey": "components.rating_field_item.a11y.half_note", "noteFallback": "In half-increment mode, items with value % 1 > 0 use clip-path to show half a star. Both the full and half items render a separate label/input pair so the underlying model remains accessible."}], "roles": ["radio"], "keyboard": [{"key": "Tab", "actionKey": "components.rating_field_item.a11y.key_tab", "actionFallback": "Focuses the star button. The hidden radio input is tabindex=\"-1\" and not directly reachable by Tab."}, {"key": "Space / Enter", "actionKey": "components.rating_field_item.a11y.key_activate", "actionFallback": "Activates the star button, emitting click and setting the parent RatingField value."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"460\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"420\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"40\" width=\"60\" height=\"32\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"70\" y=\"61\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">label</text>\n  <rect x=\"110\" y=\"40\" width=\"200\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"210\" y=\"88\" font-size=\"22\" fill=\"var(--origam-color__feedback--warning---bg, #f59e0b)\" text-anchor=\"middle\">★</text>\n  <rect x=\"120\" y=\"132\" width=\"180\" height=\"12\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\"/>\n  <text x=\"210\" y=\"143\" font-size=\"8\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">hidden radio input</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"118\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"118\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"210\" cy=\"136\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"210\" y=\"140\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div class=\"origam-rating-field-item\">\n  <!-- visually-hidden label for screen readers -->\n  <label :for=\"id\">\n    <span class=\"origam-rating-field-item__hidden\">Rate {{ value }} of {{ length }}</span>\n\n    <!-- the clickable star icon (OrigamBtn in text/icon mode) -->\n    <origam-btn\n      v-if=\"showStar\"\n      variant=\"text\"\n      :icon=\"isFullIcon ? fullIcon : emptyIcon\"\n      @click=\"handleClick\"\n      @mouseenter=\"handleMouseEnter\"\n      @mouseleave=\"handleMouseLeave\"\n    />\n  </label>\n\n  <!-- visually-hidden radio input, not focusable -->\n  <input\n    class=\"origam-rating-field-item__hidden\"\n    type=\"radio\"\n    :id=\"id\"\n    :name=\"name\"\n    :value=\"value\"\n    :checked=\"checked\"\n    :disabled=\"disabled\"\n    :readonly=\"readonly\"\n    tabindex=\"-1\"\n  />\n</div>", "legend": [{"cls": ".origam-rating-field-item", "num": 1, "descriptionKey": "components.rating_field_item.anatomy.root", "descriptionFallback": "Root element (div by default). Applies --half / --full modifier classes when halfIncrements is active."}, {"cls": ".origam-rating-field-item__hidden (label)", "num": 2, "descriptionKey": "components.rating_field_item.anatomy.hidden_label", "descriptionFallback": "Visually-hidden <span> inside a <label> element. Provides the accessible text (\"Rate 3 of 5\") for screen readers. width/height: 0, opacity: 0."}, {"cls": ".origam-btn (variant=\"text\" icon)", "num": 3, "descriptionKey": "components.rating_field_item.anatomy.btn", "descriptionFallback": "Inner OrigamBtn rendered in variant=\"text\" icon mode. Displays fullIcon or emptyIcon depending on filled/hovered state. The #item slot overrides this."}, {"cls": ".origam-rating-field-item__hidden (input)", "num": 4, "descriptionKey": "components.rating_field_item.anatomy.hidden_input", "descriptionFallback": "Visually-hidden native <input type=\"radio\"> (tabindex=\"-1\"). Tracks checked state for form participation and screen reader state. Not focusable — keyboard navigation uses the Btn."}], "classes": [{"cls": "origam-rating-field-item", "descriptionKey": "components.rating_field_item.anatomy.root", "descriptionFallback": "Root block element."}, {"cls": "origam-rating-field-item--half", "descriptionKey": "components.rating_field_item.anatomy.half", "descriptionFallback": "Applied when halfIncrements=true and value is fractional. Clips the star to show only the left half via clip-path."}, {"cls": "origam-rating-field-item--full", "descriptionKey": "components.rating_field_item.anatomy.full", "descriptionFallback": "Applied when halfIncrements=true and value is a whole number."}, {"cls": "origam-rating-field-item__hidden", "descriptionKey": "components.rating_field_item.anatomy.hidden", "descriptionFallback": "Visually-hidden utility class (height/width: 0, opacity: 0, position: absolute). Applied to both the label span and the radio input."}], "svgDesc": "Schematic of the RatingFieldItem component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamRatingFieldItem", "rootClass": "origam-rating-field-item", "figcaption": "Anatomy of <code>&lt;origam-rating-field-item&gt;</code> — 4 parts. Root ① wraps the visually-hidden accessible label ② and the star Btn ③ (with fullIcon/emptyIcon). A hidden radio input ④ tracks the selection state for screen readers and form submission.", "svgViewBox": "0 0 460 180"}, "cssVars": [{"name": "--origam-rating-field---item-color", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.rating_field_item.css_vars.item_color", "descriptionFallback": "Default (empty) star color."}, {"name": "--origam-rating-field---item-color-active", "defaultValue": "{color.feedback.warning.bg}", "descriptionKey": "components.rating_field_item.css_vars.item_color_active", "descriptionFallback": "Star color when filled or hovered."}, {"name": "--origam-rating-field---item-color-disabled", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.rating_field_item.css_vars.item_color_disabled", "descriptionFallback": "Star color when disabled."}, {"name": "--origam-rating-field---item-font-size", "defaultValue": "{font.size.2xl}", "descriptionKey": "components.rating_field_item.css_vars.item_font_size", "descriptionFallback": "Icon size of each star."}, {"name": "--origam-rating-field---item-scale-hover", "defaultValue": "1.15", "descriptionKey": "components.rating_field_item.css_vars.item_scale_hover", "descriptionFallback": "Scale applied to the star on hover."}, {"name": "--origam-rating-field---item-transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.rating_field_item.css_vars.item_transition_duration", "descriptionFallback": "Transition duration for scale and color animations."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.rating_field_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.rating_field_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "ComputedRef<string>", "descriptionKey": "components.rating_field_item.exposed.id", "descriptionFallback": "Computed id of the hidden radio input (\"{name}-{value}\")."}, {"name": "load", "type": "() => void", "descriptionKey": "components.rating_field_item.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.rating_field_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.rating_field_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}, {"name": "styleId", "type": "string", "descriptionKey": "components.rating_field_item.exposed.style_id", "descriptionFallback": "Unique style-sheet ID for this instance."}], "playground": {"controls": [{"kind": "number", "prop": "value", "labelKey": "components.rating_field_item.playground.value", "defaultValue": 1, "labelFallback": "Value"}, {"kind": "switch", "prop": "isFilled", "labelKey": "components.rating_field_item.playground.is_filled", "defaultValue": false, "labelFallback": "Filled"}, {"kind": "select", "prop": "fullIcon", "options": [{"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-heart", "value": "mdi-heart"}, {"label": "mdi-thumb-up", "value": "mdi-thumb-up"}], "labelKey": "components.rating_field_item.playground.full_icon", "defaultValue": "mdi-star", "labelFallback": "Full icon"}, {"kind": "select", "prop": "emptyIcon", "options": [{"label": "mdi-star-outline", "value": "mdi-star-outline"}, {"label": "mdi-heart-outline", "value": "mdi-heart-outline"}, {"label": "mdi-thumb-up-outline", "value": "mdi-thumb-up-outline"}], "labelKey": "components.rating_field_item.playground.empty_icon", "defaultValue": "mdi-star-outline", "labelFallback": "Empty icon"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.rating_field_item.playground.disabled", "defaultValue": fa