INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3528d21f-392d-4ffa-a8fe-66d949d42020', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'responsive', 'Responsive', 'Layout & Structure', NULL, 'mdi-aspect-ratio', 'components.catalog.responsive.description', 'Aspect-ratio container that constrains its content to a fixed ratio using a sizer trick. Supports dimension overrides and standard spacing props.', NULL, NULL, 'origam-responsive', NULL, 'packages/ds/src/components/Responsive/OrigamResponsive.vue', 'origam', NULL, NULL, '/stories/?story=components-responsive--design', '/docs/components/Responsive/OrigamResponsive.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.responsive.a11y.container_note", "noteFallback": "OrigamResponsive is a pure layout container with no interactive role. Accessibility is owned by the content placed in the default slot."}, {"noteKey": "components.responsive.a11y.media_note", "noteFallback": "When wrapping an iframe or img, ensure the embedded element has appropriate title or alt attributes for screen readers."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "other", "value": "1.7778", "tokenPath": "--origam-responsive---aspect-ratio-default", "descriptionKey": "components.responsive.tokens.aspect_ratio_default", "descriptionFallback": "Default aspect ratio applied when no prop is set."}, {"type": "other", "value": "100%", "tokenPath": "--origam-responsive---max-width", "descriptionKey": "components.responsive.tokens.max_width", "descriptionFallback": "Default max-width of the container."}, {"type": "other", "value": "hidden", "tokenPath": "--origam-responsive---overflow", "descriptionKey": "components.responsive.tokens.overflow", "descriptionFallback": "Overflow mode — hidden clips content to the ratio box."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"480\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"440\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"40\" width=\"400\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.1))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"240\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__sizer (padding-block-end drives ratio)</text>\n  <rect x=\"40\" y=\"68\" width=\"400\" height=\"72\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"240\" y=\"110\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot content</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"50\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-responsive\">\n  <!-- sizer: padding-block-end = (height / width) * 100% -->\n  <div class=\"origam-responsive__sizer\" />\n\n  <!-- additional slot (overlays, decorations) -->\n  <slot name=\"additional\" />\n\n  <!-- main content, absolutely fills the container -->\n  <div class=\"origam-responsive__content\">\n    <slot name=\"default\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-responsive", "num": 1, "descriptionKey": "components.responsive.anatomy.root", "descriptionFallback": "Root element. Flex container, overflow hidden. Receives dimension, padding, margin, border and rounded classes."}, {"cls": ".origam-responsive__sizer", "num": 2, "descriptionKey": "components.responsive.anatomy.sizer", "descriptionFallback": "Zero-height helper div. Its padding-block-end (set via useAspectRatio) forces the container to the correct ratio height."}, {"cls": ".origam-responsive__content", "num": 3, "descriptionKey": "components.responsive.anatomy.content", "descriptionFallback": "Absolutely positioned content area filling the ratio-locked space. Receives contentClass."}], "classes": [{"cls": "origam-responsive", "descriptionKey": "components.responsive.anatomy.root", "descriptionFallback": "Root block element."}, {"cls": "origam-responsive__sizer", "descriptionKey": "components.responsive.anatomy.sizer", "descriptionFallback": "Aspect-ratio sizer helper div."}, {"cls": "origam-responsive__content", "descriptionKey": "components.responsive.anatomy.content", "descriptionFallback": "Content area, absolutely positioned."}], "svgDesc": "Schematic of the Responsive component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamResponsive", "rootClass": "origam-responsive", "figcaption": "Anatomy of <code>&lt;origam-responsive&gt;</code> — 3 parts: root container ①, sizer div ② (drives padding-block-end aspect trick), and content div ③.", "svgViewBox": "0 0 480 180"}, "cssVars": [{"name": "--origam-responsive---aspect-ratio-default", "defaultValue": "16 / 9", "descriptionKey": "components.responsive.css_vars.aspect_ratio_default", "descriptionFallback": "Default aspect ratio when no aspectRatio prop is set."}, {"name": "--origam-responsive---overflow", "defaultValue": "hidden", "descriptionKey": "components.responsive.css_vars.overflow", "descriptionFallback": "Overflow applied to the root container. Hidden by default to clip content."}, {"name": "--origam-responsive---max-width", "defaultValue": "100%", "descriptionKey": "components.responsive.css_vars.max_width", "descriptionFallback": "Default max-width of the responsive container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.responsive.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.responsive.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.responsive.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.responsive.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.responsive.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.responsive.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "aspectRatio", "options": [{"label": "16/9", "value": "16/9"}, {"label": "4/3", "value": "4/3"}, {"label": "1/1", "value": "1"}, {"label": "3/4 (portrait)", "value": "3/4"}, {"label": "21/9 (ultrawide)", "value": "21/9"}], "labelKey": "components.responsive.playground.aspect_ratio", "defaultValue": "16/9", "labelFallback": "Aspect ratio"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.responsive.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "maxWidth", "options": [{"label": "(none)", "value": ""}, {"label": "320px", "value": "320px"}, {"label": "480px", "value": "480px"}, {"label": "640px", "value": "640px"}], "labelKey": "components.responsive.playground.max_width", "defaultValue": "", "labelFallback": "Max width"}]}, "previewVariants": [{"label": "16/9", "props": {"width": 280, "aspectRatio": "16/9"}, "slotContent": "16 : 9"}, {"label": "4/3", "props": {"width": 200, "aspectRatio": "4/3"}, "slotContent": "4 : 3"}, {"label": "1/1", "props": {"width": 160, "aspectRatio": "1"}, "slotContent": "1 : 1"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
