INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7e870fd8-916d-47b4-8cce-b91c4a51553e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'selection-control-group', 'SelectionControlGroup', 'Form & Input', NULL, 'mdi-format-list-checks', 'components.catalog.selection_control_group.description', 'Groups multiple SelectionControl instances under a shared v-model with inline layout support and a typed item-slot API.', NULL, NULL, 'origam-selection-control-group', NULL, 'packages/ds/src/components/SelectionControl/OrigamSelectionControlGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-selection-control--design', '/docs/components/SelectionControl/OrigamSelectionControl.html', 'selection-control', '{"a11y": {"notes": [{"noteKey": "components.selection_control_group.a11y.role_group", "noteFallback": "The root element carries role=\"group\" and is identified by the computed name/id attribute. Screen readers announce the group boundary."}, {"noteKey": "components.selection_control_group.a11y.defaults_provider", "noteFallback": "OrigamDefaultsProvider forwards type, name, density, color, disabled, readonly and error to every descendant SelectionControl. Child overrides still win."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.selection_control_group.a11y.key_tab", "actionFallback": "Moves focus through each child SelectionControl."}, {"key": "Space", "actionKey": "components.selection_control_group.a11y.key_space", "actionFallback": "Toggles the focused child control."}]}, "tokens": {"excerpt": [{"type": "other", "value": "flex", "tokenPath": "--origam-selection-control-group---display", "descriptionKey": "components.selection_control_group.tokens.display", "descriptionFallback": "Display mode for the group container."}, {"type": "other", "value": "column", "tokenPath": "--origam-selection-control-group---flex-direction", "descriptionKey": "components.selection_control_group.tokens.flex_direction", "descriptionFallback": "Default stack direction (column). Row when inline."}, {"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-selection-control-group---gap", "descriptionKey": "components.selection_control_group.tokens.gap", "descriptionFallback": "Gap between child controls."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"520\" height=\"160\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"50\" width=\"440\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"260\" y=\"73\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-selection-control (item 1)</text>\n  <rect x=\"40\" y=\"96\" width=\"440\" height=\"36\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"260\" y=\"119\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-selection-control (item 2)</text>\n  <rect x=\"40\" y=\"142\" width=\"440\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #eee)\" opacity=\"0.4\"/>\n  <text x=\"260\" y=\"158\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">slot: item / item.{index}</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"60\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"50\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"50\" y=\"152\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div role=\"group\" :id=\"name\" class=\"origam-selection-control-group\">\n  <!-- OrigamDefaultsProvider pushes density/color/type/disabled/… to children -->\n  <origam-defaults-provider :defaults=\"slotDefaults\">\n    <slot name=\"default\" v-bind=\"{ items }\">\n      <!-- fallback: iterate items via item slot -->\n      <template v-for=\"(item, index) in items\" :key=\"index\">\n        <slot :name=\"`item.${index}`\" v-bind=\"{ item }\">\n          <slot name=\"item\" v-bind=\"{ item, index }\" />\n        </slot>\n      </template>\n    </slot>\n  </origam-defaults-provider>\n</div>", "legend": [{"cls": ".origam-selection-control-group", "num": 1, "descriptionKey": "components.selection_control_group.anatomy.root", "descriptionFallback": "Root div with role=\"group\". Receives the group id as the ARIA id attribute. Applies --inline modifier when inline=true."}, {"cls": ".origam-selection-control-group--inline", "num": 2, "descriptionKey": "components.selection_control_group.anatomy.inline", "descriptionFallback": "Modifier applied when inline=true. Switches flex-direction from column to row."}, {"cls": "[slot: item / item.{index}]", "num": 3, "descriptionKey": "components.selection_control_group.anatomy.slot_item", "descriptionFallback": "Items slot rendered per entry in the items array. Wrapped in OrigamDefaultsProvider so group-level props (color, type, density, disabled…) are inherited by children."}], "classes": [{"cls": "origam-selection-control-group", "descriptionKey": "components.selection_control_group.anatomy.root", "descriptionFallback": "Root block. Display: flex, flex-direction: column by default."}, {"cls": "origam-selection-control-group--inline", "descriptionKey": "components.selection_control_group.anatomy.inline", "descriptionFallback": "Applied when inline=true. Changes flex-direction to row."}], "svgDesc": "Schematic of SelectionControlGroup with 3 numbered parts.", "svgTitle": "Anatomy of OrigamSelectionControlGroup", "rootClass": "origam-selection-control-group", "figcaption": "Anatomy of <code>&lt;origam-selection-control-group&gt;</code> — root group ① wraps SelectionControl children ② via OrigamDefaultsProvider. The item slot ③ controls how each item is rendered.", "svgViewBox": "0 0 560 200"}, "cssVars": [{"name": "--origam-selection-control-group---display", "defaultValue": "flex", "descriptionKey": "components.selection_control_group.css_vars.display", "descriptionFallback": "Display mode for the group container (always flex)."}, {"name": "--origam-selection-control-group---flex-direction", "defaultValue": "column", "descriptionKey": "components.selection_control_group.css_vars.flex_direction", "descriptionFallback": "Stack direction. Switches to row when --inline modifier is applied."}, {"name": "--origam-selection-control-group---flex-direction-inline", "defaultValue": "row", "descriptionKey": "components.selection_control_group.css_vars.flex_direction_inline", "descriptionFallback": "Flex direction when inline=true."}, {"name": "--origam-selection-control-group---flex-wrap", "defaultValue": "wrap", "descriptionKey": "components.selection_control_group.css_vars.flex_wrap", "descriptionFallback": "Wrap mode for inline groups."}, {"name": "--origam-selection-control-group---gap", "defaultValue": "{space.2}", "descriptionKey": "components.selection_control_group.css_vars.gap", "descriptionFallback": "Gap between child SelectionControl items."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.selection_control_group.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.selection_control_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "ComputedRef<string>", "descriptionKey": "components.selection_control_group.exposed.id", "descriptionFallback": "Computed group id (props.id or auto-generated origam-selection-control-group-{uid})."}, {"name": "styleId", "type": "string", "descriptionKey": "components.selection_control_group.exposed.style_id", "descriptionFallback": "Unique style-sheet ID for this instance (distinct from the logical group id)."}, {"name": "load", "type": "() => void", "descriptionKey": "components.selection_control_group.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.selection_control_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.selection_control_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "type", "options": [{"label": "checkbox", "value": "checkbox"}, {"label": "radio", "value": "radio"}], "labelKey": "components.selection_control_group.playground.type", "defaultValue": "checkbox", "labelFallback": "Type"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.selection_control_group.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "inline", "labelKey": "components.selection_control_group.playground.inline", "defaultValue": false, "labelFallback": "Inline"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.selection_control_group.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "error", "labelKey": "components.selection_control_group.playground.error", "defaultValue": false, "labelFallback": "Error"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('347ffc2c-cbbf-46b8-a159-9b667b55cdd9', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'sheet', 'Sheet', 'Overlay & Surface', NULL, 'mdi-card-outline', 'components.catalog.sheet.description', 'General-purpose surface container with optional swipe-to-expand bottom-sheet gesture. Used as the base layer for Dialog, Picker, ColorPickerField and other overlay components.', NULL, NULL, 'origam-sheet', NULL, 'packages/ds/src/components/Sheet/OrigamSheet.vue', 'origam', NULL, NULL, '/stories/?story=components-sheet--design', '/docs/components/Sheet/OrigamSheet.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.sheet.a11y.handle_note", "noteFallback": "The drag handle has role=\"button\", tabindex=\"0\" and aria-label=\"Drag handle\" so keyboard users can navigate snap points without touch."}, {"noteKey": "components.sheet.a11y.reduced_motion_note", "noteFallback": "Under prefers-reduced-motion, the height transition is disabled. Height still changes imperatively but without animation."}, {"noteKey": "components.sheet.a11y.overlay_note", "noteFallback": "OrigamSheet is a surface-only primitive. Overlay focus-trap and aria-modal semantics are managed by the Dialog or Drawer wrapper using this component."}], "roles": [], "keyboard": [{"key": "Tab (handle)", "actionKey": "components.sheet.a11y.key_tab", "actionFallback": "Focuses the drag handle button when swipeable=true."}, {"key": "Enter / Space (handle)", "actionKey": "components.sheet.a11y.key_enter", "actionFallback": "Cycles through snap points when the handle is focused."}]}, "tokens": {"exce