es the focused dismiss or action button."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-snackbar-group---gap", "descriptionKey": "components.snackbar_group.tokens.gap", "descriptionFallback": "Gap between stacked toast items."}, {"type": "dimension", "value": "420px", "tokenPath": "--origam-snackbar-group---max-width", "descriptionKey": "components.snackbar_group.tokens.max_width", "descriptionFallback": "Maximum width of the stack container."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-snackbar-group---transition-duration", "descriptionKey": "components.snackbar_group.tokens.transition_duration", "descriptionFallback": "Duration of the enter/leave slide transitions."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-snackbar-group---position-top", "descriptionKey": "components.snackbar_group.tokens.position_top", "descriptionFallback": "Distance from the top edge for top-* locations."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-snackbar-group---position-right", "descriptionKey": "components.snackbar_group.tokens.position_right", "descriptionFallback": "Distance from the right edge for *-right locations."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f8f5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"20\" width=\"652\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"36\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-snackbar-group (Teleport → body)</text>\n  <rect x=\"36\" y=\"54\" width=\"628\" 