scriptionFallback": "Leading icon wrapper. Only rendered when icon prop is provided."}, {"cls": "origam-tab__label", "descriptionKey": "components.tab.anatomy.label", "descriptionFallback": "Label zone containing the default slot content or text prop."}, {"cls": "origam-tab__append", "descriptionKey": "components.tab.anatomy.append", "descriptionFallback": "Trailing icon wrapper. Only rendered when appendIcon prop is provided."}, {"cls": "origam-tab__indicator", "descriptionKey": "components.tab.anatomy.indicator", "descriptionFallback": "Bottom indicator bar. Visible only in underline variant; scales on activation."}], "svgDesc": "Schematic of the Tab component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamTab", "rootClass": "origam-tab", "figcaption": "Anatomy of <code>&lt;origam-tab&gt;</code> — 5 internal parts. The indicator (⑤) is absolute-positioned at the block-end and scales on activation.", "svgViewBox": "0 0 600 200"}, "cssVars": [{"name": "--origam-tabs__item---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.tab.css_vars.color", "descriptionFallback": "Tab label color in resting state."}, {"name": "--origam-tabs__item---background-color", "defaultValue": "transparent", "descriptionKey": "components.tab.css_vars.background_color", "descriptionFallback": "Tab background in resting state."}, {"name": "--origam-tabs__item---height", "defaultValue": "48px", "descriptionKey": "components.tab.css_vars.height", "descriptionFallback": "Minimum tab height."}, {"name": "--origam-tabs__item---padding-inline", "defaultValue": "16px", "descriptionKey": "components.tab.css_vars.padding_inline", "descriptionFallback": "Horizontal padding of each tab."}, {"name": "--origam-tabs__item---padding-block", "defaultValue": "0", "descriptionKey": "components.tab.css_vars.padding_block", "descriptionFallback": "Vertical padding of each tab."}, {"name": "--origam-tabs__item---gap", "defaultValue": "8px", "descriptionKey": "components.tab.css_vars.gap", "descriptionFallback": "Gap between icon and label."}, {"name": "--origam-tabs__item---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.tab.css_vars.font_size", "descriptionFallback": "Tab label font size."}, {"name": "--origam-tabs__item---font-weight", "defaultValue": "500", "descriptionKey": "components.tab.css_vars.font_weight", "descriptionFallback": "Tab label font weight."}, {"name": "--origam-tabs__item---letter-spacing", "defaultValue": "0.03125em", "descriptionKey": "components.tab.css_vars.letter_spacing", "descriptionFallback": "Tab label letter spacing."}, {"name": "--origam-tabs__item---border-radius", "defaultValue": "0", "descriptionKey": "components.tab.css_vars.border_radius", "descriptionFallback": "Tab border radius. Set to radius.full for pills variant."}, {"name": "--origam-tabs__item---transition-duration", "defaultValue": "0.2s", "descriptionKey": "components.tab.css_vars.transition_duration", "descriptionFallback": "Transition duration for color, background-color, border-color and transform."}, {"name": "--origam-tabs__item--active---color", "defaultValue": "currentColor", "descriptionKey": "components.tab.css_vars.active_color", "descriptionFallback": "Tab label color when active."}, {"name": "--origam-tabs__item--active---font-weight", "defaultValue": "600", "descriptionKey": "components.tab.css_vars.active_font_weight", "descriptionFallback": "Font weight applied to the active tab."}, {"name": "--origam-tabs__indicator---color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.tab.css_vars.indicator_color", "descriptionFallback": "Color of the underline indicator bar (variant=\"underline\")."}, {"name": "--origam-tabs__indicator---height", "defaultValue": "2px", "descriptionKey": "components.tab.css_vars.indicator_height", "descriptionFallback": "Thickness of the underline indicator bar."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tab.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "toggle", "type": "() => void", "descriptionKey": "components.tab.exposed.toggle", "descriptionFallback": "Toggles the selected state of this tab in the group."}, {"name": "select", "type": "(value: boolean) => void", "descriptionKey": "components.tab.exposed.select", "descriptionFallback": "Programmatically selects (true) or deselects (false) this tab."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed tab styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tab.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.tab.playground.text", "defaultValue": "Tab label", "labelFallback": "Label text"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-magnify", "value": "mdi-magnify"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-star", "value": "mdi-star"}], "labelKey": "components.tab.playground.icon", "defaultValue": "", "labelFallback": "Leading icon"}, {"kind": "select", "prop": "appendIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-close", "value": "mdi-close"}, {"label": "mdi-chevron-right", "value": "mdi-chevron-right"}, {"label": "mdi-bell", "value": "mdi-bell"}], "labelKey": "components.tab.playground.append_icon", "defaultValue": "", "labelFallback": "Trailing icon"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.tab.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": ""}, "previewVariants": [{"label": "default", "props": {"text": "Tab", "value": "a"}}, {"label": "with icon", "props": {"icon": "mdi-magnify", "text": "Search", "value": "b"}}, {"label": "disabled", "props": {"text": "Disabled", "value": "c", "disabled": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
