---4)", "tokenPath": "--origam-timeline---gap", "descriptionKey": "components.timeline.tokens.gap", "descriptionFallback": "Gap between items."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-timeline---dot-size", "descriptionKey": "components.timeline.tokens.dot_size", "descriptionFallback": "Dot diameter."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-timeline---dot-bg", "descriptionKey": "components.timeline.tokens.dot_bg", "descriptionFallback": "Default dot background color."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-timeline---connector-color", "descriptionKey": "components.timeline.tokens.connector_color", "descriptionFallback": "Connector line color."}, {"type": "dimension", "value": "var(--origam-border__width---thin)", "tokenPath": "--origam-timeline---connector-thickness", "descriptionKey": "components.timeline.tokens.connector_thickness", "descriptionFallback": "Connector line width."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-timeline---title-font-weight", "descriptionKey": "components.timeline.tokens.title_font_weight", "descriptionFallback": "Title font weight."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"20\" width=\"544\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"70\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <line x1=\"120\" y1=\"80\" x2=\"120\" y2=\"150\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"160\" r=\"10\" fill=\"var(--origam-color__feedback--success---bg, #10b981)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <line x1=\"120\" y1=\"170\" x2=\"120\" y2=\"240\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"250\" r=\"10\" fill=\"var(--origam-color__feedback--info---bg, #06b6d4)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <rect x=\"148\" y=\"50\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"76\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">Account created</text>\n  <rect x=\"148\" y=\"140\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"166\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">Profile completed</text>\n  <rect x=\"148\" y=\"230\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"256\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">First payment</text>\n  <circle cx=\"36\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"110\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"110\" y=\"62.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"132\" cy=\"82\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"132\" y=\"86.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"148\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"62.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"46\" y1=\"20\" x2=\"80\" y2=\"6\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-timeline</text>\n", "code": "<!-- root: role=\"list\" -->\n<component :is=\"tag\" class=\"origam-timeline\" role=\"list\" :aria-label=\"ariaLabel\">\n  <!-- horizontal mode wraps items in a scroll-snap track -->\n  <div v-if=\"orientation === ''horizontal''\" class=\"origam-timeline__track-wrapper\">\n    <slot>\n      <origam-timeline-item v-for=\"(entry, i) in items\" :key=\"i\" v-bind=\"entry\" />\n    </slot>\n  </div>\n\n  <!-- vertical mode: direct slot -->\n  <slot v-else>\n    <origam-timeline-item v-for=\"(entry, i) in items\" :key=\"i\" v-bind=\"entry\" />\n  </slot>\n</component>", "legend": [{"cls": ".origam-timeline", "num": 1, "descriptionKey": "components.timeline.anatomy.root", "descriptionFallback": "Root element with role=\"list\". Contains a track-wrapper div in horizontal mode."}, {"cls": ".origam-timeline-item__dot", "num": 2, "descriptionKey": "components.timeline.anatomy.dot", "descriptionFallback": "Circular dot. Background color driven by the item intent via --origam-timeline-item---dot-bg. Hosts the #dot slot (icon by default when icon prop is set)."}, {"cls": ".origam-timeline-item__connector", "num": 3, "descriptionKey": "components.timeline.anatomy.connector", "descriptionFallback": "Vertical (or horizontal) line connecting consecutive dots. Hidden on the last item when truncateLine=true."}, {"cls": ".origam-timeline-item__content", "num": 4, "descriptionKey": "components.timeline.anatomy.content", "descriptionFallback": "Content area next to the dot. Contains the header (title + subtitle) and an optional body. Hosts the #default and #body slots."}], "classes": [{"cls": "origam-timeline", "descriptionKey": "components.timeline.anatomy.root", "descriptionFallback": "Root element (role=\"list\")."}, {"cls": "origam-timeline__track-wrapper", "descriptionKey": "components.timeline.anatomy.track_wrapper", "descriptionFallback": "Horizontal scroll container. Only rendered when orientation=\"horizontal\"."}, {"cls": "origam-timeline-item", "descriptionKey": "components.timeline.anatomy.item", "descriptionFallback": "Individual timeline entry (role=\"listitem\")."}, {"cls": "origam-timeline-item__track", "descriptionKey": "components.timeline.anatomy.track", "descriptionFallback": "Track column: dot + connector (aria-hidden)."}, {"cls": "origam-timeline-item__dot", "descriptionKey": "components.timeline.anatomy.dot", "descriptionFallback": "Circular dot. Intent-colored background."}, {"cls": "origam-timeline-item__connector", "descriptionKey": "components.timeline.anatomy.connector", "descriptionFallback": "Line connecting this dot to the next."}, {"cls": "origam-timeline-item__content", "descriptionKey": "components.timeline.anatomy.content", "descriptionFallback": "Content area: header + body."}], "svgDesc": "Schematic of the Timeline component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamTimeline", "rootClass": "origam-timeline", "figcaption": "Anatomy of <code>&lt;origam-timeline&gt;</code> — 4 internal parts: root list ①, dot ②, connector ③ and content area ④ per item.", "svgViewBox": "0 0 600 300"}, "cssVars": [{"name": "--origam-timeline---gap", "defaultValue": "{space.4}", "descriptionKey": "components.timeline.css_vars.gap", "descriptionFallback": "Gap between timeline items and between the dot and content."}, {"name": "--origam-timeline---dot-size", "defaultValue": "{space.3}", "descriptionKey": "components.timeline.css_vars.dot_size", "descriptionFallback": "Diameter of the dot."}, {"name": "--origam-timeline---dot-bg", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.timeline.css_vars.dot_bg", "descriptionFallback": "Default dot background color (overridden per item by intent)."}, {"name": "--origam-timeline---dot-color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.timeline.css_vars.dot_color", "descriptionFallback": "Default dot foreground (icon) color."}, {"name": "--origam-timeline---connector-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.timeline.css_vars.connector_color", "descriptionFallback": "Color of the connector line between dots."}, {"name": "--origam-timeline---connector-thickness", "defaultValue": "{border.width.thin}", "descriptionKey": "components.timeline.css_vars.connector_thickness", "descriptionFallback": "Width/height of the connector line."}, {"name": "--origam-timeline---track-width", "defaultValue": "{space.6}", "descriptionKey": "components.timeline.css_vars.track_width", "descriptionFallback": "Width of the track column (dot + connector area)."}, {"name": "--origam-timeline---title-font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.timeline.css_vars.title_font_size", "descriptionFallback": "Font size of the item title."}, {"name": "--origam-timeline---subtitle-color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.timeline.css_vars.subtitle_color", "descriptionFallback": "Color of the item subtitle and body text."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.timeline.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.timeline.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.timeline.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.timeline.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.timeline.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.timeline.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "orientation", "options": [{"label": "vertical", "value": "vertical"}, {"label": "horizontal", "value": "horizontal"}], "labelKey": "components.timeline.playground.orientation", "defaultValue": "vertical", "labelFallback": "Orientation"}, {"kind": "select", "prop": "side", "options": [{"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "alternating", "value": "alternating"}], "labelKey": "components.timeline.playground.side", "defaultValue": "start", "labelFallback": "Side"}, {"kind": "switch", "prop": "truncateLine", "labelKey": "components.timeline.playground.truncate_line", "defaultValue": true, "labelFallback": "Truncate last connector"}, {"kind": "select", "prop": "color", "optio