INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7a2a70f9-eb11-40f5-bfa6-29b3559a1a9a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'toolbar', 'Toolbar', 'Layout & Structure', NULL, 'mdi-toolbar', 'components.catalog.toolbar.description', 'Horizontal bar hosting a title, prepend/append action zones and content. Supports collapse, flat and floating modes with density and elevation control.', NULL, NULL, 'origam-toolbar', NULL, 'packages/ds/src/components/Toolbar/OrigamToolbar.vue', 'origam', NULL, NULL, '/stories/?story=components-toolbar--design', '/docs/components/Toolbar/OrigamToolbar.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.toolbar.a11y.landmark", "noteFallback": "When rendered as <header> (default tag), the toolbar acts as a ARIA banner landmark. Ensure only one banner per page."}, {"noteKey": "components.toolbar.a11y.icon_btns", "noteFallback": "Icon-only buttons inside the toolbar must carry an aria-label."}], "roles": ["banner"], "keyboard": [{"key": "Tab", "actionKey": "components.toolbar.a11y.key_tab", "actionFallback": "Moves focus through interactive children (buttons, links) in the toolbar."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-toolbar---background", "descriptionKey": "components.toolbar.tokens.background", "descriptionFallback": "Default toolbar background."}, {"type": "dimension", "value": "var(--origam-toolbar---height-default, var(--origam-space---14))", "tokenPath": "--origam-toolbar---height", "descriptionKey": "components.toolbar.tokens.height", "descriptionFallback": "Default height (56px)."}, {"type": "dimension", "value": "var(--origam-space---10)", "tokenPath": "--origam-toolbar---height-compact", "descriptionKey": "components.toolbar.tokens.height_compact", "descriptionFallback": "Compact density height."}, {"type": "shadow", "value": "var(--origam-shadow---sm)", "tokenPath": "--origam-toolbar---box-shadow", "descriptionKey": "components.toolbar.tokens.box_shadow", "descriptionFallback": "Default shadow."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-toolbar---transition-duration", "descriptionKey": "components.toolbar.tokens.transition_duration", "descriptionFallback": "Height/shadow transition duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"40\" width=\"660\" height=\"56\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"96\" width=\"660\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.08))\"/>\n  <rect x=\"28\" y=\"48\" width=\"52\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"54\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prepend</text>\n  <rect x=\"88\" y=\"56\" width=\"120\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"148\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">title</text>\n  <rect x=\"216\" y=\"48\" width=\"288\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"360\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">content</text>\n  <rect x=\"612\" y=\"48\" width=\"60\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"642\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append</text>\n  <circle cx=\"28\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"54\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"54\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"148\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"360\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"360\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"642\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"642\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <line x1=\"28\" y1=\"39\" x2=\"28\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"50\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-toolbar</text>\n", "code": "<component :is=\"tag\" class=\"origam-toolbar\">\n  <slot name=\"default\">\n    <div class=\"origam-toolbar__wrapper\">\n      <!-- prepend zone (nav icon, back btn) -->\n      <div v-if=\"hasPrepend\" class=\"origam-toolbar__prepend\">\n        <slot name=\"prepend\" />\n      </div>\n      <!-- title -->\n      <div v-if=\"hasTitle\" class=\"origam-toolbar__title\">\n        <slot name=\"title\">\n          <origam-title :text=\"title\" />\n        </slot>\n      </div>\n      <!-- flexible content area -->\n      <div class=\"origam-toolbar__content\">\n        <slot name=\"content\" />\n      </div>\n      <!-- append zone (action buttons, overflow) -->\n      <div v-if=\"hasAppend\" class=\"origam-toolbar__append\">\n        <slot name=\"append\" />\n      </div>\n    </div>\n  </slot>\n</component>", "legend": [{"cls": ".origam-toolbar", "num": 1, "descriptionKey": "components.toolbar.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;header&gt;</code> by default. Hosts the box-shadow and z-index."}, {"cls": ".origam-toolbar__prepend", "num": 2, "descriptionKey": "components.toolbar.anatomy.prepend", "descriptionFallback": "Leading zone. Rendered only when the #prepend slot has content. Margin-end: auto pushes the title to the right."}, {"cls": ".origam-toolbar__title", "num": 3, "descriptionKey": "components.toolbar.anatomy.title", "descriptionFallback": "Title zone. Contains an <code>OrigamTitle</code> by default, or the #title slot."}, {"cls": ".origam-toolbar__content", "num": 4, "descriptionKey": "components.toolbar.anatomy.content", "descriptionFallback": "Flexible center area. flex-grow: 1 so it absorbs all remaining space."}, {"cls": ".origam-toolbar__append", "num": 5, "descriptionKey": "components.toolbar.anatomy.append", "descriptionFallback": "Trailing zone. Rendered only when the #append slot has content. Margin-start: auto pushes it to the far right."}], "classes": [{"cls": "origam-toolbar", "descriptionKey": "components.toolbar.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-toolbar__wrapper", "descriptionKey": "components.toolbar.anatomy.wrapper", "descriptionFallback": "Inner flex row container."}, {"cls": "origam-toolbar__prepend", "descriptionKey": "components.toolbar.anatomy.prepend", "descriptionFallback": "Leading slot host."}, {"cls": "origam-toolbar__title", "descriptionKey": "components.toolbar.anatomy.title", "descriptionFallback": "Title slot host."}, {"cls": "origam-toolbar__content", "descriptionKey": "components.toolbar.anatomy.content", "descriptionFallback": "Flexible content area."}, {"cls": "origam-toolbar__append", "descriptionKey": "components.toolbar.anatomy.append", "descriptionFallback": "Trailing slot host."}], "svgDesc": "Schematic of the Toolbar component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamToolbar", "rootClass": "origam-toolbar", "figcaption": "Anatomy of <code>&lt;origam-toolbar&gt;</code> — 5 internal parts. The <code>__wrapper</code> arranges prepend, title, content and append in a row; the optional shadow line ① marks the bottom edge.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-toolbar---background", "defaultValue": "{color.surface.default}", "descriptionKey": "components.toolbar.css_vars.background", "descriptionFallback": "Toolbar background color."}, {"name": "--origam-toolbar---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.toolbar.css_vars.color", "descriptionFallback": "Foreground (text/icon) color."}, {"name": "--origam-toolbar---height", "defaultValue": "{space.14}", "descriptionKey": "components.toolbar.css_vars.height", "descriptionFallback": "Default height (56px). Overridden per density variant."}, {"name": "--origam-toolbar---height-compact", "defaultValue": "{space.10}", "descriptionKey": "components.toolbar.css_vars.height_compact", "descriptionFallback": "Height in density=\"compact\" mode (40px)."}, {"name": "--origam-toolbar---height-prominent", "defaultValue": "{space.20}", "descriptionKey": "components.toolbar.css_vars.height_prominent", "descriptionFallback": "Height in density=\"prominent\" mode (80px)."}, {"name": "--origam-toolbar---box-shadow", "defaultValue": "{shadow.sm}", "descriptionKey": "components.toolbar.css_vars.box_shadow", "descriptionFallback": "Box shadow. Set to none via the flat prop."}, {"name": "--origam-toolbar---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.toolbar.css_vars.transition_duration", "descriptionFallback": "Transition duration for height, transform, and box-shadow."}, {"name": "--origam-toolbar---z-index", "defaultValue": "{zIndex.fixed}", "descriptionKey": "components.toolbar.css_vars.z_index", "descriptionFallback": "Z-index of the toolbar when position is fixed or sticky."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.toolbar.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.toolbar.exposed.css", "descriptionFallback": "Reactive CSS string for the computed toolbar styles (used by DefaultsProvider)."}, {"name": "id", "type": "string", "descriptionKey": "components.toolbar.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.toolbar.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.toolbar.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.toolbar.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.toolbar.playground.title", "defaultValue": "My App", "labelFallback": "Title"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(surface)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.toolbar.playground.bg_color", "defaultValue": "", "labelFallback": "Background"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "prominent", "value": "prominent"}], "labelKey": "components.toolbar.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "select", "prop": "elevation", "options": [{"label": "0", "value": "0"}, {"label": "1", "value": "1"}, {"label": "2", "value": "2"}, {"label": "4", "value": "4"}, {"label": "8", "value": "8"}], "labelKey": "components.toolbar.playground.elevation", "defaultValue": "2", "labelFallback": "Elevation"}, {"kind": "switch", "prop": "flat", "labelKey": "components.toolbar.playground.flat", "defaultValue": false, "labelFallback": "Flat"}, {"kind": "switch", "prop": "floating", "labelKey": "components.toolbar.playground.floating", "defaultValue": false, "labelFallback": "Floating"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "pill", "value": "pill"}], "labelKey": "components.toolbar.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}]}, "previewVariants": [{"label": "default", "props": {"title": "App", "elevation": "2"}}, {"label": "flat", "props": {"flat": true, "title": "Flat"}}, {"label": "primary", "props": {"flat": true, "color": "white", "title": "Primary", "bgColor": "primary"}}, {"label": "compact", "props": {"title": "Compact", "density": "compact"}}, {"label": "rounded", "props": {"title": "Rounded", "rounded": "lg", "elevation": "2"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('24329dbf-e736-4fa6-924d-0340559bccb0', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'tooltip', 'Tooltip', 'Overlay & Surface', NULL, 'mdi-tooltip-text', 'components.catalog.tooltip.description', 'Contextual floating label anchored to an activator element. Appears on hover/focus, auto-positioned via location strategy.', NULL, NULL, 'origam-tooltip', NULL, 'packages/ds/src/components/Tooltip/OrigamTooltip.vue', 'origam', NULL, NULL, '/stories/?story=components-tooltip--design', '/docs/components/Tooltip/OrigamTooltip.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.tooltip.a11y.aria_describedby", "noteFallback": "The activator element receives aria-describedby pointing to the tooltip id so screen readers announce the tooltip text."}, {"noteKey": "components.tooltip.a11y.role", "noteFallback": "role=\"tooltip\" is applied directly on the OrigamOverlay element (not just the content div) so the association is unambiguous."}, {"noteKey": "components.tooltip.a11y.reduced_motion", "noteFallback": "Transitions are disabled under prefers-reduced-motion: reduce."}], "roles": ["tooltip"], "keyboard": [{"key": "Tab / Shift+Tab", "actionKey": "components.tooltip.a11y.key_focus", "actionFallback": "Focusing the activator opens the tooltip. Blurring closes it."}, {"key": "Escape", "actionKey": "components.tooltip.a11y.key_escape", "actionFallback": "Closes the tooltip if it was opened via keyboard focus."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__neutral---800)", "tokenPath": "--origam-tooltip---background-color", "descriptionKey": "components.tooltip.tokens.background_color", "descriptionFallback": "Dark inverse background for contrast in both themes."}, {"type": "color", "value": "var(--origam-color__text---inverse)", "tokenPath": "--origam-tooltip---color", "descriptionKey": "components.tooltip.tokens.color", "descriptionFallback": "Inverse text color (white on dark surface)."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-tooltip---border-radius", "descriptionKey": "components.tooltip.tokens.border_radius", "descriptionFallback": "Corner radius."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-tooltip---transition-duration", "descriptionKey": "components.tooltip.tokens.transition_duration", "descriptionFallback": "Enter/leave transition duration."}, {"type": "number", "value": "var(--origam-zIndex---tooltip)", "tokenPath": "--origam-tooltip---z-index", "descriptionKey": "components.tooltip.tokens.z_index", "descriptionFallback": "Z-index layer."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"250\" y=\"130\" width=\"200\" height=\"40\" rx=\"6\" fill=\"var(--origam-color__neutral---800, #1f1333)\"/>\n  <text x=\"350\" y=\"154\" font-size=\"11\" fill=\"var(--origam-color__text---inverse, #fff)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Tooltip text</text>\n  <polygon points=\"350,118 340,130 360,130\" fill=\"var(--origam-color__neutral---800, #1f1333)\"/>\n  <rect x=\"300\" y=\"60\" width=\"100\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"84\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">activator</text>\n  <circle cx=\"258\" cy=\"138\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"258\" y=\"142\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"350\" cy=\"138\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"142\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"350\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<origam-overlay role=\"tooltip\" :id=\"id\" class=\"origam-tooltip\" …>\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\" />\n  </template>\n  <template #default>\n    <!-- visible surface -->\n    <div class=\"origam-tooltip__content\">\n      <slot name=\"default\">\n        <span>{{ text }}</span>\n      </slot>\n    </div>\n  </template>\n</origam-overlay>", "legend": [{"cls": ".origam-tooltip", "num": 1, "descriptionKey": "components.tooltip.anatomy.root", "descriptionFallback": "Root overlay element — transparent, zero-size. Wraps OrigamOverlay; positions via location strategy. role=\"tooltip\" set explicitly."}, {"cls": ".origam-tooltip__content", "num": 2, "descriptionKey": "components.tooltip.anatomy.content", "descriptionFallback": "Visible content surface. Background: neutral.800 (dark inverse). Contains the text or #default slot."}, {"cls": "[activator]", "num": 3, "descriptionKey": "components.tooltip.anatomy.activator", "descriptionFallback": "External activator element projected via #activator slot. Receives aria-describedby pointing to the tooltip id."}], "classes": [{"cls": "origam-tooltip", "descriptionKey": "components.tooltip.anatomy.root", "descriptionFallback": "Root overlay element."}, {"cls": "origam-tooltip__content", "descriptionKey": "components.tooltip.anatomy.content", "descriptionFallback": "Visible floating pill with dark background."}], "svgDesc": "Schematic of the Tooltip overlay with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamTooltip", "rootClass": "origam-tooltip", "figcaption": "Anatomy of <code>&lt;origam-tooltip&gt;</code> — overlay wraps a content div ① with the text ②; the activator ③ (any element) triggers visibility.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-tooltip---background-color", "defaultValue": "{color.neutral.800}", "descriptionKey": "components.tooltip.css_vars.background_color", "descriptionFallback": "Tooltip background. Dark inverse surface for contrast in both themes."}, {"name": "--origam-tooltip---color", "defaultValue": "{color.text.inverse}", "descriptionKey": "components.tooltip.css_vars.color", "descriptionFallback": "Tooltip text color."}, {"name": "--origam-tooltip---font-size", "defaultValue": "{font.size.sm}", "descriptionKey": "components.tooltip.css_vars.font_size", "descriptionFallback": "Font size of the tooltip label."}, {"name": "--origam-tooltip---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.tooltip.css_vars.border_radius", "descriptionFallback": "Corner radius of the tooltip pill."}, {"name": "--origam-tooltip---max-width", "defaultValue": "300px", "descriptionKey": "components.tooltip.css_vars.max_width", "descriptionFallback": "Maximum width before tooltip text wraps."}, {"name": "--origam-tooltip---z-index", "defaultValue": "{zIndex.tooltip}", "descriptionKey": "components.tooltip.css_vars.z_index", "descriptionFallback": "Z-index of the tooltip overlay."}, {"name": "--origam-tooltip---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.tooltip.css_vars.transition_duration", "descriptionFallback": "Enter/leave transition duration."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tooltip.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to OrigamOverlay."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tooltip.exposed.css", "descriptionFallback": "Reactive CSS string for computed tooltip styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tooltip.exposed.id", "descriptionFallback": "Unique ID for this tooltip instance (referenced by aria-describedby on the activator)."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tooltip.exposed.load", "descriptionFallback": "Injects the computed style sheet."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tooltip.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tooltip.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}, {"name": "styleId", "type": "string", "descriptionKey": "components.tooltip.exposed.style_id", "descriptionFallback": "Unique style-sheet ID scoping injected CSS rules."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.tooltip.playground.text", "defaultValue": "This is a tooltip", "labelFallback": "Text"}, {"kind": "select", "prop": "location", "options": [{"label": "top", "value": "top"}, {"label": "bottom", "value": "bottom"}, {"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "top start", "value": "top start"}, {"label": "top end", "value": "top end"}, {"label": "bottom start", "value": "bottom start"}, {"label": "bottom end", "value": "bottom end"}], "labelKey": "components.tooltip.playground.location", "defaultValue": "top", "labelFallback": "Location"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(inverse dark)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.tooltip.playground.bg_color", "defaultValue": "", "labelFallback": "Background"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a4f49b43-0419-44ad-8556-db2eb4d1f6c4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'component', 'transition', 'Transition', 'Utilities & Providers', NULL, 'mdi-transition', 'components.catalog.transition.description', 'CSS-driven Vue transition wrappers. The family includes Fade, SlideX, SlideY, ExpandX, ExpandY, ScaleRotate and a generic Transition component. All are prefers-reduced-motion aware.', NULL, NULL, 'origam-transition', NULL, 'packages/ds/src/components/Transition/OrigamTransition.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.transition.a11y.reduced_motion", "noteFallback": "All Origam transition components detect prefers-reduced-motion: reduce and disable the animation (disabled=true) automatically. Content still appears/disappears instantly."}, {"noteKey": "components.transition.a11y.no_role", "noteFallback": "Transition wrappers are transparent to the accessibility tree — they add no ARIA roles or attributes. Only the slotted content is announced by screen readers."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"280\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"180\" y=\"84\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <rect x=\"380\" y=\"40\" width=\"280\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.5\"/>\n  <text x=\"520\" y=\"84\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"388\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"388\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"80\" font-size=\"20\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<!-- generic wrapper — delegates to <transition> or <transition-group> -->\n<component :is=\"group ? ''transition-group'' : ''transition''\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>", "legend": [{"cls": "[enter-active]", "num": 1, "descriptionKey": "components.transition.anatomy.enter", "descriptionFallback": "The entering element receives the transition CSS class (e.g. origam-transition--fade-enter-active)."}, {"cls": "[leave-active]", "num": 2, "descriptionKey": "components.transition.anatomy.leave", "descriptionFallback": "The leaving element receives the leave-active class and exits. In out-in mode this completes before the enter starts."}], "classes": [{"cls": "origam-transition--fade", "descriptionKey": "components.transition.anatomy.fade_cls", "descriptionFallback": "Opacity-only CSS transition class."}, {"cls": "origam-transition--slide-x", "descriptionKey": "components.transition.anatomy.slide_x_cls", "descriptionFallback": "Horizontal slide + fade CSS transition class."}, {"cls": "origam-transition--slide-y", "descriptionKey": "components.transition.anatomy.slide_y_cls", "descriptionFallback": "Vertical slide + fade CSS transition class."}, {"cls": "origam-transition--scale-rotate", "descriptionKey": "components.transition.anatomy.scale_rotate_cls", "descriptionFallback": "Scale + rotate + fade CSS transition class."}], "svgDesc": "Schematic showing transition wrapper over entering and leaving elements.", "svgTitle": "Anatomy of OrigamTransition", "rootClass": "origam-transition", "figcaption": "Anatomy of <code>&lt;origam-transition&gt;</code> — wraps a single child. During a transition, the entering element ① is animated in while the leaving element ② animates out (sequence depends on <code>mode</code>).", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-transition---default-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.transition.css_vars.default_duration", "descriptionFallback": "Default transition duration (300 ms)."}, {"name": "--origam-transition---default-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.transition.css_vars.default_easing", "descriptionFallback": "Default easing function (cubic-bezier)."}, {"name": "--origam-transition---slide-x-distance", "defaultValue": "100%", "descriptionKey": "components.transition.css_vars.slide_x_distance", "descriptionFallback": "Horizontal translate distance for slide-x transition."}, {"name": "--origam-transition---slide-y-distance", "defaultValue": "100%", "descriptionKey": "components.transition.css_vars.slide_y_distance", "descriptionFallback": "Vertical translate distance for slide-y transition."}, {"name": "--origam-transition---scale-from", "defaultValue": "0.95", "descriptionKey": "components.transition.css_vars.scale_from", "descriptionFallback": "Initial scale value for scale-based transitions."}, {"name": "--origam-transition---expand-duration", "defaultValue": "{motion.duration.slow}", "descriptionKey": "components.transition.css_vars.expand_duration", "descriptionFallback": "Duration for expand-x/expand-y transitions (400 ms — slightly slower for layout shifts)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.transition.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the underlying transition."}], "playground": {"controls": [{"kind": "select", "prop": "name", "options": [{"label": "fade", "value": "origam-transition--fade"}, {"label": "slide-x", "value": "origam-transition--slide-x"}, {"label": "slide-y", "value": "origam-transition--slide-y"}, {"label": "scale-rotate", "value": "origam-transition--scale-rotate"}], "labelKey": "components.transition.playground.name", "defaultValue": "origam-transition--fade", "labelFallback": "Transition"}, {"kind": "select", "prop": "mode", "options": [{"label": "(none)", "value": ""}, {"label": "in-out", "value": "in-out"}, {"label": "out-in", "value": "out-in"}], "labelKey": "components.transition.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.transition.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "group", "labelKey": "components.transition.playground.group", "defaultValue": false, "labelFallback": "Group mode"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
