INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d8d917dd-0669-4efc-9181-153fd57a1c6d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-both-color', 'useBothColor', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useBothColor(bgColorProps: T | Ref<TColor> | ComputedRef<TColor>, colorProps: T | Ref<TColor> | ComputedRef<TColor>, name?: K): { colorClasses: ComputedRef<string[]>; colorStyles: ComputedRef<string[]>; }', NULL, NULL, 'packages/ds/src/composables/Commons/bothColor.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('26c734fd-ca9d-41e8-806f-515e45708c5f', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-calendar', 'useCalendar', NULL, 'Calendar', 'mdi-calendar', '', 'Stateless calendar engine powering <OrigamCalendar>. Computes the visible date range for month/week/day/agenda views, expands recurring events (RRULE), and provides pure grid-builder functions for month, week, and day layouts. Navigation mutates the current date via optional callbacks so the composable can be driven from props, a store, or a local ref without re-instantiation.', NULL, 'function useCalendar(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('940d2c51-86f1-42d0-b036-c2a822079538', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-cell', 'useCell', NULL, 'DataTable', 'mdi-table-column', '', 'Resolve the padding for a DataTable cell based on the column definition. Special columns (data-table-select and data-table-expand) receive a fixed narrow padding; user-defined columns honour the column''s own padding setting; all others receive the default undefined (letting CSS tokens drive the spacing).', NULL, 'function useCell(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('20267de6-5edf-4ec2-9d22-8ccf9aa5db1d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-chart', 'useChart', NULL, 'Chart', 'mdi-chart-line', '', 'Stateless SVG chart engine powering <OrigamChart>. Computes every render-time descriptor needed for cartesian, polar, pie/donut, radar, bar, scatter, and stacked variants: viewBox, pixel-mapping scales, gridline ticks, per-series path/rect/circle descriptors, resolved legend entries, and an interactive hover state. Driven entirely by thunk options so it reacts to props, stores, or computed refs without re-instantiation.', NULL, 'function useChart(options: IUseChartOptions): {
