INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1f899c82-e22d-4aab-bd30-8ff6cb2508ac', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-chart-gauge', 'useChartGauge', NULL, 'Chart', 'mdi-gauge', '', 'Solid-gauge geometry engine for <OrigamChartGauge>. Given a value clamped between min and max, computes the SVG arc paths for the track (full arc background) and the indicator (partial arc proportional to the value), plus centre coordinates and radius values for the value label. Designed to mirror a speedometer-style gauge with a configurable sweep angle and thickness.', NULL, 'function useChartGauge(options: IUseChartGaugeOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b362d9d1-214c-46c3-ae50-20b8e7bf8a61', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-chart-header-typography', 'useChartHeaderTypography', 'Chart', 'Chart', NULL, NULL, NULL, NULL, 'function useChartHeaderTypography(props: ITypographyProps): { headerTypographyStyles: ComputedRef<StyleValue>; }', NULL, NULL, 'packages/ds/src/composables/Chart/chart-header-typography.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0d498cc7-081c-4390-8b16-5a5bef1e8675', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-chart-zoom', 'useChartZoom', NULL, 'Chart', 'mdi-magnify-plus-outline', '', 'Manages interactive zoom and pan state for OrigamChartCartesian. The zoom window is expressed as a closed [zoomStart, zoomEnd] range of category indices. Provides scroll-wheel zoom, drag-to-select zoom, and programmatic pan, all with clamping invariants.', NULL, 'function useChartZoom(options: { dataLength: () => number }): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a2b059fe-0ebf-4d1d-afde-83c22c949c7a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-clipboard', 'useClipboard', NULL, 'Clipboard', 'mdi-clipboard-outline', '', 'Headless clipboard composable. Wraps the modern navigator.clipboard.writeText API with a legacy execCommand fallback. Exposes a self-resetting copied flag so consumers do not need to wire the reset timeout themselves. Never throws — callers branch on the returned boolean.', NULL, 'function useClipboard(options?: IUseClipboardOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('83f0c2d8-2988-4023-9ec4-ea3e059d4a25', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-code', 'useCode', NULL, 'Code', 'mdi-code-tags', '', 'Singleton shiki-powered syntax highlighter. Lazily loads shiki on the first highlight() call to keep the initial bundle small. Bundles only the curated origam language subset and dual light/dark themes so token colours switch via CSS variables without re-tokenising. Caches results in a tiny LRU keyed by (code, lang).', NULL, 'function useCode(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f456f6d4-27d2-4824-b4c7-d9da5b216b52', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-color', 'useColor', NULL, 'Commons', 'mdi-palette', '', 'Resolve background and text colors from intent tokens or raw CSS values. Part of the classes-first strategy: tokenised intents emit utility classes, custom hex/rgb values emit inline styles.', NULL, 'function useColor(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('df0c51c1-84f7-42ab-90ca-6efc5f481bf5', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-color-effect', 'useColorEffect', NULL, 'Commons', 'mdi-palette-swatch', '', 'State-aware (hover / active / disabled) color resolution for components that paint a surface. Resolves bg and fg independently per state axis. Auto-contrasts foreground when only `bgColor` is set. Used by Btn, Card, Chip and ~49 other components.', NULL, 'function useColorEffect(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('de8d946e-d92d-413d-a235-4b1851127742', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-command', 'useCommand', NULL, 'CommandPalette', 'mdi-console-line', '', 'Process-wide command palette registry. Uses module-scope state (not provide/inject) so commands can be registered from anywhere — feature code, plugins, background services — without coupling to a Vue tree. Two callers on the same module instance see the exact same reactive list.', NULL, 'function useCommand(): {
