INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('070e3c67-5448-4cb5-97cb-6c68b4f3da22', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-padding', 'usePadding', NULL, 'Commons', 'mdi-arrow-collapse-all', '', 'Resolves the `padding` shorthand prop into utility classes for spacing-scale steps (0–12) or inline padding declarations for custom values. Mirror of useMargin for the padding axis.', NULL, 'function usePadding(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('067e169c-0f0d-4039-90e6-0a5e046f8a1c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-paginated-items', 'usePaginatedItems', 'DataTable', 'DataTable', NULL, NULL, NULL, NULL, 'function usePaginatedItems(options: { items: Ref<readonly (T | IDataTableGroup<T>)[]> startIndex: Ref<number> stopIndex: Ref<number> itemsPerPage: Ref<number> }): { paginatedItems: ComputedRef<readonly (T | IDataTableGroup<T>)[]>; }', NULL, NULL, 'packages/ds/src/composables/DataTable/paginatedItems.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('02f616db-82f9-485c-a1b4-b7da9ee19e26', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-pagination', 'usePagination', NULL, 'DataTable', 'mdi-book-open-page-variant-outline', '', 'Suite of three pagination helpers for OrigamDataTable: createPagination initialises page and itemsPerPage refs from props; providePagination computes derived state (startIndex, stopIndex, pageCount) and provides it to children; usePagination injects the provided pagination context. A fourth helper usePaginatedItems slices the items array for the current page.', NULL, '// Initialise pagination refs from props
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7ee754b9-c13a-4168-b2a1-8cb6f917ea05', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-parallax', 'useParallaxRuntime', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Headless parallax engine used by OrigamParallax. Maintains a registry of layers, tracks scroll progress via IntersectionObserver, and drives per-frame transforms via requestAnimationFrame. Branches automatically to a CSS scroll-driven animation path (Chrome 115+) when the easing is linear and the browser supports animation-timeline: scroll(). Respects prefers-reduced-motion at OS level.', NULL, 'function useParallaxRuntime(options: IUseParallaxRuntimeOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('64a385de-5040-4417-8284-0abba0b69116', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-parallax-transform', 'useParallaxTransform', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Computes CSS transform strings for parallax layer elements based on normalised mouse-position coordinates. Supports five transform types: translate, rotate, depth (3-D tilt), depth-inv (inverted tilt), scale, scale-x, and scale-y. Consumed by OrigamParallax to animate child layers.', NULL, 'function useParallaxTransform(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('96296b7d-ad89-40df-b238-0098f7122afe', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-passed-props', 'usePassedProps', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function usePassedProps(_props: T, instanceLabel?: string = ''usePassedProps''): (key: Extract<keyof T, string> | string) => boolean', NULL, NULL, 'packages/ds/src/composables/Commons/passedProps.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8cf6565f-cc88-4682-9ee1-f73d3d8fde34', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-password-strength', 'computeStrength', NULL, 'PasswordField', 'mdi-shield-lock-outline', '', 'Pure function (no Vue reactivity needed) that scores a password string on a 0-4 scale based on length, digit presence, case diversity, and special characters. Returns a numeric score and a semantic level (weak / fair / good / strong). Used internally by OrigamPasswordField to drive the strength bar colour and label. No third-party dependencies.', NULL, 'function computeStrength(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8a4761ed-0b5c-4db3-98cb-b42ca8044f33', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-position', 'usePosition', NULL, 'Commons', 'mdi-map-marker-outline', '', 'Derives CSS positioning classes and inline style declarations from IPositionProps. Emits a BEM modifier class for the position variant (absolute, fixed, sticky, relative, static) and inline top/bottom/left/right properties for any offset props that are set.', NULL, 'function usePosition(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8a104012-809d-4a94-a714-3cf6fe5e899a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-progress', 'useProgress', NULL, 'Progress', 'mdi-progress-clock', '', 'Computes all state needed to render a progress bar or circular progress indicator: a normalised 0-100 value from modelValue and max, thickness as a number, a visibility flag tied to IntersectionObserver, and BEM class/style arrays that handle indeterminate, striped, active, and absolute modes. Used by OrigamProgressLinear and OrigamProgressCircular.', NULL, 'function useProgress(props: IProgressTypeProps): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('907d7320-add6-442d-bf03-7848899ad929', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-props', 'useProps', NULL, 'Commons', 'mdi-tune-variant', '', 'Returns a filterProps utility that picks only the keys declared on a component interface from an arbitrary props object, stripping undefined values so that Vue 3 boolean-prop coercion does not silently override withDefaults in child components. Used by composite components (DataTable, List, Select…) to forward a safe subset of their own props to child Origam components.', NULL, 'function useProps<T extends Record<string, any>>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f227ab63-da4d-4de1-850e-7c4369429c20', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-qr-code', 'useQrCode', NULL, 'QrCode', 'mdi-qrcode', '', 'Headless QR-code composable. Encodes a string payload using qrcode-generator (Reed-Solomon + matrix masking) and returns a reactive SVG string, the raw module matrix, and the matrix size. The encoder is LRU-cached at module level to avoid rebuilding identical matrices on re-renders. Fully SSR-safe — no DOM API is touched.', NULL, 'function useQrCode(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('76a84e01-3416-4f52-a6e4-2aec89d9e860', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'const', 'chart-gauge-default-end-angle', 'CHART_GAUGE_DEFAULT_END_ANGLE', 'Chart', NULL, NULL, NULL, NULL, 'export const CHART_GAUGE_DEFAULT_END_ANGLE = Math.PI * 3 / 4', NULL, NULL, 'Math.PI * 3 / 4', 'packages/ds/src/consts/Chart/chart-gauge.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f36c2b6b-2584-405f-988f-ee563f505b8c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-refs', 'useRefs', NULL, 'Commons', 'mdi-link-variant', '', 'Manages a dynamic array of template refs that is reset before each update cycle. Provides an updateRef(el, i) callback designed for use with :ref in v-for loops, where Vue replaces individual refs by index. The refs array is always fresh (cleared in onBeforeUpdate) so stale elements from a previous render do not leak.', NULL, 'function useRefs<T extends object>(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c27fd5fa-a118-486a-a6b4-271a93e506ae', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-resize-observer', 'useResizeObserver', NULL, 'Commons', 'mdi-resize', '', 'Wraps the native ResizeObserver API with a reactive template ref. Returns a resizeRef to attach to any element and a readonly contentRect that updates on every resize. Automatically disconnects the observer on component unmount. Supports both content-box (default) and border-box measurement.', NULL, 'function useResizeObserver(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8660befe-cec6-4bd0-a335-ab542f0a01cb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-rounded', 'useRounded', NULL, 'Commons', 'mdi-rounded-corner', '', 'Resolves the `rounded` prop to border-radius classes and inline styles. Supports the modern utility taxonomy (xs/sm/md/lg/xl/none/full), the legacy named variants (x-small/small/default/medium/large/x-large/shaped), numbers and free-form CSS values.', NULL, 'function useRounded(
