INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('22a52856-27e4-4fba-acbc-4d4bcd81ff6a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-v-model', 'useVModel', NULL, 'Commons', 'mdi-swap-horizontal', '', 'Implements a controlled / uncontrolled prop contract for any component prop bound via v-model. When the parent provides both the prop and the matching onUpdate:prop listener the component operates in controlled mode; otherwise it manages its own internal ref. Supports kebab-case / camelCase prop alias pairs and optional in/out value transformers.', NULL, 'function useVModel<
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e894e743-ccbe-4f83-bb8c-30046bd2b3b2', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'composable', 'use-watermark', 'useWatermark', NULL, 'Watermark', 'mdi-watermark', '', 'Headless watermark composable. Builds a repeating SVG tile from text or an image URL and exposes it as a CSS `background-image` data URL. Provides `install()` / `uninstall()` helpers for programmatic use. Optionally watches the DOM via MutationObserver to re-inject the layer if it is removed (anti-tamper mode). SSR-safe — no DOM access in the reactive core.', NULL, 'function useWatermark(
