INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c01a826d-8338-4e58-9d0b-83354b2b1deb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'interface', 'i-chart-pyramid-props', 'IChartPyramidProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_pyramid_props.description', 'Props for <OrigamChartPyramid> — the pyramid / funnel family. A single series of N data points is rendered as N horizontal trapezoids stacked vertically. type="funnel" = widest at top (conversion funnel); type="pyramid" = widest at bottom. Extends IChartBaseProps.', 'export interface IChartPyramidProps extends IChartBaseProps {
