INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06e2e4d2-5549-432a-9e56-70c2f9b3fcd6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '55c1c429-d1f2-4e5a-94dc-2b78227789e6', 'value', 'boolean | { class?: string; center?: boolean; circle?: boolean }', false, 'directives.ripple.arg_value', 'Pass false to disable. Pass an object to set a custom class on the ripple element or to override center/circle via the value (equivalent to using modifiers).', 0, false, NULL, NULL);
