INSERT INTO public.doc_directive_arg (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1a305146-3cd1-45e6-8d06-cc1e65ad3599', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'be33fe97-136f-48c9-97ad-56d0e1cc03e2', 'parent', 'boolean', false, 'directives.touch.arg_parent', 'When true, listeners are attached to the parentElement instead of the element itself. Useful for scrollable containers where the element may be smaller than the gesture area.', 2, false, NULL, NULL);
