INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d470aeb-9cd7-42f7-af15-3a407c2c0cdb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'fd5699b0-f2b7-49fc-b473-0fa71566f50b', 'stop', NULL, false, 'directives.hover.modifier_stop', 'Calls stopPropagation() on the underlying pointer events, preventing parent hover handlers from triggering.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('079878a8-5e61-43c7-9668-6aa91c10eb06', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '70e80571-d769-4f25-be18-f7e8782b4fec', 'once', NULL, false, 'directives.intersect.modifier_once', 'Disconnects the observer after the element enters the viewport for the first time. Useful for one-shot animations.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0bd46a3c-c9f1-40c5-b25a-89311416c0b6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '70e80571-d769-4f25-be18-f7e8782b4fec', 'quiet', NULL, false, 'directives.intersect.modifier_quiet', 'Suppresses the first callback call that IntersectionObserver fires synchronously on setup, so the handler only fires on real scroll-triggered intersections.', 1, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('49c532a1-bded-4c99-ada6-149d3ad1cd0a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '55c1c429-d1f2-4e5a-94dc-2b78227789e6', 'center', NULL, false, 'directives.ripple.modifier_center', 'The ripple always starts from the geometric center of the element instead of the actual click position. Typically used for icon buttons.', 0, false, NULL, NULL);
INSERT INTO public.doc_directive_modifier (id, created_at, updated_at, entry_id, name, type, required, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5e94d08c-9b41-49e2-9f65-f57f4c20939c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '55c1c429-d1f2-4e5a-94dc-2b78227789e6', 'circle', NULL, false, 'directives.ripple.modifier_circle', 'Clips the ripple container to a perfect circle. Combine with .center for round icon buttons.', 1, false, NULL, NULL);
