INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fed66673-8ceb-40fd-a50f-f817cc7a09d2', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5efe645d-28e4-4d94-816d-6656bc80878d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d5f5c941-0844-4706-9bed-1c686d566790', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0ceee695-a1a3-473f-9f98-8edd70596c1e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '22251967-d38f-4cf2-8d7e-c297194a1592', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('006a0a11-e4e6-47fd-be11-70df02ded0ac', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '22251967-d38f-4cf2-8d7e-c297194a1592', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6d4a3a69-1e80-4ed6-96a7-6e0d35799296', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '22251967-d38f-4cf2-8d7e-c297194a1592', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('21def5ad-376f-4156-a81c-58adbc7d0848', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '34674f64-f72c-4d4b-aab2-902533477104', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d967124-ac19-4b84-9779-fffb1dd008a6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '34674f64-f72c-4d4b-aab2-902533477104', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dea9341e-2bae-4c3e-848b-31cd0e4b145d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '34674f64-f72c-4d4b-aab2-902533477104', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e9585c6-2c45-42fd-bf09-fcd27eb13b7d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '8cd7eb79-1533-470e-945e-9349b0976696', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1fa6b2ed-49ae-4f04-ac01-2fe537f6d7ac', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '2f994780-080b-47b5-8574-38535b2a4f2b', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bed49e5c-beca-4076-b1aa-80345ef64a69', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '5162aed5-943a-4ab1-b774-ab3b261c6c5f', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9da909f0-6411-40c6-b4d6-ff6bc90919fc', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a5fdaa48-5a71-4edf-ba58-277a354c0279', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
