INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('57842c61-770a-4c85-a317-d298026cccfb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '26c734fd-ca9d-41e8-806f-515e45708c5f', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('785c4594-20c7-474a-b89e-5dbc1cd6f4a6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '26c734fd-ca9d-41e8-806f-515e45708c5f', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96c95040-03be-406a-b1d9-bb873c3092ce', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '26c734fd-ca9d-41e8-806f-515e45708c5f', 'setCurrentDate', '(date: Date) => void', false, NULL, '', 'Optional callback invoked by navigate(). Bind to a v-model:currentDate setter. If omitted, navigation calls have no effect on the parent state.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dbd87c51-bf43-4da0-829e-f2c474830fd4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '20267de6-5edf-4ec2-9d22-8ccf9aa5db1d', 'options', 'IUseChartOptions', true, NULL, '', 'Configuration object with getter thunks for type, series, categories, stacked, stacking, donutHoleSize, colorScheme, smoothing, yMin, yMax, width, height, padding, and optional hiddenLabels and secondaryYAxis. All values are () => T functions so the composable reacts to any reactive source.', 0, false, NULL, NULL);
