INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ee1835c1-b866-4e13-9b1f-936fb1218f34', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'f227ab63-da4d-4de1-850e-7c4369429c20', 'value', 'MaybeRefOrGetter<string>', true, NULL, '', 'The payload to encode: URL, text, vCard, etc. Accepts a plain string, a ref, or a getter function. Reactive — the SVG rebuilds whenever value changes.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('be5f8d44-e583-46d5-b7ba-45683987eeda', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'f227ab63-da4d-4de1-850e-7c4369429c20', 'options', 'MaybeRefOrGetter<IUseQrCodeOptions>', false, '{}', '', 'Encoding and rendering options: errorCorrectionLevel ("L" | "M" | "Q" | "H"), foreground, background, margin (module units), cornerRadius (per <rect>), and logo ({ src, size, padding, background }).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a64db52a-592d-4768-8a5f-b2be8795813e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c27fd5fa-a118-486a-a6b4-271a93e506ae', 'callback', 'ResizeObserverCallback', false, NULL, '', 'Optional raw ResizeObserver callback. Receives the full entries array and the observer instance. Called on every resize event before contentRect is updated.', 0, false, NULL, NULL);
