INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1a67980b-9b6d-4813-8dc5-95b882c95e12', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '844687a5-ca5d-449d-8505-c414e3383e34', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('973c0b6a-a38c-4c03-a164-3fe9103f6f7c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '844687a5-ca5d-449d-8505-c414e3383e34', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('baf2ef24-ee62-4665-8583-82b5b898addf', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '844687a5-ca5d-449d-8505-c414e3383e34', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('338d1e3e-5d8b-44a2-90e2-20070aa5da61', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('32c0dfd0-86da-4e5b-ab5e-e9dc33dbfa56', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2b9e99d0-31e7-43ba-b35e-df60e5edc62a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'ac0d4964-3e66-4b51-ab6f-2abef635d149', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d2933479-61cc-4c41-bf44-8a23e47187fb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3cd0fa84-73e9-4763-a7dd-2f919aa5cc75', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6b9a454c-ff31-40f8-acb8-a7bdbb095720', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('092c9787-96b7-4d28-bd50-3176e8df06f4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96d79c74-8e3b-40a6-bdd0-ef8fe2489213', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3a5206e6-1fc4-4065-b3f2-611974b42a60', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '6f18ee44-3748-45c6-b3bb-009a30e57d8c', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f1ae43f8-99a9-4d3a-9742-8fdd2ef47a63', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '6f18ee44-3748-45c6-b3bb-009a30e57d8c', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c4c15466-a8cf-412c-bf9e-4ba0c38ecf23', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3a6ead70-bfb0-46ff-83b2-81d990dc77b7', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a73d3fc3-3876-4b6a-97dd-98483f97bf6a', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3a6ead70-bfb0-46ff-83b2-81d990dc77b7', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('254e2cfc-0a25-4a00-8a86-bfebdde516ab', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4c46fd30-6da0-4b17-973d-ceffdbc65fc9', 'rootEl', 'Ref<HTMLElement | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('39374975-4e93-4081-b9ba-314c4b2229a6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4c46fd30-6da0-4b17-973d-ceffdbc65fc9', 'isSticky', 'Ref<boolean>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('01ddcf5b-db4f-49f3-b2ff-1254f98ff44e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4c46fd30-6da0-4b17-973d-ceffdbc65fc9', 'layoutItemStyles', 'Ref<CSSProperties>', true, NULL, NULL, NULL, 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ed26c357-dc1a-40df-bd81-675adea22299', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a3473b0f-0c26-4c9f-ba25-71195dfa1a79', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7374ea7f-72ff-4e27-a17e-4e3459484ad3', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a3473b0f-0c26-4c9f-ba25-71195dfa1a79', 'uniq', 'MaybeRefOrGetter<string | undefined>', false, 'undefined', '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b03be5e3-bc58-4381-86e7-f80e3ad643a7', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a3473b0f-0c26-4c9f-ba25-71195dfa1a79', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('954c912b-460a-4f83-ab23-bf68b4f51bab', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a138e14b-9065-447d-aede-ef4a33ff9339', 'css', 'MaybeRef<string>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
