INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d10d6cdb-d365-47cf-a07c-26760fbff68d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'd0d553d0-57dc-402f-9c16-d9640506794a', 'target', 'Ref<boolean | string | Element>', true, NULL, '', 'Reactive teleport destination. true → returns undefined (Vue Teleport disabled, renders in-place). false → document.body. A CSS selector string → querySelector result. An Element → used directly. Returns undefined and warns if a string selector yields no match.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1db17ba4-ff85-4aac-9c52-6cb2ab029d4f', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '1cba24f1-31f5-4fc6-8187-c1c1cf840913', 'fieldRef', 'Ref<{ $el?: HTMLElement } | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
