INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a86cdad1-9c13-4f2b-850d-06837d3b89e9', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a895f838-cef8-4b07-b18f-adc1f1271c23', 'options', 'IUseTextareaRichOptions', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd626834-8e80-4b95-9de7-4ab374525f18', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '891e3cc3-7783-4daf-9bad-bf185a1c3b04', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fce3eeb9-ed81-4277-a6e8-52b85e1d455b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '2dedac23-93a2-4659-9973-1b4307645558', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('46136ded-0dea-4c0a-aaeb-9ce691fd1c29', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '2dedac23-93a2-4659-9973-1b4307645558', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f4eb8062-ce0b-442e-8914-b7d44b9a777b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '6f787686-c196-43bb-8c7e-80a68b73e6f8', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ccb671a9-8e30-4d72-84e6-cde4943f5d5c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '6f787686-c196-43bb-8c7e-80a68b73e6f8', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('270a53da-d496-45a9-a4eb-459184e786ea', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '04bf9a44-3752-4066-8b04-041612a343fd', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b7ceb7b8-c9f7-4e10-9c07-2c57ee8e666b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '04bf9a44-3752-4066-8b04-041612a343fd', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1ad43396-316b-4772-8f2d-353e0586c68e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'ac0d4964-3e66-4b51-ab6f-2abef635d149', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3e03074d-e70e-402d-9a5f-2227364fca65', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'ac0d4964-3e66-4b51-ab6f-2abef635d149', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54452330-ba00-4570-b1e2-5b9768966001', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3f75d746-c0ca-470f-9a6b-0a279ef0d252', 'a', 'Date', true, NULL, 'utils.detail.diff_minutes.param_a', 'The start date (reference).', 0, false, NULL, NULL);
