INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('73ef28ea-f203-4be2-9146-f647c646bea9', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c6d0211d-3a2e-45a9-a6fd-2910f3a06828', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1c4d5ec9-b4bf-4ba4-bcc4-d144d27c3694', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '22a52856-27e4-4fba-acbc-4d4bcd81ff6a', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ccc8b12-dc01-462c-8404-1f82ac5d7aeb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '22a52856-27e4-4fba-acbc-4d4bcd81ff6a', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
