INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('904f87f7-0847-4469-9db7-1f46eda10eaa', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '22a52856-27e4-4fba-acbc-4d4bcd81ff6a', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('346ca92b-7253-46b7-ae89-0173946daba5', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '22a52856-27e4-4fba-acbc-4d4bcd81ff6a', 'transformOut', '(value: Inner) => Props[Prop]', false, '(v: Inner) => v as Props[Prop]', '', 'Optional inverse transform applied before emitting `update:prop`. Pairs with transformIn to keep the internal representation separate from the public API value.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('baaec7cb-7cdd-4139-bc90-81e3eff3af64', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e894e743-ccbe-4f83-bb8c-30046bd2b3b2', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('34cf520b-f75b-435c-99bf-f94a17418432', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'ec9a22a2-e775-4a93-93f1-607e6f624356', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2018c3fc-2fa6-4093-8142-24af6993d749', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'ec9a22a2-e775-4a93-93f1-607e6f624356', 'options', 'IUseWaveformOptions', false, '{}', '', 'Optional: `bins` (number of peaks to produce, default 200) and `crossOrigin` ("use-credentials" | undefined) for the fetch credentials policy.', 1, false, NULL, NULL);
