INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('67271d5e-5766-4a2a-87f2-48954e400963', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '02e44913-f9e4-4fa7-a062-3607acdbf4ec', 'hex', 'string', true, NULL, 'utils.detail.parse_hex.param_hex', 'A hex color string in any accepted format: with or without `#`, 3/4/6/8 digit. Invalid characters are silently coerced to `F`.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('757314ee-889e-499e-ac5e-dc66317c7ae4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b916b6fc-33c3-4930-9c64-74e4ab7dea27', 'input', 'number[] | string | null | undefined', true, NULL, 'utils.detail.parse_highlight_lines.param_input', 'A number array, a comma- and/or range-separated string (e.g. `"1"`, `"1,3"`, `"1-3"`, `"1,3-5,7"`), or null/undefined. Whitespace inside the string is ignored. Zeros, negatives, and non-finite values are dropped silently.', 0, false, NULL, NULL);
