INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6b6ac9bd-b48f-4eab-b6ab-a5b974df4e93', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b1431132-52e0-407e-91ed-daf8f859cbec', 'pattern', 'string', true, NULL, 'utils.detail.parse_pattern.param_pattern', 'The mask pattern string. Special characters: `#` (digit), `A` (letter), `*` (any). Every other character is treated as a literal separator (e.g. `-`, `/`, `(`, `)`).', 0, false, NULL, NULL);
