INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d237a69f-a48d-44dc-9f57-5b8cda062071', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '89be4c3a-891d-458f-9e21-b20d3eaf577c', 'value', 'Date | string | number | null | undefined', true, NULL, 'utils.detail.to_date.param_value', 'The raw value to coerce. A Date is cloned; a string is parsed via `new Date()` (ISO-8601 natively supported); a number is treated as epoch milliseconds. null and undefined return null immediately.', 0, false, NULL, NULL);
