INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('71dbc189-7891-44b0-b960-0b2b5063297d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '249ab1c6-73bd-4a40-8469-10b26dedb754', 'feedback', '(bindings: { copied: boolean }) => any', NULL, NULL, true, NULL, NULL, NULL, 'Custom feedback marker rendered when copied is true. Scoped — receives the boolean for symmetry with the default slot.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('67fd5614-f92e-498e-93cb-9b387a625723', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '59aa7435-b295-47db-a19d-03815ada3802', 'feedbackDuration', 'number', NULL, NULL, true, NULL, '2000', NULL, 'Duration (ms) the returned `copied` ref stays true after a successful write before auto-resetting.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36e68c4c-da82-468d-b752-028356968d44', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '08fb04be-3c13-47ba-a53e-436f3a26ba57', 'code', 'string', NULL, NULL, true, NULL, NULL, NULL, 'The code to highlight. When omitted the default slot is used as the source. When both are provided the prop wins.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('05d5539f-113a-4e53-9ce4-5937cfc2df52', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '08fb04be-3c13-47ba-a53e-436f3a26ba57', 'lang', 'TCodeLangOpen', NULL, NULL, true, NULL, NULL, NULL, 'Language grammar to apply (e.g. "typescript", "vue"). Unknown values fall back to "plaintext" with a one-shot console warning.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e2419a8e-697a-4262-87ab-c1b8a1950347', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '08fb04be-3c13-47ba-a53e-436f3a26ba57', 'lineNumbers', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Show a left gutter with line numbers. Pure CSS — uses a CSS counter incremented per .origam-code__row.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('187f0cf4-37f1-40d3-bc12-bae90ef68143', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '08fb04be-3c13-47ba-a53e-436f3a26ba57', 'highlightLines', 'number[] | string | null', NULL, NULL, true, NULL, NULL, NULL, 'Lines to highlight. Accepts a pre-computed array of 1-based line numbers or a comma/range string ("2,5-7"). null / empty disables the feature.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('db214118-8140-480e-876c-7e0f082639bd', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '08fb04be-3c13-47ba-a53e-436f3a26ba57', 'copyable', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Show the copy-to-clipboard button in the top-right corner. Defaults to true.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d964020d-70c1-4cfb-952f-c6c4059f0a30', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '08fb04be-3c13-47ba-a53e-436f3a26ba57', 'format', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Auto-format the code before highlighting. Reserved for v3 — currently a no-op that warns once in dev.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4911ed5f-1468-4cca-a47f-6f63ad4b447b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '08fb04be-3c13-47ba-a53e-436f3a26ba57', 'wrap', 'boolean', NULL, NULL, true, NULL, NULL, NULL, 'Wrap long lines instead of scrolling horizontally. Off by default so the visual column matches the source file.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('367f2335-055f-45c9-94a7-c1ceabad0515', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '08fb04be-3c13-47ba-a53e-436f3a26ba57', 'filename', 'string', NULL, NULL, true, NULL, NULL, NULL, 'Optional filename rendered in the header bar (e.g. "App.vue"). When provided and copyable is true, the header also hosts the copy button.', 7, false, NULL, NULL);
