INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0e68816f-514b-408c-983d-3e99f47b7d69', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '100c7d9e-57ca-4321-8ed5-5ac55bca1b49', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Anchor descriptor that combines a side ("top", "bottom", "left", "right", "center") with an optional alignment ("start", "end"). Controls where the floating content appears relative to its target.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7838db3a-3de3-4912-8eb1-8c13496281cb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '2d40f6b8-cdd4-472f-9ddd-2d97059e321a', 'locationStrategy', 'TLocationStrategy | TLocationStrategyFn', NULL, NULL, true, NULL, NULL, NULL, 'Named strategy ("connected" | "static") or a custom strategy function. The connected strategy aligns the floating panel to the activator; static keeps it in place.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5a270d67-1a52-4c65-9c0c-f68936941d09', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '2d40f6b8-cdd4-472f-9ddd-2d97059e321a', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Side and alignment where the floating content appears relative to the activator (e.g. "bottom start", "top end").', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('442200a2-7828-4670-b9cd-1e4212217fa8', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '2d40f6b8-cdd4-472f-9ddd-2d97059e321a', 'origin', 'TAnchor | ''auto'' | ''overlap''', NULL, NULL, true, NULL, NULL, NULL, 'The anchor point on the floating content itself. "auto" mirrors the location; "overlap" places the panel over the activator.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8f63cb5-cd3f-4278-bc72-ad61947e0622', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '2d40f6b8-cdd4-472f-9ddd-2d97059e321a', 'offset', 'number | string | Array<number>', NULL, NULL, true, NULL, NULL, NULL, 'Gap in pixels between the activator and the floating content. An array of two values sets [main-axis, cross-axis] offsets independently.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1257314c-76a1-45a3-96fe-3dbad2465b2e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '2d40f6b8-cdd4-472f-9ddd-2d97059e321a', 'viewportMargin', 'number', NULL, NULL, true, NULL, '12', NULL, 'Minimum breathing room in pixels between the floating content and each viewport edge. Defaults to 12 so panels never overlap browser chrome.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eef38100-d94f-4a4e-b267-8c8e1feb6bbf', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '9045b3ed-632c-4510-b4a6-768e514073d6', 'contentEl', 'Ref<HTMLElement | undefined>', NULL, NULL, false, NULL, NULL, NULL, 'Reactive reference to the floating content element. The strategy reads its dimensions and writes its position here.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d6480026-ddb6-4c1c-96a3-cb20909acd90', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '9045b3ed-632c-4510-b4a6-768e514073d6', 'target', 'Ref<HTMLElement | [x: number, y: number] | undefined>', NULL, NULL, false, NULL, NULL, NULL, 'Reactive reference to the anchor element or an [x, y] pixel coordinate. When set to coordinates, the floating panel anchors to a virtual point (used by context menus).', 1, false, NULL, NULL);
