INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('80ab8ea5-1f22-4ccc-8ab0-6856b7839cda', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'lang', 'TCodeLangOpen', 'code-lang', 'type', NULL, false, '''plaintext''', 'components.code.props.lang.description', 'Language grammar to apply. Supported: ''plaintext'' | ''vue'' | ''ts'' | ''js'' | ''tsx'' | ''jsx'' | ''scss'' | ''css'' | ''json'' | ''bash'' | ''html'' | ''xml'' | ''yaml'' | ''md''. Unknown values fall back to plaintext.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd08ce20-67a6-4c60-9c7a-3a1a52bb6f26', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6f5c8b31-06bc-419a-8941-ca5a24ffd1e1', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'highlightLines', 'number[] | string | null', '', 'primitive', NULL, false, 'null', 'components.code.props.highlight_lines.description', 'Lines to highlight. Accepts a 1-based array ([2, 5, 6]) or a range string (''2,5-7''). Null/empty disables.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87ea54e4-6ade-4aeb-bfc3-16d3f6ef4e80', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f8709588-d225-4c82-834e-d008520455fc', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a9e5748c-4322-4ce2-9ab4-28ee4ea80bc2', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'wrap', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.wrap.description', 'Wraps long lines instead of scrolling horizontally.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0cb7659c-0356-4ebd-b782-1e580c28b5df', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'filename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.filename.description', 'Optional filename rendered in the header bar (e.g. ''App.vue''). When present AND copyable=true, the header hosts the copy button; otherwise the copy button floats in the top-right corner.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b433efc2-8fa0-4689-9ecd-0c6cb013a7b3', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e399e57b-da6e-4b6a-a329-f7230ee910d4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'prompt', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.prompt.description', 'Decorative prefix rendered before the code (e.g. ''$'' for shell commands). Purely visual — not copied to clipboard.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e2996751-8bfc-4789-a318-b9e93dde934c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'hideHeader', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Do not render the header bar (filename / language badge / copy button). For a block embedded in a surface that already shows that information, such as a tab of OrigamCodeGroup.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('41e31860-a344-4858-8c14-95903fceb9b8', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', 'd3177154-41d8-4f70-9b4e-e4e1d0047a73', 'flat', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Flatten the block into its host: no border, no radius, no elevation, no outer margin.', 11, false, NULL, NULL);
