INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a277c693-3832-4d48-bed4-d63d25f0c770', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'state', 'IMediaPlayerState', '', 'primitive', NULL, true, '—', 'components.media_controller.props.state.description', 'Reactive media state from useMediaPlayer() (or a specialisation: useVideoPlayer, useAudioPlayer). Contains refs for playing, currentTime, duration, volume, muted, buffered, playbackRate, remoteAvailable, remoteState.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5681bedd-b501-4460-96ad-a3f0eb6d3615', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'methods', 'IMediaPlayerMethods', '', 'primitive', NULL, true, '—', 'components.media_controller.props.methods.description', 'Imperative methods from useMediaPlayer(). Provides play(), pause(), seek(), setVolume(), toggleMute(), setPlaybackRate(), requestRemotePlayback().', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04781e39-06ea-4f2e-ad11-8ba758db0b82', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'inset', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.inset.description', 'YouTube-style overlay mode: the shell sits on top of the media surface with a dark gradient and auto-hides on visible=false. When false, renders as a regular always-on toolbar.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9a16aefe-b0d9-43a2-b526-4e35dd14b9da', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'visible', 'boolean', '', 'primitive', NULL, false, 'true', 'components.media_controller.props.visible.description', 'Visibility flag driven by the parent autohide logic. Only meaningful when inset=true. When false, the shell is opacity: 0 and pointer-events: none.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ae9b2f48-bf09-4288-b542-782689c2e4df', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', NULL, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('09a70a46-6a06-4492-bd81-2fc2c7092431', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'allowRemotePlayback', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dfd642f0-9744-433a-83bc-191ba7c2c7f4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ecd9fdc3-f5fc-4149-9a9d-348df645c98c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'downloadUrl', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.download_url.description', 'URL surfaced to the consumer when the Download menu item is clicked. Supports same-origin, data: and blob: URLs natively; cross-origin URLs are routed through a fetch → blob pipeline.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4fa8c938-815f-4f07-a753-a263a9e0539b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'downloadFilename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5b5e0f1f-f460-4dea-bcc3-abd88a19c8f1', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'qualityOptions', 'ReadonlyArray<TQualityOption>', '', 'primitive', NULL, false, '[]', 'components.media_controller.props.quality_options.description', 'Optional list of quality variants. When ≥ 2 entries are present, a "Quality" drill-down appears in the config menu. Each entry is { quality: string; label: string }.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4e2a41cd-573c-4455-9488-6f0c5a089460', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'currentQuality', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3ecb6f44-e206-492d-9430-c8a87f90133e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'showPrevious', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_previous.description', 'Show the "previous track" transport button. The parent listens to the previous emit and decides the action (skip back 10s or jump to the previous playlist track).', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a5521ef7-c4ee-4748-9ebe-fa7c13ac3206', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'showNext', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('028fb8be-1b4f-425a-951f-a4c1b87b1c0e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'showLoop', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_loop.description', 'Show the tri-state loop button (none → all → one → none). Supports v-model:loopMode.', 13, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ef11417e-fdf8-493e-8cf0-8323bfadf665', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'showShuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_shuffle.description', 'Show the shuffle toggle button. Supports v-model:shuffle.', 14, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6073ec4d-cf4b-4c2d-a786-50ef2b107ee6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'loopMode', 'TAudioLoopMode', '', 'primitive', NULL, false, '''none''', 'components.media_controller.props.loop_mode.description', 'Current loop mode: "none" | "all" | "one". The Controller cycles on click and emits update:loopMode; the parent applies its playlist or <audio loop> policy.', 15, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fb9b644a-431f-46f0-b329-b4d5f1992bd9', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '06b9aec7-ab34-4d87-b024-07ad5d4d4b57', 'shuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.shuffle.description', 'Current shuffle state. The Controller toggles on click and emits update:shuffle; the parent switches its next-track resolution.', 16, false, NULL, NULL);
