INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bcbd16e6-5422-4089-9c09-425e9043aed6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:21.970851+00', '6f08cea4-f0c8-4f09-bea6-4b1f65def9b5', 'modelValue', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.model_value.description', 'Current value between min and max. Supports v-model. The component never mutates this directly — every change surfaces via update:modelValue.', 0, false, NULL, NULL);
