INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('46e7f074-2576-439b-b7c0-1ba7433922b8', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'activatorRef', 'Ref<HTMLElement | undefined>', '', 'Template ref for a statically rendered activator child. Assign to the activator element via v-bind to let the composable resolve it automatically on mount.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cb57e616-8211-4d9a-88d5-858ab8b468e6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'target', 'ComputedRef<HTMLElement | [x: number, y: number] | undefined>', '', 'Resolved positioning target. Returns cursor coordinates when target="cursor" is set, the element bound to targetRef when provided, or falls back to the activatorEl.', 2, false, NULL, NULL);
