INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4144f886-87c2-493f-8c64-ca3843dee29f', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'targetRef', 'Ref<HTMLElement | undefined>', '', 'Template ref for an explicit positioning target element, independent from the activator element.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4fafcefc-3a3f-4d76-96a9-999a315f8109', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'activatorEvents', 'ComputedRef<Partial<Record<string, EventListener>>>', '', 'Event listeners to spread on the activator element via v-bind. Only includes listeners relevant to the active open strategy (onClick, onMouseenter/leave, onFocus/Blur, onContextmenu).', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3eaf35d5-3f48-41e2-a59e-9801fde7cd01', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'contentEvents', 'ComputedRef<Record<string, EventListener>>', '', 'Event listeners to spread on the overlay content panel. Handles hover-sustain (keep open while cursor is inside the content), focus-in/out relay, and closeOnContentClick.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c5574220-9667-432a-bd73-c52aa5245691', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e753a11b-63aa-467e-ac53-aa91606440e9', 'scrimEvents', 'ComputedRef<Record<string, EventListener>>', '', 'Event listeners for the backdrop scrim element. Sustains hover-open when the cursor moves from the activator to the scrim before reaching the content.', 7, false, NULL, NULL);
