INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('de114644-a305-4417-a265-981c4c1eb708', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '7ffa0864-b7e9-4a83-9f4f-13cc082130a3', 'toggleSelect', '(item: IDataTableSelectableItem) => void', '', 'Toggle the selection state of a single item.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('484258b4-7c61-4c9a-b3e5-0b6682a0eff1', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '7ffa0864-b7e9-4a83-9f4f-13cc082130a3', 'selectAll', '(value: boolean) => void', '', 'Select or deselect all eligible items according to the active strategy. Strategy page selects only the current page; strategy all selects across all pages.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ceedc9ad-2a83-42af-9daf-a6dd5fcd8552', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '7ffa0864-b7e9-4a83-9f4f-13cc082130a3', 'someSelected', 'ComputedRef<boolean>', '', 'True when the selected Set is non-empty. Used to render the indeterminate state on the select-all checkbox.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c1007720-e336-4ac0-9285-eecfe1f4843c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '7ffa0864-b7e9-4a83-9f4f-13cc082130a3', 'allSelected', 'ComputedRef<boolean>', '', 'True when all eligible items (non-disabled) are selected according to the active strategy.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54d1f4e4-3799-495e-962e-a65da113e9d5', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '7ffa0864-b7e9-4a83-9f4f-13cc082130a3', 'showSelectAll', 'ComputedRef<boolean>', '', 'Whether the select-all checkbox should be visible. Always false for the single select strategy.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd97a817-be33-47a5-801c-32f3e55e202d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c2688729-4cec-446f-a315-9d61d51cb759', 'currentSnap', 'Ref<TSheetSnapId>', '', 'The id of the currently active snap point. Writable — programmatically call snapTo() or assign directly. Kept in sync with options.defaultSnap via a watcher.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('adc15722-3bf1-42f9-86bf-05126285a133', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c2688729-4cec-446f-a315-9d61d51cb759', 'dragOffset', 'ShallowRef<number>', '', 'Live pixel offset from the baseline snap height during an active drag. Positive = sheet growing (finger moving up). Resets to 0 on pointer release. Bind to a CSS translateY to achieve 1:1 finger tracking.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c28fbbc4-765d-4a59-9064-ab680a870719', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c2688729-4cec-446f-a315-9d61d51cb759', 'isDragging', 'ShallowRef<boolean>', '', 'True while a pointer is captured by the handle. Use it to suppress the sheet transition (transition: none) so the user sees immediate 1:1 tracking instead of the animated snap.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f274b5df-3b66-4fea-b486-7d32aef985fc', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c2688729-4cec-446f-a315-9d61d51cb759', 'snapTo', '(id: TSheetSnapId) => void', '', 'Programmatically move to a named snap point. Respects the persistent constraint (cannot snap to closed when persistent=true). Resets dragOffset to 0.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('078fc1fa-4584-4ffb-a3ea-4b8c41264b8d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c2688729-4cec-446f-a315-9d61d51cb759', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('10fe86a8-f4f5-43bf-8a1d-76ad046eef79', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c2688729-4cec-446f-a315-9d61d51cb759', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d10ddc5e-4b13-4602-955c-6cba04fe4a69', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3d598245-27f2-4891-8e4f-0fe9a67ec164', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('88d1a1e3-1783-4ad2-bd3d-1852b9c3f0ad', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3d598245-27f2-4891-8e4f-0fe9a67ec164', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9dc299f5-3f3f-439a-b79e-67e607bdf912', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '17eded95-9d67-414c-99b2-779a95eb505d', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('53354a59-c60c-4376-a52c-d5835d8da31b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '17eded95-9d67-414c-99b2-779a95eb505d', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2dd3dc4b-d359-4b89-a7b7-672369facfeb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '17eded95-9d67-414c-99b2-779a95eb505d', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('75bb6ba4-784d-432c-95db-5ab4375fb918', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '17eded95-9d67-414c-99b2-779a95eb505d', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('545627ed-e7f2-4f6b-bdd0-1f3957931b4c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '17eded95-9d67-414c-99b2-779a95eb505d', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ed1b9629-169e-423f-993b-c75c82b1e94f', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b0a8d910-55e5-4fe7-824e-f4c28afec12f', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6b0c7c99-1a61-4e7f-968e-1662b23b7992', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b0a8d910-55e5-4fe7-824e-f4c28afec12f', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('98f1cb16-1291-43ef-a0a9-fc8b0e4dab57', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b0a8d910-55e5-4fe7-824e-f4c28afec12f', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('90214d33-22e8-4a14-b4a3-7e5c94ff9c1b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b0a8d910-55e5-4fe7-824e-f4c28afec12f', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e3a56a3-9620-4269-b8e6-1106b4c7f011', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '9c7f3ab1-df79-4060-b124-3f392090a750', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('160475e3-b7e4-4faf-8750-98aa8db69339', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '9c7f3ab1-df79-4060-b124-3f392090a750', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2e716ce3-7aed-44bd-b7ec-2ecc0ea5567e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '9c7f3ab1-df79-4060-b124-3f392090a750', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ef56df92-1617-4ea0-977c-bf60b7c299cd', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '9c7f3ab1-df79-4060-b124-3f392090a750', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c22622c5-bc29-457f-b1d7-a7db87c6e675', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e989ac81-8c0e-4660-8bce-e355f011c80a', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('615c603b-d390-4390-b9eb-bfc27c4426ce', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e989ac81-8c0e-4660-8bce-e355f011c80a', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2bcb1818-285e-4e90-b07d-403a2b8c3ac7', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e989ac81-8c0e-4660-8bce-e355f011c80a', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b07eccc9-2c4b-4dfd-a04d-a37de97ade98', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'f84e710f-9948-4aed-92a0-d59b1d6dd5e1', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3fb00656-07ee-4a47-814a-094a3df6fa40', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'f84e710f-9948-4aed-92a0-d59b1d6dd5e1', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('deb1c0c8-bcb4-4f23-ba52-f9575cff1fdf', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '0f6b2e16-3d5f-4f07-bd42-a9acaa42d6e4', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4dc7e795-fa08-409f-ac27-d7e7d92eac03', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '844687a5-ca5d-449d-8505-c414e3383e34', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('84ad1069-c35c-4f98-a113-ae864005a8c3', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '844687a5-ca5d-449d-8505-c414e3383e34', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('39d44848-6385-4198-bf9f-e9da2b617e39', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '844687a5-ca5d-449d-8505-c414e3383e34', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4f4bd684-69d9-498c-86cd-b1a27fedf6ea', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('57ec5acc-e32e-48a6-8720-67e0aad50391', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3f4e927e-dff4-4992-8fc0-efc6f78c7ee3', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6bd228c9-82ee-4cfc-8cba-b85ffcde5b2c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('13c91518-0837-4d57-9955-f832d00d8664', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4726c9db-2845-47dd-bbdd-ed8305a785d4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6eed6e7e-9daa-4107-a1b3-df00c10aa473', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'b83eb313-49c2-4e95-b5ff-c5cc096dca70', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('44ffd945-472a-49b0-8f3a-7cf3a6df7be3', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3a6ead70-bfb0-46ff-83b2-81d990dc77b7', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('df92b2ef-a9f2-4cf8-8fbb-6213bc399a55', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3a6ead70-bfb0-46ff-83b2-81d990dc77b7', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2862d69e-df94-401c-a3ec-64abb75cd804', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3a6ead70-bfb0-46ff-83b2-81d990dc77b7', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2890d454-66ae-421e-8980-2beb7e769441', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3a6ead70-bfb0-46ff-83b2-81d990dc77b7', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0b0469a5-1a84-4117-897f-ecd1864483da', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '3a6ead70-bfb0-46ff-83b2-81d990dc77b7', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fa028195-74b2-45d0-a2bc-242669548d9c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4c46fd30-6da0-4b17-973d-ceffdbc65fc9', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ce5218ee-0ecd-4fcd-8bf8-522b410a083d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4c46fd30-6da0-4b17-973d-ceffdbc65fc9', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e595966-baa1-4ed1-aefc-8911c371f017', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a3473b0f-0c26-4c9f-ba25-71195dfa1a79', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f5d0a72a-16bf-47a9-80ec-18aa11e9b8cd', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a3473b0f-0c26-4c9f-ba25-71195dfa1a79', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('422aae1d-e910-42b0-9c88-cead2b1ab02d', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a3473b0f-0c26-4c9f-ba25-71195dfa1a79', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('84fb2776-cf64-40a9-9508-94c430cfa86c', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'a3473b0f-0c26-4c9f-ba25-71195dfa1a79', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b19868c1-b003-42bd-af41-45af30f67efd', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'd0d553d0-57dc-402f-9c16-d9640506794a', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb64c9ae-3f50-466f-9819-d979b10075e9', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '891e3cc3-7783-4daf-9bad-bf185a1c3b04', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fe41551c-5e6b-46d6-a51e-9e1cc05574c0', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '891e3cc3-7783-4daf-9bad-bf185a1c3b04', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('78dc83be-454c-4c45-a72d-a2fa792e581b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '891e3cc3-7783-4daf-9bad-bf185a1c3b04', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('65fd6e56-9d42-488b-ad71-dc599ddbebb5', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '891e3cc3-7783-4daf-9bad-bf185a1c3b04', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1d60c11f-3819-4da1-9815-53f66a55c3d4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '891e3cc3-7783-4daf-9bad-bf185a1c3b04', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4d5400d7-ac0c-4385-a91a-186a55f7b6dc', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '891e3cc3-7783-4daf-9bad-bf185a1c3b04', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5a7677fe-179e-453a-acd1-721cc71a5ce9', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '2dedac23-93a2-4659-9973-1b4307645558', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ff6e131-5431-4cc7-bad3-3c02e59abbcb', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '2dedac23-93a2-4659-9973-1b4307645558', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('66d5464d-90cd-4d8d-b84a-22b2c1169300', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'f1426a77-2bda-42d0-9a41-edc59f688631', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
