INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c017e2d4-2030-47e8-82d9-25c66aa6d8db', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c6d0211d-3a2e-45a9-a6fd-2910f3a06828', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1ae85634-fb52-4991-a6e8-ce853e8bc3c9', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c6d0211d-3a2e-45a9-a6fd-2910f3a06828', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e3dd7d3c-d67f-4c0e-b516-0ef6d36dd7d5', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c6d0211d-3a2e-45a9-a6fd-2910f3a06828', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c6323c55-67ff-4967-8b53-ae525d1d4cac', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'c6d0211d-3a2e-45a9-a6fd-2910f3a06828', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c2b96588-35c0-4f20-94d9-e609971c0ca1', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '22a52856-27e4-4fba-acbc-4d4bcd81ff6a', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('27d29135-f398-4bdc-a1dc-6f73d44bf453', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e894e743-ccbe-4f83-bb8c-30046bd2b3b2', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6683589c-a95e-4b58-8334-fb111143f0c6', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e894e743-ccbe-4f83-bb8c-30046bd2b3b2', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ec2abcf6-1d5b-4865-8232-fd185e13d58b', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'e894e743-ccbe-4f83-bb8c-30046bd2b3b2', 'uninstall', '() => void', '', 'Remove the injected layer and disconnect the MutationObserver if active. Called automatically on scope dispose.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a7974247-6e49-4792-bf7a-9fff3ce3e798', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', 'ec9a22a2-e775-4a93-93f1-607e6f624356', 'peaks', 'Ref<Array<number>>', '', 'Array of `bins` values in [0, 1], where 1 is the loudest bucket in the track. Empty while computing or on error.', 0, false, NULL, NULL);
