INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f28bc28c-8339-4dcf-b6c0-3ae0ccb3115e', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '8506efdc-3b68-408a-b50c-37c304d81912', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ae27e030-9dd6-41cb-9b6d-9de780fc27ca', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4e4a8149-4c7b-43ba-9a8b-cc9610cc940a', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('97bdfd08-aa20-48b2-b3cc-85ec00f37de8', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4e4a8149-4c7b-43ba-9a8b-cc9610cc940a', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ae55a2b0-93c3-4f4d-bf3d-bf581dfbbba4', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4e4a8149-4c7b-43ba-9a8b-cc9610cc940a', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a665077e-e614-4ae4-aae1-115c15946033', '2026-11-11 21:53:00.583474+00', '2026-11-11 21:53:00.583474+00', '4e4a8149-4c7b-43ba-9a8b-cc9610cc940a', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
